STORIES.splice(0,STORIES.length,...[{"id":"a1-cafe-manana","level":"A1","title":"قهوة الصباح","desc":"تطلب لونا قهوة وفطورًا في مقهى صغير قبل العمل.","lines":[{"speaker":"paco","es":"Buenos días, ¿qué va a tomar?","ar":"صباح الخير، ماذا ستأخذين؟"},{"speaker":"luna","es":"Buenos días. Un café con leche, por favor.","ar":"صباح الخير. قهوة بالحليب من فضلك."},{"speaker":"paco","es":"¿Algo más? Tenemos cruasanes.","ar":"أي شيء آخر؟ لدينا كرواسان."},{"speaker":"luna","es":"Sí, un cruasán también.","ar":"نعم، كرواسان أيضًا."},{"speaker":"paco","es":"¿Para aquí o para llevar?","ar":"هنا أم للأخذ؟"},{"speaker":"luna","es":"Para llevar, gracias.","ar":"للأخذ، شكرًا."},{"speaker":"paco","es":"Son tres euros con cincuenta.","ar":"ثلاثة يورو ونصف."},{"speaker":"luna","es":"Aquí tiene. ¡Que tenga buen día!","ar":"تفضّل. نهارك سعيد!"}],"questions":[{"q":"ماذا طلبت لونا؟","options":["قهوة بالحليب وكرواسان","عصير برتقال فقط","شاي وكعكة"],"answer":"قهوة بالحليب وكرواسان","rationale":"قالت «Un café con leche» و«un cruasán también»، أي قهوة بالحليب وكرواسان. لم يُذكر شاي ولا عصير في الحوار."},{"q":"أين ستأخذ لونا الطلب؟","options":["في العمل","للأخذ","هنا في المقهى"],"answer":"للأخذ","rationale":"قالت «Para llevar» أي للأخذ. أما «Para aquí» فكانت ستعني هنا، ولم يُذكر العمل."},{"q":"كم الحساب؟","options":["خمسة يورو","ثلاثة عشر يورو","ثلاثة يورو ونصف"],"answer":"ثلاثة يورو ونصف","rationale":"«tres euros con cincuenta» أي ثلاثة يورو ونصف. أما الخمسة والثلاثة عشر فلم يُذكرا."},{"q":"من يأخذ الطلب؟","options":["باكو","زبون آخر","لونا"],"answer":"باكو","rationale":"باكو هو الذي سأل «¿qué va a tomar?» وقال الحساب، فهو الذي يأخذ الطلب. ولونا هي الزبونة."}]},{"id":"a1-camino-metro","level":"A1","title":"الطريق إلى المترو","desc":"تسأل لونا في الشارع عن محطة المترو.","lines":[{"speaker":"luna","es":"Perdone, ¿dónde está el metro?","ar":"من فضلك، أين المترو؟"},{"speaker":"paco","es":"¿El metro? Siga todo recto.","ar":"المترو؟ امشي إلى الأمام مباشرة."},{"speaker":"luna","es":"¿Todo recto?","ar":"إلى الأمام مباشرة؟"},{"speaker":"paco","es":"Sí, y luego gire a la izquierda.","ar":"نعم، ثم انعطفي يسارًا."},{"speaker":"luna","es":"¿Está lejos?","ar":"هل هو بعيد؟"},{"speaker":"paco","es":"No, está muy cerca. Dos minutos.","ar":"لا، إنه قريب جدًا. دقيقتان."},{"speaker":"luna","es":"Muchas gracias.","ar":"شكرًا جزيلًا."},{"speaker":"paco","es":"De nada. Adiós.","ar":"عفوًا. مع السلامة."}],"questions":[{"q":"عمّ تبحث لونا؟","options":["التاكسي","الحافلة","المترو"],"answer":"المترو","rationale":"سألت «¿dónde está el metro?» أي إنها تبحث عن المترو. ولم تُذكر الحافلة ولا التاكسي."},{"q":"كيف تمشي لونا في البداية؟","options":["إلى اليمين","إلى الأمام مباشرة","إلى اليسار"],"answer":"إلى الأمام مباشرة","rationale":"«Todo recto» أي إلى الأمام مباشرة. لم يُذكر اليمين، وأما اليسار فيأتي لاحقًا."},{"q":"وبعد ذلك إلى أين تذهب؟","options":["إلى الأمام مباشرة مرة أخرى","إلى اليمين","إلى اليسار"],"answer":"إلى اليسار","rationale":"«gire a la izquierda» أي انعطفي يسارًا. اليمين خطأ لأن izquierda تعني اليسار."},{"q":"هل المترو قريب أم بعيد؟","options":["بعيد، عشرون دقيقة","قريب، دقيقتان","قريب، عشر دقائق"],"answer":"قريب، دقيقتان","rationale":"قال «está muy cerca. Dos minutos» أي إنه قريب جدًا، دقيقتان. ولم تُذكر الأرقام الأخرى."}]},{"id":"a1-mercado-fruta","level":"A1","title":"في السوق","desc":"تشتري لونا فاكهة من السوق وتسأل عن الأسعار.","lines":[{"speaker":"luna","es":"Hola, ¿a cuánto están los plátanos?","ar":"أهلًا، بكم الموز؟"},{"speaker":"paco","es":"A dos euros el kilo.","ar":"بيوروين للكيلو."},{"speaker":"luna","es":"Vale. ¿Y las manzanas?","ar":"حسنًا. والتفاح؟"},{"speaker":"paco","es":"Las manzanas, a uno ochenta.","ar":"التفاح بيورو وثمانين."},{"speaker":"luna","es":"Quiero un kilo de plátanos, por favor.","ar":"أريد كيلو من الموز من فضلك."},{"speaker":"paco","es":"¿Algo más?","ar":"أي شيء آخر؟"},{"speaker":"luna","es":"No, nada más. ¿Cuánto es?","ar":"لا، هذا كل شيء. كم الحساب؟"},{"speaker":"paco","es":"Dos euros.","ar":"يورو‌ان."},{"speaker":"luna","es":"Tome. Gracias, adiós.","ar":"تفضّل. شكرًا، مع السلامة."}],"questions":[{"q":"بكم كيلو الموز؟","options":["يورو‌ان","يورو وثمانون سنتًا","ثلاثة يورو"],"answer":"يورو‌ان","rationale":"«A dos euros el kilo» أي بيوروين للكيلو. واليورو والثمانون سعر التفاح لا الموز."},{"q":"بكم التفاح؟","options":["يورو‌ان","يورو وثمانون سنتًا","يورو واحد فقط"],"answer":"يورو وثمانون سنتًا","rationale":"«a uno ochenta» أي يورو وثمانون سنتًا. أما اليورو‌ان فسعر الموز."},{"q":"ماذا اشترت لونا في النهاية؟","options":["كيلو من الموز فقط","كيلو من التفاح","كيلو من الموز وكيلو من التفاح"],"answer":"كيلو من الموز فقط","rationale":"قالت «un kilo de plátanos» وسألت عن التفاح فقط دون أن تشتريه، وردّت على «¿Algo más?» بـ «No, nada más» أي هذا كل شيء."},{"q":"كم دفعت؟","options":["يورو وثمانين سنتًا","ثلاثة يورو وثمانين سنتًا","يورو‌ين"],"answer":"يورو‌ين","rationale":"كيلو الموز بيوروين، والبائع قال «Dos euros». أما الثلاثة يورو والثمانون فخطأ لأنها لم تشتر تفاحًا."}]},{"id":"a1-vecino-nuevo","level":"A1","title":"جار جديد","desc":"تتعرّف لونا إلى جارها الجديد في المصعد.","lines":[{"speaker":"luna","es":"¡Hola! ¿Eres nuevo en el edificio?","ar":"أهلًا! هل أنت جديد في العمارة؟"},{"speaker":"paco","es":"Sí, me llamo Paco. Vivo en el tercero.","ar":"نعم، اسمي باكو. أسكن في الطابق الثالث."},{"speaker":"luna","es":"Encantada, Paco. Yo soy Luna, del segundo.","ar":"تشرّفنا يا باكو. أنا لونا، من الطابق الثاني."},{"speaker":"paco","es":"Encantado, Luna. ¿Llevas mucho tiempo aquí?","ar":"تشرّفنا يا لونا. هل تسكنين هنا منذ زمن طويل؟"},{"speaker":"luna","es":"Sí, dos años.","ar":"نعم، منذ سنتين."},{"speaker":"paco","es":"¿Y trabajas cerca?","ar":"وهل تعملين قريبًا من هنا؟"},{"speaker":"luna","es":"Sí, trabajo en una farmacia, al lado del metro.","ar":"نعم، أعمل في صيدلية بجانب المترو."},{"speaker":"paco","es":"¡Qué bien! Hasta luego, Luna.","ar":"جميل! أراك لاحقًا يا لونا."},{"speaker":"luna","es":"Hasta luego. ¡Bienvenido!","ar":"أراك لاحقًا. أهلًا بك!"}],"questions":[{"q":"في أي طابق يسكن باكو؟","options":["الرابع","الثاني","الثالث"],"answer":"الثالث","rationale":"قال «Vivo en el tercero» أي إنه يسكن في الطابق الثالث. أما الثاني فطابق لونا."},{"q":"منذ متى تسكن لونا هنا؟","options":["ثلاث سنوات","سنتين","سنة"],"answer":"سنتين","rationale":"قالت «dos años» أي إنها تسكن هنا منذ سنتين. ولم تُذكر السنة ولا الثلاث."},{"q":"أين تعمل لونا؟","options":["في صيدلية بجانب المترو","في سوبرماركت","في مقهى"],"answer":"في صيدلية بجانب المترو","rationale":"قالت «trabajo en una farmacia, al lado del metro» أي إنها تعمل في صيدلية بجانب المترو. ولم يُذكر المقهى ولا السوبرماركت."},{"q":"بماذا رحّبت لونا بباكو في النهاية؟","options":["«¡Buenas tardes!»","«¡Hasta mañana!»","«¡Bienvenido!»"],"answer":"«¡Bienvenido!»","rationale":"قالت «¡Bienvenido!» أي أهلًا بك. ولم يُقل مساء الخير ولا أراك غدًا."}]},{"id":"a2-paquete-otra-sucursal","level":"A2","title":"الطرد في الفرع الآخر","desc":"تذهب لونا لاستلام طردها فتكتشف أنه وصل إلى فرع آخر من المتجر نفسه.","lines":[{"speaker":"luna","es":"Buenos días. Vengo a recoger un paquete.","ar":"صباح الخير. جئت لأستلم طردًا."},{"speaker":"paco","es":"Buenos días. ¿Tiene el código de seguimiento?","ar":"صباح الخير. هل معكِ رقم التتبع؟"},{"speaker":"luna","es":"Sí, mire. Me llegó un mensaje ayer.","ar":"نعم، تفضّل. وصلتني رسالة أمس."},{"speaker":"paco","es":"Gracias... Mmm, qué raro. Este paquete no está aquí.","ar":"شكرًا... همم، غريب. هذا الطرد ليس هنا."},{"speaker":"luna","es":"¿Cómo que no está? El mensaje dice que es esta tienda.","ar":"كيف ليس هنا؟ الرسالة مكتوب فيها هذا المتجر."},{"speaker":"paco","es":"Ya lo veo, pero mire la dirección: es la otra sucursal, la de la calle Mayor.","ar":"أرى ذلك، لكن انظري إلى العنوان من فضلك: هذا هو الفرع الآخر، الذي في شارع مايور."},{"speaker":"luna","es":"¡Ay, es verdad! No leí bien el mensaje.","ar":"آه، صحيح! لم أقرأ الرسالة جيدًا."},{"speaker":"paco","es":"No pasa nada, le pasa a mucha gente. Las dos sucursales tienen el mismo nombre, por eso pasa.","ar":"لا بأس، يحدث هذا مع كثير من الناس. للفرعين الاسم نفسه، ولذلك يحدث هذا."},{"speaker":"luna","es":"¿Y puedo recogerlo allí hoy?","ar":"وهل أستطيع استلامه من هناك اليوم؟"},{"speaker":"paco","es":"Sí, claro. Cierran a las nueve. Voy a llamar a la otra sucursal para avisar.","ar":"نعم بالطبع. يغلقون في الساعة التاسعة. سأتصل بالفرع الآخر لأبلغهم."},{"speaker":"luna","es":"Muy amable. ¿Sabe si hay un metro cerca?","ar":"أنت لطيف جدًا. هل تعرف مترو قريبًا؟"},{"speaker":"paco","es":"Sí, la estación de Ópera está a cinco minutos a pie.","ar":"نعم، محطة أوبرا على بُعد خمس دقائق سيرًا."},{"speaker":"luna","es":"Perfecto. Entonces paso por allí después del trabajo.","ar":"حسنًا. إذن سأمرّ عليه بعد العمل."},{"speaker":"paco","es":"De acuerdo. ¡Que tenga buen día!","ar":"حسنًا. نهارك سعيد!"},{"speaker":"luna","es":"Gracias, igualmente.","ar":"شكرًا، وأنت أيضًا."}],"questions":[{"q":"لماذا ذهبت لونا إلى المتجر؟","options":["لتشتري هدية","لتستلم طردًا","لتقدّم شكوى"],"answer":"لتستلم طردًا","rationale":"أول جملة قالتها «Vengo a recoger un paquete» أي جئت لأستلم طردًا. ولم تُذكر هدية ولا شكوى."},{"q":"لماذا الطرد غير موجود في هذا المتجر؟","options":["وصل إلى فرع آخر له اسم المتجر نفسه","ما زال في الطريق","أُعيد إلى المرسل"],"answer":"وصل إلى فرع آخر له اسم المتجر نفسه","rationale":"وجد الموظف أن العنوان في الرسالة هو عنوان الفرع الآخر، وقال «Las dos sucursales tienen el mismo nombre». ولم يُذكر تأخير ولا إرجاع."},{"q":"ما سبب الخلط؟","options":["الموظف أضاع الطرد","شركة الشحن أخطأت","لونا لم تقرأ العنوان جيدًا"],"answer":"لونا لم تقرأ العنوان جيدًا","rationale":"لونا نفسها قالت «No leí bien el mensaje» أي إنها هي التي لم تقرأ الرسالة جيدًا. ولم يقل أحد إن الموظف أضاع الطرد أو إن الشحن أخطأ."},{"q":"ماذا فعل الموظف ليساعد لونا؟","options":["سيرسل الطرد إلى بيتها","سيتصل بالفرع الآخر ليبلغهم","قال لها تعالي غدًا"],"answer":"سيتصل بالفرع الآخر ليبلغهم","rationale":"قال «Voy a llamar a la otra sucursal para avisar» أي سيتصل بالفرع الآخر ليبلغهم. ولم يُذكر توصيل إلى البيت."},{"q":"متى وأين ستستلم لونا الطرد؟","options":["اليوم من الفرع الآخر بعد العمل","غدًا من المتجر نفسه","حين يصل إلى هنا بعد يومين"],"answer":"اليوم من الفرع الآخر بعد العمل","rationale":"قالت «paso por allí después del trabajo» أي ستمرّ عليه بعد العمل، وكلمة «allí» تشير إلى الفرع الآخر."},{"q":"في أي ساعة يغلق الفرع الآخر؟","options":["في الساعة الخامسة","في الساعة الثانية عشرة","في الساعة التاسعة"],"answer":"في الساعة التاسعة","rationale":"قال «Cierran a las nueve» أي يغلقون في الساعة التاسعة. ولم تُذكر الخامسة ولا الثانية عشرة."}]},{"id":"a2-cita-doctor","level":"A2","title":"موعد الطبيب","desc":"تتصل لونا بالعيادة لتغيّر موعد كشفها.","lines":[{"speaker":"paco","es":"Clínica Sol, buenos días.","ar":"عيادة سول، صباح الخير."},{"speaker":"luna","es":"Buenos días. Tengo una cita mañana y quiero cambiarla.","ar":"صباح الخير. عندي موعد غدًا وأريد تغييره."},{"speaker":"paco","es":"Muy bien. ¿A qué hora es su cita?","ar":"حسنًا. في أي ساعة موعدك؟"},{"speaker":"luna","es":"A las diez, con la doctora Ruiz.","ar":"في الساعة العاشرة، مع الدكتورة رويث."},{"speaker":"paco","es":"Sí, aquí está. ¿Qué día le viene bien?","ar":"نعم، وجدته. أي يوم يناسبك؟"},{"speaker":"luna","es":"¿Es posible el jueves por la tarde?","ar":"هل يمكن يوم الخميس بعد الظهر؟"},{"speaker":"paco","es":"El jueves... hay un hueco libre a las cinco y media.","ar":"الخميس... يوجد موعد فارغ في الساعة الخامسة والنصف."},{"speaker":"luna","es":"Perfecto, me viene muy bien.","ar":"حسنًا، هذا يناسبني جدًا."},{"speaker":"paco","es":"Entonces, el jueves a las cinco y media con la doctora Ruiz.","ar":"إذن الخميس في الساعة الخامسة والنصف مع الدكتورة رويث."},{"speaker":"luna","es":"Muy bien. ¿Tengo que traer algo?","ar":"حسنًا. هل يجب أن أحضر شيئًا معي؟"},{"speaker":"paco","es":"Solo su tarjeta sanitaria.","ar":"فقط بطاقة التأمين الصحي الخاصة بك."},{"speaker":"luna","es":"De acuerdo. Muchas gracias.","ar":"حسنًا. شكرًا جزيلًا."},{"speaker":"paco","es":"A usted. Hasta el jueves.","ar":"عفوًا. نراك يوم الخميس."}],"questions":[{"q":"لماذا تتصل لونا بالعيادة؟","options":["لتلغي الموعد نهائيًا","لتغيّر موعدها","لتحجز موعدًا جديدًا"],"answer":"لتغيّر موعدها","rationale":"قالت «quiero cambiarla» أي أريد تغيير الموعد، لا إلغاءه. والموعد موجود أصلًا، فليس حجزًا جديدًا."},{"q":"متى كان موعدها الأصلي؟","options":["الخميس في الساعة الخامسة","غدًا في الساعة الخامسة والنصف","غدًا في الساعة العاشرة"],"answer":"غدًا في الساعة العاشرة","rationale":"قالت «Tengo una cita mañana» و«A las diez» أي غدًا في الساعة العاشرة. أما الخامسة والنصف فهو الموعد الجديد."},{"q":"متى الموعد الجديد إذن؟","options":["الخميس في الساعة الخامسة والنصف","الجمعة في الساعة الخامسة","الخميس في الساعة العاشرة"],"answer":"الخميس في الساعة الخامسة والنصف","rationale":"قال الموظف «el jueves... a las cinco y media» ووافقت لونا. ولم يُذكر الجمعة إطلاقًا."},{"q":"ماذا يجب أن تحضر معها؟","options":["أجرة الكشف نقدًا","بطاقة التأمين الصحي","تحاليل قديمة"],"answer":"بطاقة التأمين الصحي","rationale":"قال «Solo su tarjeta sanitaria» أي فقط بطاقة التأمين الصحي. ولم يُذكر مال ولا تحاليل."},{"q":"ما اسم الطبيبة التي تكشف على لونا؟","options":["سول","لونا","رويث"],"answer":"رويث","rationale":"«con la doctora Ruiz» أي مع الدكتورة رويث. أما سول فاسم العيادة، ولونا هي المريضة."}]},{"id":"a2-farmacia-resfriado","level":"A2","title":"عند الصيدلي","desc":"باكو مريض ويشرح للصيدلانية أعراض الزكام التي عنده.","lines":[{"speaker":"luna","es":"Buenas tardes, ¿qué necesita?","ar":"مساء الخير، ماذا تحتاج؟"},{"speaker":"paco","es":"Buenas. Estoy resfriado desde ayer.","ar":"مساء الخير. أنا مصاب بزكام منذ أمس."},{"speaker":"luna","es":"¿Qué síntomas tiene?","ar":"ما الأعراض التي عندك؟"},{"speaker":"paco","es":"Me duele la garganta y tengo tos.","ar":"حلقي يؤلمني وعندي سعال."},{"speaker":"luna","es":"¿Tiene fiebre?","ar":"هل عندك حمّى؟"},{"speaker":"paco","es":"No, fiebre no tengo.","ar":"لا، ليست عندي حمّى."},{"speaker":"luna","es":"Vale. Le doy un jarabe para la tos y pastillas para la garganta.","ar":"حسنًا. سأعطيك شراب سعال وأقراصًا للحلق."},{"speaker":"paco","es":"¿Cómo se toman?","ar":"كيف آخذهما؟"},{"speaker":"luna","es":"El jarabe y las pastillas, como pone en el prospecto. Cualquier duda, me pregunta.","ar":"الشراب والأقراص كما هو مكتوب في النشرة التي في العلبة. وإن كان عندك أي سؤال فاسألني."},{"speaker":"paco","es":"¿Y cuándo me voy a encontrar mejor?","ar":"ومتى سأتحسّن؟"},{"speaker":"luna","es":"Depende. Si los síntomas empeoran o no mejora, vaya al médico.","ar":"هذا يختلف. إن زادت الأعراض أو لم يحدث تحسّن، فاذهب إلى الطبيب."},{"speaker":"paco","es":"Muy bien. ¿Cuánto es todo?","ar":"حسنًا. كم الحساب كله؟"},{"speaker":"luna","es":"Doce euros con sesenta.","ar":"اثنا عشر يورو وستون سنتًا."},{"speaker":"paco","es":"Aquí tiene. Gracias.","ar":"تفضّلي. شكرًا."}],"questions":[{"q":"ما بال باكو؟","options":["مصاب بزكام منذ أمس","معدته تؤلمه من طعام الليلة الماضية","ظهره يؤلمه من العمل والوقوف الطويل"],"answer":"مصاب بزكام منذ أمس","rationale":"قال «Estoy resfriado desde ayer» أي إنه مصاب بزكام منذ أمس. ولم تُذكر معدة ولا ظهر."},{"q":"ما أعراضه؟","options":["سعال جاف وحمّى مرتفعة منذ الصباح","ألم في الحلق وسعال","حمّى وصداع شديد منذ يومين"],"answer":"ألم في الحلق وسعال","rationale":"قال «Me duele la garganta y tengo tos» ونفى الحمّى: «fiebre no tengo». فأي اختيار فيه حمّى خطأ."},{"q":"ماذا أعطته الصيدلانية؟","options":["قطرة للعين ومرهمًا لألم الظهر","مضادًا حيويًا وخافضًا للحرارة والصداع","شراب سعال وأقراصًا للحلق"],"answer":"شراب سعال وأقراصًا للحلق","rationale":"قالت «un jarabe para la tos y pastillas para la garganta». ولم يُذكر مضاد حيوي ولا قطرة."},{"q":"كيف قالت الصيدلانية لباكو أن يأخذ الدواء؟","options":["كما هو مكتوب في النشرة داخل العلبة","من عنده ودون أن يسأل الصيدلانية إطلاقًا","كما قال له صديقه أمس ودون أن يسأل أحدًا"],"answer":"كما هو مكتوب في النشرة داخل العلبة","rationale":"قالت «como pone en el prospecto» أي كما هو مكتوب في النشرة، وإن كان عنده سؤال فليسألها. ولم تُذكر مواعيد محددة."},{"q":"متى قالت له الصيدلانية أن يذهب إلى الطبيب؟","options":["بعد أن ينتهي من الدواء كله مهما كان شعوره","إن زادت الأعراض أو لم يحدث تحسّن","إن أراد شراء دواء آخر من النوع نفسه"],"answer":"إن زادت الأعراض أو لم يحدث تحسّن","rationale":"قالت «Si los síntomas empeoran o no mejora, vaya al médico» أي إن زادت الأعراض أو لم يتحسّن فليذهب إلى الطبيب. ولم يحدد أحد موعدًا معينًا."},{"q":"كم دفع في النهاية؟","options":["يوروان وستون سنتًا","عشرون يورو وخمسة وسبعون سنتًا","اثنا عشر يورو وستون سنتًا"],"answer":"اثنا عشر يورو وستون سنتًا","rationale":"«Doce euros con sesenta» أي اثنا عشر يورو وستون سنتًا. وكلمة doce تعني اثني عشر لا اثنين."}]},{"id":"a2-tren-perdido","level":"A2","title":"فات القطار","desc":"يصل باكو إلى المحطة متأخرًا فيجد القطار قد انطلق، ويبحث عن حل.","lines":[{"speaker":"paco","es":"¡Qué mala suerte! He perdido el tren de las nueve.","ar":"حظي سيئ جدًا! فاتني قطار التاسعة."},{"speaker":"luna","es":"¿A qué hora ha llegado usted?","ar":"في أي ساعة وصلت؟"},{"speaker":"paco","es":"A las nueve y cinco. El autobús llegó tarde.","ar":"في التاسعة وخمس دقائق. تأخرت الحافلة."},{"speaker":"luna","es":"Entiendo. ¿Adónde viaja?","ar":"فهمت. إلى أين تسافر؟"},{"speaker":"paco","es":"A Valencia. Tengo una reunión a las doce.","ar":"إلى فالنسيا. عندي اجتماع في الساعة الثانية عشرة."},{"speaker":"luna","es":"Hay otro tren a las nueve y media. Llega a las once y veinte.","ar":"يوجد قطار آخر في التاسعة والنصف. يصل في الحادية عشرة والعشرين."},{"speaker":"paco","es":"¿Y llego a tiempo para la reunión?","ar":"وهل سألحق بالاجتماع؟"},{"speaker":"luna","es":"Sí, si sale de la estación rápido. Hay taxis en la puerta.","ar":"نعم، إن خرجت من المحطة بسرعة. توجد سيارات أجرة عند الباب."},{"speaker":"paco","es":"Vale, quiero un billete para ese tren.","ar":"حسنًا، أريد تذكرة لهذا القطار."},{"speaker":"luna","es":"¿Su billete anterior era flexible?","ar":"هل كانت تذكرتك القديمة قابلة للتعديل؟"},{"speaker":"paco","es":"Sí, era flexible.","ar":"نعم، كانت قابلة للتعديل."},{"speaker":"luna","es":"Entonces el cambio es gratis. Aquí tiene su nuevo billete.","ar":"إذن التغيير مجاني. تفضّل تذكرتك الجديدة."},{"speaker":"paco","es":"¡Muchas gracias! Me ha salvado.","ar":"شكرًا جزيلًا! لقد أنقذتِني حقًا!"}],"questions":[{"q":"لماذا فات باكو القطار؟","options":["تأخرت الحافلة التي أقلّته","ذهب إلى محطة أخرى في طرف المدينة الآخر","نام واستيقظ متأخرًا من كثرة السهر تلك الليلة"],"answer":"تأخرت الحافلة التي أقلّته","rationale":"قال «El autobús llegó tarde» أي تأخرت الحافلة، وهذا سبب وصوله في التاسعة وخمس دقائق. ولم يُذكر نوم ولا محطة خطأ."},{"q":"إلى أين يسافر باكو ولماذا؟","options":["إلى فالنسيا في إجازة","إلى مدريد لحضور حفل زفاف","إلى فالنسيا لحضور اجتماع"],"answer":"إلى فالنسيا لحضور اجتماع","rationale":"قال «A Valencia. Tengo una reunión a las doce» أي إنه ذاهب إلى فالنسيا لاجتماع في الساعة الثانية عشرة، لا إلى إجازة."},{"q":"متى يغادر القطار الآخر ومتى يصل؟","options":["يغادر في التاسعة والنصف ويصل في الحادية عشرة والعشرين","يغادر في التاسعة ويصل في الحادية عشرة","يغادر في العاشرة ويصل في الثانية عشرة"],"answer":"يغادر في التاسعة والنصف ويصل في الحادية عشرة والعشرين","rationale":"«a las nueve y media... Llega a las once y veinte» أي يغادر في التاسعة والنصف ويصل في الحادية عشرة والعشرين، فسيصل قبل اجتماع الساعة الثانية عشرة."},{"q":"لماذا كان التغيير مجانيًا؟","options":["عرض خاص من الشركة للعملاء المميزين فقط","كانت تذكرته قابلة للتعديل","القطار نفسه تأخر عن موعده كثيرًا"],"answer":"كانت تذكرته قابلة للتعديل","rationale":"سألت الموظفة «¿era flexible?» ولما قال نعم قالت «el cambio es gratis». ولم يُذكر عرض خاص."},{"q":"بماذا نصحته الموظفة ليلحق بالاجتماع؟","options":["أن يؤجل الاجتماع","أن يركب حافلة أخرى","أن يخرج من المحطة بسرعة ويأخذ سيارة أجرة"],"answer":"أن يخرج من المحطة بسرعة ويأخذ سيارة أجرة","rationale":"قالت «si sale de la estación rápido» و«Hay taxis en la puerta». ولم تقل أن يؤجل الاجتماع."}]},{"id":"b1-piso-alquiler","level":"B1","title":"هل نسكن في الشقة أم لا؟","desc":"ترى لونا وباكو شقة للإيجار ويريدان أن يقرّرا، وكلٌّ منهما يرى شيئًا مختلفًا.","lines":[{"speaker":"luna","es":"Bueno, ¿qué te ha parecido el piso?","ar":"حسنًا، هل أعجبتك الشقة؟"},{"speaker":"paco","es":"A mí me ha encantado. Es grande y tiene mucha luz.","ar":"أعجبتني كثيرًا. واسعة وفيها نور كثير."},{"speaker":"luna","es":"Sí, es verdad, pero está un poco lejos del centro.","ar":"نعم صحيح، لكنها بعيدة قليلًا عن وسط المدينة."},{"speaker":"paco","es":"Ya, pero por eso es más barata. Con lo que ahorramos podemos pagar el transporte.","ar":"نعم، لكن لهذا السبب هي أرخص. ما سنوفّره يكفي للمواصلات."},{"speaker":"luna","es":"No sé... yo tardaría cuarenta minutos en llegar al trabajo.","ar":"لست متأكدة... سأحتاج إلى أربعين دقيقة لأصل إلى العمل."},{"speaker":"paco","es":"¿Y si nos mudamos y lo probamos unos meses? El contrato es de once meses.","ar":"حسنًا، لماذا لا نسكن ونجرّب بضعة أشهر؟ العقد أصلًا لأحد عشر شهرًا."},{"speaker":"luna","es":"Es que también me preocupa la cocina. Es muy pequeña.","ar":"المشكلة أنني قلقة من المطبخ أيضًا. إنه صغير جدًا."},{"speaker":"paco","es":"Hombre, pero tú casi no cocinas entre semana.","ar":"يا عزيزتي، لكنك أصلًا لا تطبخين في أيام الأسبوع."},{"speaker":"luna","es":"¡Eso no es verdad! Cocino casi todos los días.","ar":"هذا غير صحيح! أنا أطبخ كل يوم تقريبًا."},{"speaker":"paco","es":"Vale, vale, tienes razón. Entonces, ¿qué hacemos?","ar":"حسنًا حسنًا، معكِ حق. إذن ماذا نفعل؟"},{"speaker":"luna","es":"Mira, me gusta el piso, pero quiero ver otro que hay cerca del metro. Si no nos convence, nos quedamos con este.","ar":"اسمع، الشقة أعجبتني، لكنني أريد أن أرى شقة أخرى قرب المترو. وإن لم تعجبنا فسنأخذ هذه."},{"speaker":"paco","es":"Me parece justo. Pero hay que decidir rápido, que el dueño dijo que tiene más interesados.","ar":"كلامك منطقي. لكن يجب أن نقرّر بسرعة، فصاحب الشقة قال إن هناك أشخاصًا آخرين مهتمين."},{"speaker":"luna","es":"Vale. Mañana vemos el otro y por la noche decidimos.","ar":"حسنًا. غدًا نرى الأخرى وفي الليل نقرّر."},{"speaker":"paco","es":"Trato hecho.","ar":"اتفقنا."}],"questions":[{"q":"كيف يرى باكو الشقة؟","options":["صغيرة وغالية جدًا وفوق ميزانيتهما","قريبة من عملهما بعشر دقائق فقط","أعجبته كثيرًا: واسعة ومضيئة"],"answer":"أعجبته كثيرًا: واسعة ومضيئة","rationale":"قال «me ha encantado. Es grande y tiene mucha luz». والقرب من العمل ليس ميزتها، بل هو نقطة ضعفها عند لونا."},{"q":"ما مشكلتا لونا مع الشقة؟","options":["بعيدة عن وسط المدينة والمطبخ صغير","غالية والمصعد معطّل","النور قليل والشارع صاخب"],"answer":"بعيدة عن وسط المدينة والمطبخ صغير","rationale":"قالت «lejos del centro» و«la cocina... Es muy pequeña». والسعر أصلًا أرخص، والنور كثير بحسب كلام باكو."},{"q":"ما حجة باكو في أن البُعد ليس مشكلة؟","options":["لونا ستعمل من البيت","ما سيوفّرانه من الإيجار يكفي للمواصلات","سيشتري سيارة"],"answer":"ما سيوفّرانه من الإيجار يكفي للمواصلات","rationale":"قال «Con lo que ahorramos podemos pagar el transporte». ولم تُذكر سيارة ولا عمل من البيت."},{"q":"ما الاتفاق الذي توصّلا إليه في النهاية؟","options":["أن يريا شقة أخرى قرب المترو، وإن لم تعجبهما فيأخذان هذه","أن يبحثا في منطقة أخرى بعيدة عن وسط المدينة وأسعارها أرخص","أن يوقّعا على هذه الشقة فورًا دون تفكير"],"answer":"أن يريا شقة أخرى قرب المترو، وإن لم تعجبهما فيأخذان هذه","rationale":"اقترحت لونا «quiero ver otro que hay cerca del metro. Si no nos convence, nos quedamos con este» ووافق باكو: «Me parece justo»."},{"q":"لماذا يجب أن يقرّرا بسرعة؟","options":["لأن العقد سيبدأ الأسبوع القادم","لأن هناك أشخاصًا آخرين مهتمين بالشقة","لأن صاحب الشقة مسافر"],"answer":"لأن هناك أشخاصًا آخرين مهتمين بالشقة","rationale":"قال باكو «el dueño dijo que tiene más interesados» أي إن هناك مهتمين آخرين. ولم يُذكر سفر صاحب الشقة."},{"q":"كم مدة العقد المكتوبة؟","options":["سنة كاملة","ستة أشهر","أحد عشر شهرًا"],"answer":"أحد عشر شهرًا","rationale":"قال باكو «El contrato es de once meses» أي أحد عشر شهرًا. ولم تُذكر السنة الكاملة ولا الستة أشهر."}]},{"id":"b1-cumple-confundido","level":"B1","title":"حفلة مارتا: السبت أم الأحد؟","desc":"تظن لونا أن حفلة مارتا يوم الأحد ويظن باكو أنها يوم السبت، ويحاولان أن يفهما ما حدث.","lines":[{"speaker":"paco","es":"Oye, Luna, ¿has comprado ya el regalo para el sábado?","ar":"يا لونا، هل اشتريتِ هدية لحفلة السبت؟"},{"speaker":"luna","es":"¿Para el sábado? La fiesta de Marta es el domingo.","ar":"لماذا السبت؟ حفلة مارتا يوم الأحد."},{"speaker":"paco","es":"No, mujer, es el sábado. Me lo dijo ella misma.","ar":"لا، بل يوم السبت. هي نفسها قالت لي."},{"speaker":"luna","es":"Pues a mí me mandó un mensaje que ponía: «el domingo a las ocho».","ar":"حسنًا، وصلتني رسالة مكتوب فيها: «يوم الأحد في الساعة الثامنة»."},{"speaker":"paco","es":"Qué raro... A ver, enséñame el mensaje.","ar":"غريب... حسنًا، أرِني الرسالة."},{"speaker":"luna","es":"Mira. «El domingo a las ocho en mi casa».","ar":"انظر. «يوم الأحد في الساعة الثامنة في بيتي»."},{"speaker":"paco","es":"¡Ah, ya entiendo! Marta cambió el día. El sábado era el plan original.","ar":"آه، فهمت! مارتا غيّرت اليوم. كان السبت هو الخطة الأصلية."},{"speaker":"luna","es":"¿Y por qué no te avisó a ti?","ar":"ولماذا لم تُبلغك أنت؟"},{"speaker":"paco","es":"Pues... porque yo estaba sin móvil toda la semana, ¿no te acuerdas?","ar":"لأنني... كنت بلا هاتف طوال الأسبوع، ألا تتذكرين؟"},{"speaker":"luna","es":"¡Es verdad! Se te rompió la pantalla.","ar":"صحيح! كانت الشاشة قد انكسرت."},{"speaker":"paco","es":"Eso es. Menos mal que me lo has dicho, porque yo iba a aparecer allí el sábado con el regalo.","ar":"بالضبط. الحمد لله أنك أخبرتني، كنت سأذهب إلى هناك يوم السبت بالهدية."},{"speaker":"luna","es":"Imagina la cara de Marta. «Paco, la fiesta es mañana».","ar":"تخيّل وجه مارتا. «يا باكو، الحفلة غدًا»."},{"speaker":"paco","es":"Ja, ja. Bueno, el sábado entonces salimos nosotros, ¿no? Ya que estamos libres.","ar":"ها ها. حسنًا، يوم السبت نخرج نحن إذن، موافقة؟ فنحن فارغان أصلًا."},{"speaker":"luna","es":"¡Buena idea! Así no perdemos el plan.","ar":"فكرة جميلة! هكذا لا تضيع الخطة."}],"questions":[{"q":"ما سبب الخلط؟","options":["كلاهما نسي مكان الحفلة","لونا نسيت أن تحضر هدية","باكو يظن الحفلة يوم السبت ولونا تظنها يوم الأحد"],"answer":"باكو يظن الحفلة يوم السبت ولونا تظنها يوم الأحد","rationale":"قال باكو «es el sábado» وقالت لونا «es el domingo». والمكان والهدية ليسا سبب الخلط، فالخلط في اليوم فقط."},{"q":"ما الحقيقة؟","options":["مارتا غيّرت اليوم من السبت إلى الأحد","باكو أخطأ في قراءة الرسالة","لونا نسيت موعد الحفلة"],"answer":"مارتا غيّرت اليوم من السبت إلى الأحد","rationale":"فهم باكو: «Marta cambió el día. El sábado era el plan original». ولم يكن باكو مخطئًا، بل لم يعرف بالتغيير فقط."},{"q":"لماذا لم يعرف باكو بالتغيير؟","options":["كان مسافرًا","كان بلا هاتف طوال الأسبوع","نسيت مارتا أن تتصل به"],"answer":"كان بلا هاتف طوال الأسبوع","rationale":"قال «estaba sin móvil toda la semana» وذكّرته لونا بأن الشاشة انكسرت. ولم يُذكر سفر."},{"q":"ماذا كانت تقول رسالة مارتا للونا؟","options":["الأحد في الساعة الثامنة في بيتها","الأحد في الساعة العاشرة في بيتها","السبت في الساعة الثامنة في مطعم"],"answer":"الأحد في الساعة الثامنة في بيتها","rationale":"قرأت لونا: «El domingo a las ocho en mi casa». ولم يُذكر المطعم ولا الساعة العاشرة."},{"q":"ماذا سيحدث يوم السبت في النهاية؟","options":["سيذهب باكو إلى بيت مارتا بالهدية","سيذهبان إلى حفلة مارتا يوم السبت","ستخرج لونا وباكو وحدهما"],"answer":"ستخرج لونا وباكو وحدهما","rationale":"اقترح باكو «el sábado entonces salimos nosotros» لأنهما فارغان، ووافقت لونا. وحفلة مارتا يوم الأحد."}]},{"id":"b1-oferta-trabajo","level":"B1","title":"عرض العمل الجديد","desc":"تلقّت لونا عرض عمل جديد وتستشير باكو: مال أكثر أم راحة أكثر؟","lines":[{"speaker":"luna","es":"Paco, tengo que contarte algo. Me han ofrecido otro trabajo.","ar":"يا باكو، يجب أن أخبرك بشيء. وصلني عرض عمل آخر."},{"speaker":"paco","es":"¡Anda! ¿Dónde?","ar":"حقًا! أين؟"},{"speaker":"luna","es":"En una empresa grande, en las afueras. Pagan un veinte por ciento más.","ar":"في شركة كبيرة في أطراف المدينة. يدفعون أكثر بنسبة عشرين في المئة."},{"speaker":"paco","es":"¡Un veinte por ciento! Eso está muy bien.","ar":"عشرون في المئة! هذا جيد جدًا."},{"speaker":"luna","es":"Sí, pero tardaría una hora en llegar. Ahora tardo diez minutos andando.","ar":"نعم، لكنني سأحتاج إلى ساعة في الطريق. الآن أحتاج إلى عشر دقائق سيرًا."},{"speaker":"paco","es":"Buf, eso son dos horas al día. ¿Y el ambiente? ¿Has hablado con alguien de allí?","ar":"آه، هذه ساعتان في اليوم. حسنًا، وما الأجواء هناك؟ هل تحدثتِ مع أحد يعمل هناك؟"},{"speaker":"luna","es":"Sí, he hablado con una chica que trabaja allí. Dice que el ambiente es bueno, pero hay mucha presión.","ar":"نعم، تحدثت مع فتاة تعمل هناك. قالت إن الأجواء جيدة لكن فيها ضغطًا كثيرًا."},{"speaker":"paco","es":"¿Y en tu trabajo actual estás a gusto?","ar":"وهل أنتِ مرتاحة في عملك الحالي؟"},{"speaker":"luna","es":"La verdad es que sí. Me llevo bien con todos y el horario es flexible.","ar":"الحقيقة نعم. علاقتي جيدة بالجميع والمواعيد مرنة."},{"speaker":"paco","es":"Pues yo creo que tienes que pensar qué es más importante para ti ahora: el dinero o la tranquilidad.","ar":"أرى أنه يجب أن تفكّري فيما هو الأهم لكِ الآن: المال أم راحة البال."},{"speaker":"luna","es":"Es que necesito ahorrar. Quiero hacer un máster el año que viene.","ar":"المشكلة أنني أحتاج إلى أن أدّخر. أريد أن أدرس الماجستير العام القادم."},{"speaker":"paco","es":"Ah, eso cambia las cosas. Si ahorras ese veinte por ciento durante un año, ¿te llega?","ar":"آه، هذا يغيّر الأمر. إن ادخرتِ هذه العشرين في المئة سنة كاملة، فهل ستكفيكِ؟"},{"speaker":"luna","es":"Sí, me llega justo.","ar":"نعم، ستكفيني بالكاد."},{"speaker":"paco","es":"Entonces yo lo aceptaría. Aguanta un año, ahorra, y luego ya veremos.","ar":"إذن كنت سأقبل. اصبري سنة، وادّخري، وبعد ذلك نرى."},{"speaker":"luna","es":"Tienes razón. Mañana les respondo que sí.","ar":"معك حق. غدًا سأردّ عليهم وأقول لهم إنني موافقة."}],"questions":[{"q":"ما الميزة الأساسية للعمل الجديد؟","options":["أقرب إلى البيت كثيرًا من عملها الحالي","راتب أعلى بعشرين في المئة","مواعيد مرنة تستطيع أن تختارها بنفسها"],"answer":"راتب أعلى بعشرين في المئة","rationale":"قالت «Pagan un veinte por ciento más». والمواعيد المرنة ميزة عملها الحالي، أما الجديد فأبعد عن البيت."},{"q":"ما عيب العمل الجديد؟","options":["ساعة في الطريق في كل اتجاه وضغط عمل كثير","الراتب أقل","المديرون سيئون"],"answer":"ساعة في الطريق في كل اتجاه وضغط عمل كثير","rationale":"قالت «tardaría una hora en llegar» ونقلت عن الفتاة «hay mucha presión». والراتب أعلى لا أقل."},{"q":"لماذا تحتاج لونا إلى مال زائد؟","options":["تريد أن تشتري سيارة لتنقلاتها اليومية","تريد أن تسافر إلى أوروبا في الصيف مع صديقاتها","تريد أن تدرس الماجستير العام القادم"],"answer":"تريد أن تدرس الماجستير العام القادم","rationale":"قالت «Quiero hacer un máster el año que viene» وإنها تحتاج إلى الادخار. ولم تُذكر سيارة ولا سفر."},{"q":"ما نصيحة باكو؟","options":["اطلبي راتبًا أعلى في عملك الحالي","اقبلي واصبري سنة حتى تدّخري","ارفضي فورًا"],"answer":"اقبلي واصبري سنة حتى تدّخري","rationale":"قال «yo lo aceptaría. Aguanta un año, ahorra, y luego ya veremos». ولم تُعرض مفاوضة عملها الحالي."},{"q":"ما قرار لونا النهائي؟","options":["ستقبل العرض","ما زالت محتارة","سترفض العرض"],"answer":"ستقبل العرض","rationale":"قالت «Mañana les respondo que sí» أي غدًا سأردّ بالموافقة."},{"q":"ما الذي غيّر رأي باكو أثناء الحديث؟","options":["حين عرف أن الطريق ساعة في كل اتجاه","حين عرف أن الادخار سيحقق هدف الماجستير","حين عرف أن الشركة كبيرة ولها فروع كثيرة في الخارج"],"answer":"حين عرف أن الادخار سيحقق هدف الماجستير","rationale":"ما إن عرف بالماجستير حتى قال «eso cambia las cosas» أي هذا يغيّر الأمر، وعندها بدأ يميل إلى القبول."}]},{"id":"b1-movil-roto","level":"B1","title":"هل يُصلَح الهاتف أم نشتري هاتفًا جديدًا؟","desc":"يذهب باكو إلى محل صيانة بهاتف شاشته مكسورة، وتشرح له الفنية الخيارات.","lines":[{"speaker":"paco","es":"Buenas. Se me ha roto la pantalla del móvil. ¿Tiene arreglo?","ar":"مساء الخير. انكسرت شاشة هاتفي. هل يمكن إصلاحها؟"},{"speaker":"luna","es":"A ver... Sí, se puede cambiar. ¿Qué modelo es?","ar":"أرِني... نعم، يمكن تغييرها. ما الطراز؟"},{"speaker":"paco","es":"Es un modelo de hace cuatro años.","ar":"طراز عمره أربع سنوات."},{"speaker":"luna","es":"Mire, la pantalla cuesta ochenta euros, más veinte de mano de obra.","ar":"اسمع، الشاشة بثمانين يورو، وعشرون يورو أجرة اليد."},{"speaker":"paco","es":"Cien euros... no sé si merece la pena. El móvil ya es viejo.","ar":"مئة يورو... لا أعرف هل يستحق ذلك أم لا. الهاتف قديم أصلًا."},{"speaker":"luna","es":"Entiendo. Depende. ¿Le funciona bien todo lo demás?","ar":"فهمت. هذا يعتمد. هل بقية الهاتف تعمل جيدًا؟"},{"speaker":"paco","es":"La batería dura poco, pero lo demás va bien.","ar":"البطارية تنفد بسرعة، لكن الباقي يعمل جيدًا."},{"speaker":"luna","es":"Pues otra cosa: la batería de este modelo ya no se encuentra fácil. Si se la cambiamos dentro de unos meses, será otro gasto.","ar":"حسنًا، وهناك شيء آخر: بطارية هذا الطراز صار من الصعب العثور عليها. إن غيّرناها بعد بضعة أشهر فهذه مصاريف أخرى."},{"speaker":"paco","es":"O sea, que si lo arreglo ahora, en unos meses igual tengo otro problema.","ar":"أي إنني لو أصلحته الآن، فبعد أشهر قد تظهر لي مشكلة أخرى."},{"speaker":"luna","es":"Exacto. Yo le diría que se comprara uno nuevo. Con cien euros más lo que ahorra, tiene un móvil mejor.","ar":"بالضبط. كنت سأقول لك اشترِ هاتفًا جديدًا. بهذه المئة يورو مع قليل من المدخرات ستشتري هاتفًا أفضل."},{"speaker":"paco","es":"¿Y no me estará vendiendo la moto?","ar":"ألا تخدعينني لأشتري؟"},{"speaker":"luna","es":"No, si aquí solo reparamos, no vendemos móviles. Se lo digo porque es lo que yo haría.","ar":"لا، نحن هنا نصلح فقط، ولا نبيع هواتف. أقول لك هذا لأن هذا هو ما كنت سأفعله أنا."},{"speaker":"paco","es":"Vale, me ha convencido. Entonces no hace falta el arreglo.","ar":"حسنًا، أقنعتِني. إذن لا حاجة إلى الإصلاح."},{"speaker":"luna","es":"Un consejo: antes de tirar el viejo, pase las fotos al ordenador.","ar":"نصيحة: قبل أن ترمي القديم، انقل الصور إلى الحاسوب."},{"speaker":"paco","es":"¡Buena idea! Gracias por la honestidad.","ar":"فكرة جميلة! شكرًا على صراحتك."}],"questions":[{"q":"كم ستكلّف إصلاح الشاشة؟","options":["عشرون يورو أجرة اليد وحدها","ثمانون يورو سعر الشاشة وحدها","مئة يورو بالكامل"],"answer":"مئة يورو بالكامل","rationale":"الشاشة بثمانين وأجرة اليد بعشرين، أي المجموع مئة: «ochenta euros, más veinte de mano de obra». والثمانون والعشرون أجزاء لا المجموع."},{"q":"لماذا ترى الفنية أن الإصلاح ليس أفضل قرار؟","options":["الشاشة الجديدة ستكون أضعف من الأصلية","بطارية هذا الطراز صار من الصعب العثور عليها وستحتاج إلى تغيير قريبًا","المحل لا يستطيع إصلاح هذا الطراز أصلًا"],"answer":"بطارية هذا الطراز صار من الصعب العثور عليها وستحتاج إلى تغيير قريبًا","rationale":"قالت «la batería de este modelo ya no se encuentra fácil» وإن هذا سيكون مصروفًا آخر قريبًا. فالإصلاح نفسه ممكن، لكنه ليس أذكى قرار."},{"q":"لماذا شكّ باكو في أن الفنية تريد أن تبيعه؟","options":["لأنها نصحته بشراء هاتف جديد بدل الإصلاح","لأنها قالت له إن هذا الهاتف لا يمكن إصلاحه أبدًا","لأنها طلبت منه أن يدفع عربونًا مقدّمًا"],"answer":"لأنها نصحته بشراء هاتف جديد بدل الإصلاح","rationale":"سألها «¿no me estará vendiendo la moto?» وهو تعبير إسباني معناه: هل تخدعينني؟ فردّت «aquí solo reparamos, no vendemos móviles» أي إن المحل يصلح فقط، فلا فائدة لها إن خرج دون إصلاح."},{"q":"ما قرار باكو النهائي؟","options":["سيصلح الشاشة فورًا في اليوم نفسه","سيغيّر البطارية فقط ويترك الشاشة","لن يصلحه وسيشتري هاتفًا جديدًا"],"answer":"لن يصلحه وسيشتري هاتفًا جديدًا","rationale":"قال «me ha convencido. Entonces no hace falta el arreglo» أي اقتنع وألغى الإصلاح."},{"q":"ما آخر نصيحة قدّمتها الفنية؟","options":["أن يشتري الطراز نفسه مرة أخرى لأنه مضمون","أن ينقل الصور إلى الحاسوب قبل أن يرمي القديم","أن يترك الهاتف القديم عندها للفحص"],"answer":"أن ينقل الصور إلى الحاسوب قبل أن يرمي القديم","rationale":"قالت «antes de tirar el viejo, pase las fotos al ordenador» أي قبل أن ترمي القديم انقل الصور إلى الحاسوب. ولم تقل أن يشتري الطراز نفسه."}]},{"id":"b2-factura-telefono","level":"B2","title":"الفاتورة بها خطأ","desc":"ذهب باكو إلى شركة الهاتف المحمول معترضًا على فاتورة جاءت بضعف المعتاد، والموظفة تحاول حل المشكلة.","lines":[{"speaker":"luna","es":"Buenos días. ¿En qué puedo ayudarle?","ar":"صباح الخير. بمَ يمكنني مساعدتك؟"},{"speaker":"paco","es":"Mire, este mes la factura me ha llegado del doble de lo normal, y no entiendo por qué.","ar":"انظري، هذا الشهر وصلتني الفاتورة بضعف المعتاد، ولا أفهم لماذا."},{"speaker":"luna","es":"Vamos a verlo. ¿Me da su número, por favor? ... Aquí está. Efectivamente, hay un cargo de datos internacionales.","ar":"لنرَ الأمر. هل تتفضل بذكر رقمك؟ ... ها هو. بالفعل، توجد رسوم بيانات دولية."},{"speaker":"paco","es":"¿Datos internacionales? Si yo no he salido de España este año.","ar":"بيانات دولية؟ أنا لم أغادر إسبانيا هذا العام."},{"speaker":"luna","es":"A veces el móvil se conecta a una red extranjera si vive cerca de la frontera. ¿Ha estado cerca de Portugal o Francia?","ar":"أحيانًا يتصل الهاتف المحمول بشبكة أجنبية إذا كنتَ تقيم قريبًا من الحدود. هل كنتَ قريبًا من البرتغال أو فرنسا؟"},{"speaker":"paco","es":"Vivo en Madrid. Esto es un error, claramente.","ar":"أنا أقيم في مدريد. هذا خطأ واضح."},{"speaker":"luna","es":"Tiene razón, Madrid no tiene sentido. Le abro una reclamación ahora mismo y le devolvemos el importe en la próxima factura.","ar":"معكَ حق، فهذا لا يعقل في مدريد. سأفتح لكَ شكوى الآن فورًا وسنعيد إليك المبلغ في الفاتورة القادمة."},{"speaker":"paco","es":"¿En la próxima factura? Yo preferiría que me lo devolvieran ya. Es dinero que se me ha cobrado de más.","ar":"في الفاتورة القادمة؟ كنت أود أن تردوه إليّ الآن. فهذه نقود سُحبت مني بالخطأ."},{"speaker":"luna","es":"Lo entiendo, pero el sistema solo permite el abono en factura. Lo que sí puedo hacer es que se anote como prioridad, para que no se retrase.","ar":"أتفهم موقفك، لكن النظام لا يسمح إلا بالخصم في الفاتورة. ما أستطيع فعله هو أن أسجلها أولوية حتى لا تتأخر."},{"speaker":"paco","es":"Vale, pero quiero un número de referencia y algo por escrito.","ar":"حسنًا، لكنني أريد رقم مرجع وشيئًا مكتوبًا."},{"speaker":"luna","es":"Por supuesto. Aquí tiene: es la referencia erre-cuatro-cero-dos-uno-cinco. Y le llegará un correo de confirmación hoy.","ar":"بالطبع. تفضل: الرقم المرجعي أر-أربعة-صفر-اثنان-واحد-خمسة. وسيصلك بريد تأكيد إلكتروني اليوم."},{"speaker":"paco","es":"De acuerdo. Y si la próxima factura llega sin el abono, ¿qué hago?","ar":"حسنًا. وإذا وصلت الفاتورة القادمة دون الخصم، ماذا أفعل؟"},{"speaker":"luna","es":"Llame al número de atención y dé esa referencia. Con eso recuperan todo el trámite en un minuto.","ar":"اتصل بخدمة العملاء واذكر لهم هذا الرقم. به سيصلون إلى كل تفاصيل الشكوى في دقيقة."},{"speaker":"paco","es":"Perfecto. Gracias por su ayuda.","ar":"ممتاز. شكرًا على مساعدتك."}],"questions":[{"q":"ما مشكلة باكو بالضبط؟","options":["هاتفه المحمول انكسر ويحتاج إلى استبدال بالضمان","الفاتورة جاءت بضعف المعتاد بسبب رسوم بيانات دولية","يريد تغيير باقته إلى باقة أرخص قبل السفر"],"answer":"الفاتورة جاءت بضعف المعتاد بسبب رسوم بيانات دولية","rationale":"قال «la factura me ha llegado del doble» والموظفة وجدت «un cargo de datos internacionales». لا يوجد هاتف مكسور ولا تغيير باقة."},{"q":"ما التفسير الأول الذي قدمته الموظفة للرسوم؟","options":["ربما اتصل الهاتف بشبكة أجنبية إن كان يقيم قريبًا من الحدود","الشركة غيّرت أسعارها من أول الشهر دون تحذير","باكو بالتأكيد سافر خارج إسبانيا ونسي إيقاف البيانات"],"answer":"ربما اتصل الهاتف بشبكة أجنبية إن كان يقيم قريبًا من الحدود","rationale":"قالت «el móvil se conecta a una red extranjera si vive cerca de la frontera». وحين عرفت أنه يقيم في مدريد قالت إن هذا لا معنى له."},{"q":"ما الحل الذي اتفقا عليه؟","options":["نقود ناقصة تُرَد إليه نقدًا في الزيارة نفسها","تغيير الباقة إلى باقة أعلى كتعويض عن الخطأ","شكوى برقم مرجع وخصم المبلغ من الفاتورة القادمة"],"answer":"شكوى برقم مرجع وخصم المبلغ من الفاتورة القادمة","rationale":"قالت «Le abro una reclamación» و«le devolvemos el importe en la próxima factura». طلب باكو النقود فورًا لكن النظام لا يسمح إلا بالخصم من الفاتورة."},{"q":"لماذا لم تستطع الموظفة إعادة النقود فورًا؟","options":["ليست لديها صلاحية إعادة أي مبلغ دون مديرها","النظام لا يسمح إلا بالخصم في الفاتورة","يجب أن يرسل باكو طلبًا مكتوبًا بالبريد الإلكتروني أولًا"],"answer":"النظام لا يسمح إلا بالخصم في الفاتورة","rationale":"قالت «el sistema solo permite el abono en factura». لا حديث عن صلاحيات ولا عن بريد إلكتروني."},{"q":"ماذا طلب باكو كضمان؟","options":["رقم مرجع وتأكيد مكتوب يصله اليوم","توقيع من مدير الفرع على ورقة رسمية","خصم إضافي على الشهرين القادمين أيضًا"],"answer":"رقم مرجع وتأكيد مكتوب يصله اليوم","rationale":"قال «quiero un número de referencia y algo por escrito» وأخذ الرقم المرجعي ووعدًا ببريد تأكيد اليوم."},{"q":"إذا جاءت الفاتورة القادمة دون الخصم، ماذا يفعل؟","options":["يلغي الخط تمامًا وينقل رقمه إلى شركة أخرى","يقدم شكوى جديدة من البداية دون رقم","يتصل بخدمة العملاء ويعطيهم رقم المرجع"],"answer":"يتصل بخدمة العملاء ويعطيهم رقم المرجع","rationale":"قالت له «Llame al número de atención y dé esa referencia» وهم سيصلون إلى كل تفاصيل الشكوى في دقيقة."}]},{"id":"b2-proyecto-retrasado","level":"B2","title":"المشروع تأخر","desc":"لونا مديرة مشروع وتتحدث مع باكو عن تأخير التسليم: ما السبب وما الخطة الواقعية للَّحاق.","lines":[{"speaker":"luna","es":"Paco, tenemos que hablar del proyecto. El cliente me ha llamado dos veces esta semana.","ar":"يا باكو، يجب أن نتحدث في المشروع. اتصل بي العميل مرتين هذا الأسبوع."},{"speaker":"paco","es":"Ya me lo imagino. Mira, el retraso no es por falta de trabajo, es que los cambios que pidió el cliente nos han llevado una semana entera.","ar":"أتوقع ذلك. انظري، التأخير ليس بسبب أننا لا نعمل، بل لأن التعديلات التي طلبها العميل أخذت منا أسبوعًا كاملًا."},{"speaker":"luna","es":"Lo sé, y por eso quiero que lo veamos juntos. Si entregáramos lo que hay ahora, ¿qué faltaría?","ar":"أعلم، ولهذا أريد أن نراه معًا. لو سلّمنا الموجود الآن، ما الذي سينقص؟"},{"speaker":"paco","es":"Faltaría la parte de informes y las pruebas finales. Sin eso, el cliente no puede usar el sistema solo.","ar":"سينقص جزء التقارير والاختبارات النهائية. وبدونهما، لن يستطيع العميل استخدام النظام وحده."},{"speaker":"luna","es":"Vale. ¿Cuánto tiempo necesitas de verdad? No quiero fechas bonitas, quiero fechas reales.","ar":"حسنًا. كم من الوقت تحتاج حقًا؟ لا أريد مواعيد شكلها جميل، أريد مواعيد حقيقية."},{"speaker":"paco","es":"Si me quitas las reuniones de esta semana, termino los informes el jueves. Las pruebas, tres días laborables más.","ar":"لو أزلتِ الاجتماعات عني هذا الأسبوع، سأنهي التقارير يوم الخميس. والاختبارات، ثلاثة أيام عمل إضافية."},{"speaker":"luna","es":"O sea, el martes de la semana que viene.","ar":"أي الثلاثاء من الأسبوع القادم."},{"speaker":"paco","es":"El martes, sí. Y si surge algún imprevisto, el miércoles como mucho.","ar":"الثلاثاء، نعم. وإذا طرأ أي ظرف، فالأربعاء كحد أقصى."},{"speaker":"luna","es":"Entonces le digo al cliente miércoles. Prefiero dar un día más y cumplir, que dar el martes y fallar.","ar":"إذن سأقول للعميل الأربعاء. أفضل أن أعطيه يومًا زيادة وأفي، بدل أن أقول الثلاثاء وأتأخر."},{"speaker":"paco","es":"De acuerdo. Y otra cosa: estaría bien que le explicaras al cliente que los cambios tienen un coste de tiempo, para la próxima.","ar":"حسنًا. وشيء آخر: سيكون جيدًا أن تشرحي للعميل أن التعديلات تستغرق وقتًا، من أجل المرة القادمة."},{"speaker":"luna","es":"Tienes razón. Voy a preparar un resumen de los cambios y sus fechas, así lo ve claro.","ar":"معك حق. سأجهز ملخصًا بالتعديلات وتواريخها، وهكذا سيرى الصورة واضحة."},{"speaker":"paco","es":"Perfecto. Entonces, sin reuniones esta semana, ¿eh?","ar":"ممتاز. إذن، دون اجتماعات هذا الأسبوع، أليس كذلك؟"},{"speaker":"luna","es":"Sin reuniones. Pero el jueves quiero ver los informes terminados.","ar":"دون اجتماعات. لكن يوم الخميس أريد أن أرى التقارير منتهية."}],"questions":[{"q":"ما سبب التأخير بحسب باكو؟","options":["أشخاص من الفريق لم يكونوا يعملون جيدًا في الفترة الماضية","الفريق كان مشغولًا بمشكلات في الأجهزة طوال الأسبوع","تعديلات العميل أخذت من الفريق أسبوعًا كاملًا"],"answer":"تعديلات العميل أخذت من الفريق أسبوعًا كاملًا","rationale":"قال «los cambios que pidió el cliente nos han llevado una semana entera» ونفى أن يكون السبب قلة العمل."},{"q":"ما الذي ينقص المشروع؟","options":["موافقة العميل على الخطة الأساسية","جزء التقارير والاختبارات النهائية","التصميم لم يُنفَّذ بعد من البداية"],"answer":"جزء التقارير والاختبارات النهائية","rationale":"قال «Faltaría la parte de informes y las pruebas finales». لم يُذكر التصميم ولا موافقة العميل كشيء ناقص."},{"q":"ماذا طلبت لونا من باكو حين سألته عن الوقت؟","options":["مواعيد حقيقية لا مواعيد شكلها جميل","وعد بأنه سينهي كل شيء قبل الغد","تقرير مكتوب يرسله للعميل بنفسه"],"answer":"مواعيد حقيقية لا مواعيد شكلها جميل","rationale":"قالت «No quiero fechas bonitas, quiero fechas reales» أي إنها تريد مواعيد حقيقية لا للشكل."},{"q":"لماذا قالت لونا للعميل الأربعاء لا الثلاثاء؟","options":["لأن العميل قال إنه غير متفرغ يوم الثلاثاء من الأساس","لأن باكو طلب يوم إجازة في منتصف الأسبوع","لتترك هامشًا إذا طرأ ظرف وتظل وافية بوعدها"],"answer":"لتترك هامشًا إذا طرأ ظرف وتظل وافية بوعدها","rationale":"قالت «Prefiero dar un día más y cumplir, que dar el martes y fallar» أي تفضل أن تعطي يومًا زيادة وتفي."},{"q":"ماذا طلب باكو من لونا أن تفعل مع العميل من أجل المستقبل؟","options":["تطلب منه مالًا زائدًا عن كل تعديل جديد","تشرح له أن التعديلات تستغرق وقتًا","تبلغه أن الفريق ضجر من كثرة التعديلات"],"answer":"تشرح له أن التعديلات تستغرق وقتًا","rationale":"قال «estaría bien que le explicaras al cliente que los cambios tienen un coste de tiempo» أي إن التعديلات تستغرق وقتًا."},{"q":"ما المقايضة التي حدثت في النهاية؟","options":["لونا أزالت الاجتماعات مقابل أن تكون التقارير جاهزة يوم الخميس","باكو يعمل يوم الإجازة مقابل مكافأة مالية","العميل ينتظر أسبوعين كاملين إضافيين دون شكوى"],"answer":"لونا أزالت الاجتماعات مقابل أن تكون التقارير جاهزة يوم الخميس","rationale":"اشترط باكو «Si me quitas las reuniones... termino los informes el jueves» وأكدت لونا: «Sin reuniones. Pero el jueves quiero ver los informes terminados»."}]},{"id":"b2-cancelacion-hotel","level":"B2","title":"إلغاء حجز الفندق","desc":"لونا لديها ظرف طارئ وتريد إلغاء حجز غير قابل للاسترداد، وتحاول الوصول إلى حل عادل مع موظف الاستقبال.","lines":[{"speaker":"paco","es":"Recepción, buenas tardes.","ar":"الاستقبال، مساء الخير."},{"speaker":"luna","es":"Buenas tardes. Tengo una reserva para este fin de semana y necesito cancelarla. Me ha surgido un problema familiar.","ar":"مساء الخير. لدي حجز في نهاية هذا الأسبوع وأحتاج إلى إلغائه. طرأت لي ظروف عائلية."},{"speaker":"paco","es":"Lo siento mucho. Déjeme ver... Sí, aquí está. Le comento que su tarifa es no reembolsable, se lo indicaba la confirmación.","ar":"أنا آسف جدًا. دعيني أنظر... نعم، وجدته. أود أن أوضح لك أن حجزك غير قابل للاسترداد، وقد كان هذا مكتوبًا في التأكيد."},{"speaker":"luna","es":"Sí, lo sé, lo vi. Pero pensé que, siendo un problema familiar, podrían hacer una excepción.","ar":"نعم أعلم، رأيته. لكنني كنت أظن أنه ما دامت الظروف عائلية، يمكنكم عمل استثناء."},{"speaker":"paco","es":"Entiendo perfectamente su situación. Mire, una devolución completa no puedo autorizarla yo, pero hay una opción que igual le interesa.","ar":"أتفهم وضعك تمامًا. انظري، ليست لدي صلاحية الاسترداد الكامل، لكن يوجد حل قد يعجبك."},{"speaker":"luna","es":"Dígame.","ar":"تفضل، إني أسمعك."},{"speaker":"paco","es":"Puedo cambiarle la reserva a cualquier fin de semana de los próximos seis meses, sin coste adicional. Así no pierde el dinero.","ar":"أستطيع نقل الحجز إلى أي نهاية أسبوع في الأشهر الستة القادمة، دون أي تكلفة إضافية. هكذا لن تضيع نقودك."},{"speaker":"luna","es":"¿Y si el fin de semana que elija es más caro?","ar":"وإذا كانت نهاية الأسبوع التي سأختارها أغلى؟"},{"speaker":"paco","es":"Pagaría solo la diferencia. Si es más barato, se lo dejamos como crédito para el desayuno o el parking.","ar":"ستدفعين الفرق فقط. وإن كانت أرخص، سنترك لك الفرق رصيدًا للإفطار أو لموقف السيارات."},{"speaker":"luna","es":"Hmm. ¿Y no hay manera de que me devuelvan al menos la mitad? Prefiero el dinero, la verdad, porque no sé cuándo podré viajar.","ar":"همم. ألا توجد طريقة لإعادة نصف المبلغ إليّ على الأقل؟ أنا بصراحة أفضل أن آخذ النقود، لأنني لا أعرف متى سأستطيع السفر."},{"speaker":"paco","es":"Le voy a ser sincero: con esa tarifa, la mitad tampoco está en mi mano. Lo que sí puedo hacer es anotar su caso y que la dirección lo revise mañana. No le prometo nada, pero se lo paso con buena recomendación.","ar":"سأكون صريحًا معك: مع هذا الحجز، حتى النصف ليس في يدي. ما أستطيع فعله هو أن أسجل حالتك وأن تراجعها الإدارة غدًا. لا أعدك بشيء، لكنني سأقدمها بتوصية جيدة."},{"speaker":"luna","es":"Vale. Hágalo, por favor. ¿Y si dicen que no, me queda la opción del cambio de fechas?","ar":"حسنًا. افعل ذلك من فضلك. وإذا قالوا لا، هل يبقى معي خيار تغيير الموعد؟"},{"speaker":"paco","es":"Exacto, esa opción sigue disponible durante seis meses. Le llamo mañana antes de las doce con la respuesta.","ar":"بالضبط، هذا الخيار سيبقى متاحًا طوال الأشهر الستة. سأتصل بك غدًا قبل الساعة الثانية عشرة بالرد."},{"speaker":"luna","es":"De acuerdo. Gracias por la claridad, de verdad.","ar":"حسنًا. شكرًا على الوضوح، حقًا."}],"questions":[{"q":"ما نوع حجز لونا؟","options":["مجاني كجزء من عرض خاص للعملاء القدامى","قابل للاسترداد بالكامل لأنها حجزت مبكرًا","غير قابل للاسترداد، وقد كان هذا مكتوبًا في التأكيد"],"answer":"غير قابل للاسترداد، وقد كان هذا مكتوبًا في التأكيد","rationale":"قال الموظف «su tarifa es no reembolsable» وأن هذا كان مكتوبًا في التأكيد، واعترفت لونا بأنها رأته."},{"q":"ما الحل الأول الذي عرضه الموظف؟","options":["ترقية الغرفة إلى جناح في الموعد نفسه","نقل الحجز إلى أي نهاية أسبوع خلال ستة أشهر دون تكلفة","استرداد كامل للمبلغ على البطاقة نفسها فورًا"],"answer":"نقل الحجز إلى أي نهاية أسبوع خلال ستة أشهر دون تكلفة","rationale":"قال «Puedo cambiarle la reserva a cualquier fin de semana de los próximos seis meses, sin coste adicional»."},{"q":"إذا كان الموعد الجديد أرخص، فماذا سيحدث للفرق؟","options":["يتحول إلى رصيد لها للإفطار أو لموقف السيارات","الفرق يضيع ولا يُحتسب في شيء","يُرَد إليها نقدًا على البطاقة في اليوم نفسه"],"answer":"يتحول إلى رصيد لها للإفطار أو لموقف السيارات","rationale":"قال «se lo dejamos como crédito para el desayuno o el parking» أي إن الفرق رصيد للإفطار أو لموقف السيارات."},{"q":"لماذا تفضل لونا النقود على تغيير الموعد؟","options":["الفندق لم يعجبها وتريد الحجز في مكان آخر","تريد النقود لتدفع مصاريف أخرى مختلفة","لا تعرف متى ستستطيع السفر بسبب ظروفها"],"answer":"لا تعرف متى ستستطيع السفر بسبب ظروفها","rationale":"قالت «no sé cuándo podré viajar» أي إنها لا تعرف متى ستستطيع السفر. لا حديث عن فندق آخر."},{"q":"ما الذي استطاع الموظف فعله حقًا؟","options":["وعدها بأنه سيعيد إليها نصف المبلغ حتمًا غدًا","سجّل الحالة وستراجعها الإدارة غدًا دون أي وعد","أعاد إليها كل النقود من خزنة الفرع فورًا"],"answer":"سجّل الحالة وستراجعها الإدارة غدًا دون أي وعد","rationale":"قال «No le prometo nada, pero se lo paso con buena recomendación» أي إنه لن يعدها بشيء ليس في يده، لكنه سيوصل طلبها."},{"q":"حتى متى يبقى خيار تغيير الموعد متاحًا؟","options":["يبقى متاحًا طوال الأشهر الستة حتى لو رفضت الإدارة","متاح لمدة أسبوع واحد فقط من تاريخ المكالمة","يجب أن تقرر في المكالمة نفسها وإلا ستخسره"],"answer":"يبقى متاحًا طوال الأشهر الستة حتى لو رفضت الإدارة","rationale":"قال «esa opción sigue disponible durante seis meses» وأكد أنه إذا قالت الإدارة لا، فإن الخيار سيبقى موجودًا."}]},{"id":"b2-entrevista-trabajo","level":"B2","title":"سؤال صعب في المقابلة","desc":"باكو في مقابلة عمل ولونا المديرة تسأله عن فترة الفراغ في سيرته الذاتية.","lines":[{"speaker":"luna","es":"Su experiencia es muy interesante, pero me llama la atención una cosa: hay un año entero sin trabajar entre sus dos últimos empleos. ¿Puede contarme qué pasó?","ar":"خبرتك مثيرة للاهتمام جدًا، لكن ثمة أمرًا يلفت انتباهي: توجد سنة كاملة دون عمل بين آخر وظيفتين. هل يمكنك أن تحكي لي ما الذي حدث؟"},{"speaker":"paco","es":"Claro. La empresa donde trabajaba cerró y me quedé sin empleo. Los primeros meses busqué trabajo sin parar, pero el sector estaba parado.","ar":"بالتأكيد. الشركة التي كنت أعمل فيها أُغلقت فوجدت نفسي دون عمل. في الأشهر الأولى كنت أبحث عن عمل دون توقف، لكن القطاع كان متوقفًا."},{"speaker":"luna","es":"¿Y el resto del año?","ar":"وباقي السنة؟"},{"speaker":"paco","es":"Mi madre enfermó y decidí cuidarla. Podía permitírmelo unos meses, y era más importante para mí que aceptar cualquier trabajo rápido.","ar":"مرضت والدتي فقررت رعايتها. كنت أستطيع تحمل ذلك ماديًا بضعة أشهر، وكان ذلك أهم عندي من قبول أي عمل بسرعة."},{"speaker":"luna","es":"Entiendo. Algunos entrevistadores verían eso como un riesgo: que usted deje el trabajo si surge algo personal.","ar":"أتفهم ذلك. بعض مسؤولي التوظيف قد يرون ذلك خطرًا: أن تترك العمل إذا طرأ لك ظرف شخصي."},{"speaker":"paco","es":"Yo lo veo al revés: volví en cuanto mi madre mejoró, y en mi trabajo actual pasé cuatro años sin faltar apenas. Sé separar las cosas, pero también sé qué es lo importante.","ar":"أنا أراه بالعكس: ما إن تحسّنت والدتي حتى عدت إلى العمل، وفي عملي الحالي أمضيت أربع سنوات دون غياب يُذكر تقريبًا. أعرف كيف أفصل بين الأمور وأعرف ما المهم."},{"speaker":"luna","es":"Bien dicho. Otra pregunta: ¿por qué quiere dejar su trabajo actual?","ar":"كلام جميل. سؤال آخر: لماذا تريد ترك عملك الحالي؟"},{"speaker":"paco","es":"Porque he llegado al techo. Aprendí todo lo que podía aprender allí, y su empresa trabaja en proyectos que allí no existen.","ar":"لأنني وصلت إلى السقف. تعلمت كل ما يمكن أن أتعلمه هناك، وشركتك تعمل على مشاريع غير موجودة هناك."},{"speaker":"luna","es":"¿Y si le ofrecieran allí más dinero para quedarse?","ar":"وإذا عرضوا عليك مالًا أكثر لتبقى؟"},{"speaker":"paco","es":"Le seré sincero: el dinero importa, pero si fuera solo eso, ya me habría ido a cualquier otro sitio. Lo que busco es crecer, y eso aquí lo veo claro.","ar":"سأكون صريحًا معك: المال مهم، لكن لو كان الأمر مالًا فقط، لكنت رحلت إلى أي مكان آخر منذ زمن. ما أبحث عنه هو أن أنمو، وهذا أراه واضحًا لديكم."},{"speaker":"luna","es":"Muy bien. Nosotros también vamos a ser sinceros con usted: hay otros dos candidatos. Le llamaremos el viernes, sea cual sea la decisión.","ar":"حسنًا جدًا. نحن أيضًا سنكون صريحين معك: يوجد مرشحان آخران. سنتصل بك يوم الجمعة، مهما كان القرار."},{"speaker":"paco","es":"Se lo agradezco. Prefiero un no claro a semanas de espera.","ar":"أشكرك على ذلك. الرفض الواضح خير عندي من أن أنتظر أسابيع."}],"questions":[{"q":"ما سبب سنة الفراغ في سيرة باكو؟","options":["شركته أُغلقت ثم مرضت والدته فمكث بجانبها","قضى سنة يدرس دورات ليغير مجاله المهني تمامًا","أخذ سنة إجازة ليسافر حول العالم ويرتاح من العمل"],"answer":"شركته أُغلقت ثم مرضت والدته فمكث بجانبها","rationale":"قال «La empresa... cerró» ثم «Mi madre enfermó y decidí cuidarla». لم يُذكر سفر ولا دراسة."},{"q":"كيف ردت لونا على إجابته؟","options":["تجاهلت الموضوع تمامًا وواصلت في السيرة الذاتية","قالت له إن المقابلة انتهت وشكرته على وقته","واجهته بأن بعض مسؤولي التوظيف قد يرون ذلك خطرًا"],"answer":"واجهته بأن بعض مسؤولي التوظيف قد يرون ذلك خطرًا","rationale":"قالت «Algunos entrevistadores verían eso como un riesgo» أي إن هناك من قد يرى ذلك خطرًا."},{"q":"كيف دافع باكو عن نفسه؟","options":["قال إن هذا موضوع شخصي وليس من حقها السؤال فيه من الأساس","عاد إلى العمل ما إن تحسّنت والدته، وأربع سنوات لم يغب تقريبًا","وعدها بأنه لن يترك العمل الجديد مهما كانت الظروف"],"answer":"عاد إلى العمل ما إن تحسّنت والدته، وأربع سنوات لم يغب تقريبًا","rationale":"قال «volví en cuanto mi madre mejoró» و«pasé cuatro años sin faltar apenas»."},{"q":"لماذا يريد باكو ترك عمله الحالي؟","options":["وصل إلى أقصى ما يمكنه هناك ويريد أن ينمو","راتبه قليل جدًا مقارنة بزملائه في الشركة نفسها","لديه مشكلات شخصية مع مديره المباشر منذ زمن"],"answer":"وصل إلى أقصى ما يمكنه هناك ويريد أن ينمو","rationale":"قال «he llegado al techo» و«Lo que busco es crecer». صرّح بأن المال مهم لكنه ليس السبب الأساسي."},{"q":"ما رد باكو على سؤال «إن عرضوا عليك مالًا أكثر فهل تبقى؟»","options":["رفض الإجابة عن السؤال وقال إن هذا موضوع شخصي","سيقبل أي عرض أعلى فورًا دون تفكير","المال مهم لكن ما يبحث عنه هو أن ينمو، وهذا يراه لديهم"],"answer":"المال مهم لكن ما يبحث عنه هو أن ينمو، وهذا يراه لديهم","rationale":"قال «el dinero importa, pero... Lo que busco es crecer, y eso aquí lo veo claro»."},{"q":"بماذا وعدت لونا في النهاية؟","options":["ستتصل به بعد شهر حين تنتهي كل المقابلات","ستتصل به يوم الجمعة مهما كان القرار، وقالت له إن هناك مرشحين آخرين","الوظيفة صارت له وانتهى الأمر، والتعاقد بعد أسبوع"],"answer":"ستتصل به يوم الجمعة مهما كان القرار، وقالت له إن هناك مرشحين آخرين","rationale":"قالت «Le llamaremos el viernes, sea cual sea la decisión» أي ستتصل به يوم الجمعة مهما كان القرار. لم تَعِده بالوظيفة."}]},{"id":"c1-vecino-ruido","level":"C1","title":"الجار والموسيقى","desc":"باكو يطرق باب لونا بسبب صوت الموسيقى، وكل واحد يحاول إيصال رسالته دون أن يفقد ماء وجهه.","lines":[{"speaker":"paco","es":"Buenas noches, Luna. Perdona la hora.","ar":"مساء الخير يا لونا. عذرًا على هذا الوقت."},{"speaker":"luna","es":"Hola, Paco. ¿Pasa algo?","ar":"أهلًا يا باكو. هل من شيء؟"},{"speaker":"paco","es":"No es nada grave, pero... la música se oye bastante en mi salón. Tengo una reunión temprano mañana.","ar":"ليس شيئًا خطيرًا، لكن... الموسيقى مسموعة كثيرًا في غرفة معيشتي. لدي اجتماع مبكر غدًا."},{"speaker":"luna","es":"Ay, lo siento, no me había dado cuenta de que se oía tanto. Es el cumpleaños de mi hermana, ya ves.","ar":"آه، آسفة، لم أنتبه أن الصوت واصل إلى هذا الحد. إنه عيد ميلاد أختي، كما ترى."},{"speaker":"paco","es":"Claro, claro, y ni se me pasa por la cabeza pedirte que cortes la fiesta. Ahora bien, si la bajaras un poco a partir de las doce, te lo agradecería de verdad.","ar":"بالطبع، بالطبع، ولا يخطر ببالي أن أطلب منك إيقاف الحفلة. لكن لو خفّضتِ الصوت قليلًا بعد الساعة الثانية عشرة، سأكون ممنونًا لك حقًا."},{"speaker":"luna","es":"Hecho. Y perdona que te lo diga, pero la última vez que tuviste invitados tú, yo no dije nada, ¿eh?","ar":"اتفقنا. واعذرني أن أقولها، لكن آخر مرة كان لديك ضيوف أنت، لم أقل شيئًا، أليس كذلك؟"},{"speaker":"paco","es":"Tienes toda la razón, y te lo agradezco. Por eso vengo yo primero y en buen plan, en vez de llamar a la policía como haría otro.","ar":"معك كل الحق، وأشكرك على ذلك. لهذا أنا آتٍ بنفسي وبكل طيبة، بدل أن أتصل بالشرطة كما كان سيفعل غيري."},{"speaker":"luna","es":"Y yo te agradezco que vengas tú y no tu mujer, que la última vez casi me grita por el buzón.","ar":"وأنا أشكرك أنك أنت من جاء لا زوجتك، لأنها في المرة الماضية كادت تصرخ في وجهي بسبب صندوق البريد."},{"speaker":"paco","es":"Ja, ja. Bueno, cada uno tiene su carácter. Entonces, ¿a las doce?","ar":"ههه. حسنًا، لكل واحد طباعه. إذن اتفقنا، الساعة الثانية عشرة؟"},{"speaker":"luna","es":"A las doce bajo la música y, para que puedas dormir, a la una apagamos del todo. Te invito a un trozo de tarta, por cierto.","ar":"في الساعة الثانية عشرة سأخفض الموسيقى، وحتى تستطيع النوم، في الساعة الواحدة سنطفئ كل شيء. بالمناسبة، تعالَ خذ لك قطعة كعكة."},{"speaker":"paco","es":"Eso sí que es un buen final. Cinco minutos, que me quito el pijama.","ar":"هذه نهاية جميلة حقًا. خمس دقائق وأغير ملابسي وآتي."}],"questions":[{"q":"كيف عبّر باكو عن شكواه؟","options":["صرخ عند الباب من البداية دون مقدمات ولا سلام","بهدوء وقدّم سببًا عمليًا، وهو أن لديه اجتماعًا مبكرًا","اتصل بالشرطة فورًا وأبلغ عن الإزعاج"],"answer":"بهدوء وقدّم سببًا عمليًا، وهو أن لديه اجتماعًا مبكرًا","rationale":"قال «No es nada grave, pero...» وهذه صيغة تهذيب تخفف الشكوى، وذكر الاجتماع سببًا. لا صراخ ولا شرطة."},{"q":"ما كان رد لونا الأول؟","options":["اتهمته بأنه يكبّر الموضوع عمدًا","أغلقت الباب في وجهه دون كلمة ولا رد","اعتذرت وقالت إنه عيد ميلاد أختها"],"answer":"اعتذرت وقالت إنه عيد ميلاد أختها","rationale":"قالت «lo siento, no me había dado cuenta» و«Es el cumpleaños de mi hermana». لا تصعيد من جانبها."},{"q":"لماذا ذكّرته لونا بضيوفه هو؟","options":["لتوازن المعاملة: فهي صمتت حين كان لديه ضيوف","لتتهمه بالنفاق وتقطع الكلام معه","لترفض طلبه تمامًا دون سبب"],"answer":"لتوازن المعاملة: فهي صمتت حين كان لديه ضيوف","rationale":"قالت «la última vez que tuviste invitados tú, yo no dije nada» ووافقت على طلبه، فهذا ليس رفضًا."},{"q":"بماذا يلمّح باكو بجملة الشرطة؟","options":["بأنه هددها بأنه سيتصل بالشرطة إن لم تسكت","بأنه يشكو من جار آخر في العمارة","بأنه اختار الحل الودي بدل التصعيد، وهذا يُحسب له"],"answer":"بأنه اختار الحل الودي بدل التصعيد، وهذا يُحسب له","rationale":"«vengo yo primero y en buen plan, en vez de llamar a la policía como haría otro» تلميح لا تهديد: يقول لها إنه اختار الطريق الودي."},{"q":"ما الاتفاق النهائي؟","options":["الحفلة ستتوقف فورًا من الآن","الصوت يُخفَّض الثانية عشرة والحفلة تنتهي الواحدة، وباكو ذاهب ليأخذ قطعة كعكة","لونا ستتجاهل الشكوى وتكمل سهرتها كالمعتاد"],"answer":"الصوت يُخفَّض الثانية عشرة والحفلة تنتهي الواحدة، وباكو ذاهب ليأخذ قطعة كعكة","rationale":"قال باكو من البداية «ni se me pasa por la cabeza pedirte que cortes la fiesta» أي إنه لا ينوي أن يطلب منها إيقاف الحفلة، وقالت لونا «A las doce bajo la música... a la una apagamos» ودعته إلى الكعكة."},{"q":"ما المفاجأة في آخر الحوار؟","options":["باكو قبل دعوة الكعكة وذهب ليغير ملابسه","باكو رفض الدعوة ومضى متضايقًا دون أن يقول شيئًا","لونا رجعت في كلامها وأوقفت الحفلة في منتصفها"],"answer":"باكو قبل دعوة الكعكة وذهب ليغير ملابسه","rationale":"قال «Eso sí que es un buen final. Cinco minutos, que me quito el pijama» أي إنه قبل الدعوة وذهب ليغير ملابسه."}]},{"id":"c1-quien-lidera","level":"C1","title":"من يقود المشروع؟","desc":"لونا وباكو يتفاوضان بأدب على من يقود المشروع الجديد، كل واحد دون أن يقولها صراحة.","lines":[{"speaker":"luna","es":"Gracias a todos por venir. Como saben, el proyecto Andalucía arranca el mes que viene y hay que nombrar un responsable.","ar":"شكرًا لحضوركم. كما تعلمون، مشروع أندلسيا سيبدأ الشهر القادم ويجب أن نعيّن مسؤولًا."},{"speaker":"paco","es":"Si me permites, Luna: yo llevo dos años con este cliente y conozco sus manías. Sería una pena perder ese conocimiento.","ar":"لو تسمحين لي يا لونا: أنا أعمل مع هذا العميل منذ عامين وأعرف طباعه جيدًا. ستكون خسارة أن نضيّع هذه الخبرة."},{"speaker":"luna","es":"Claro, Paco, por muy valioso que sea ese conocimiento, y lo es, y contaremos contigo sí o sí, la pregunta es quién coordina.","ar":"بالطبع يا باكو، مهما كانت خبرتك قيّمة، وهي قيّمة فعلًا وسنعتمد عليك حتمًا، فالسؤال هو من سينسّق."},{"speaker":"paco","es":"Pues eso es lo que digo: coordinar con un cliente que ya conoces es mucho más fácil que empezar de cero.","ar":"وهذا ما أقوله: أن تنسّق مع عميل تعرفه أسهل بكثير من أن تبدأ من الصفر."},{"speaker":"luna","es":"Totalmente de acuerdo. Aunque también hay que pensar en la carga: tú ya llevas el proyecto Norte y el mantenimiento. No querríamos quemarte.","ar":"متفقة معك تمامًا. لكن مع ذلك يجب أن نفكر في الضغط: أنت تحمل مشروع الشمال والصيانة. لا نريد أن نرهقك."},{"speaker":"paco","es":"Te agradezco la preocupación, aunque prefiero decidir yo si puedo con más o no.","ar":"أشكرك على اهتمامك، لكنني أفضل أن أقرر بنفسي إن كنت أستطيع تحمل المزيد أم لا."},{"speaker":"luna","es":"Por supuesto. Solo lo menciono porque el año pasado, cuando acumulaste tres proyectos, el cliente Norte se quejó de los tiempos.","ar":"بالطبع. أنا فقط أذكر ذلك لأن العام الماضي، حين جمعت ثلاثة مشاريع معًا، اشتكى عميل الشمال من المواعيد."},{"speaker":"paco","es":"Y precisamente por eso aprendí a organizarme mejor. Los errores de los que se aprende se llaman experiencia, ¿no?","ar":"ولهذا بالضبط تعلمت أن أنظم نفسي أفضل. الأخطاء التي يتعلم منها المرء اسمها خبرة، أليس كذلك؟"},{"speaker":"luna","es":"Sin duda. Mira, te propongo esto: tú lideras la relación con el cliente, que es tu fuerte, y yo coordino la parte interna. Así el proyecto tiene lo mejor de cada uno.","ar":"دون شك. انظر، سأقترح عليك هذا: أنت تقود علاقة العميل، فهذه نقطة قوتك، وأنا أنسّق الجزء الداخلي. هكذا سيأخذ المشروع أفضل ما في كل واحد منا."},{"speaker":"paco","es":"Hmm. Oído. ¿Y a la hora de la verdad quién firma las entregas?","ar":"همم. أسمعك. وعند الجد من الذي سيوقّع على التسليمات؟"},{"speaker":"luna","es":"Las firmamos los dos. Y si algún día hay que elegir, que elija el director. Pero sospecho que trabajando así no hará falta.","ar":"كلانا يوقّع. وإذا كان يومٌ ما يجب أن نختار، فليختر المدير. لكن عندي شعور أننا لو مشينا هكذا فلن نحتاج إلى ذلك."},{"speaker":"paco","es":"Trato hecho, entonces.","ar":"إذن اتفقنا."}],"questions":[{"q":"ما حجة باكو الأولى ليقود المشروع؟","options":["هو أقدم واحد في الشركة كلها منذ خمس عشرة سنة","هو صاحب فكرة المشروع منذ بدايته تمامًا","يعرف العميل منذ عامين ويعرف طباعه جيدًا"],"answer":"يعرف العميل منذ عامين ويعرف طباعه جيدًا","rationale":"قال «llevo dos años con este cliente y conozco sus manías». لم تُذكر الأقدمية ولا الفكرة."},{"q":"كيف ردت لونا على حجته أول مرة؟","options":["أقرت بقيمة خبرته لكنها فرّقت بين المعرفة والتنسيق","رفضت كلامه تمامًا وقالت له لن تقود","أعطته المشروع كله دون نقاش"],"answer":"أقرت بقيمة خبرته لكنها فرّقت بين المعرفة والتنسيق","rationale":"«por muy valioso que sea ese conocimiento... la pregunta es quién coordina» أي مهما كانت خبرتك قيّمة، فالسؤال من سينسّق."},{"q":"بماذا اعترضت لونا على باكو؟","options":["هددته بأنها ستكلم المدير في الموضوع","ذكّرته بشكوى عميل الشمال حين حمل ثلاثة مشاريع معًا","قالت له إنك كبرت على هذه المشاريع وانتهى الأمر"],"answer":"ذكّرته بشكوى عميل الشمال حين حمل ثلاثة مشاريع معًا","rationale":"«el año pasado, cuando acumulaste tres proyectos, el cliente Norte se quejó» وقدمته كقلق عليه لا كهجوم."},{"q":"كيف رد باكو على كلام لونا عن العام الماضي؟","options":["قال إن الأخطاء التي يتعلم منها المرء اسمها خبرة","تجاهل الموضوع تمامًا وفتح نقطة أخرى عن ميزانية المشروع","قال إن شكوى العميل لم تكن حقيقية ومبالغًا فيها"],"answer":"قال إن الأخطاء التي يتعلم منها المرء اسمها خبرة","rationale":"«Los errores de los que se aprende se llaman experiencia» أي إن الأخطاء التي تعلم منها صارت خبرة."},{"q":"ما الحل الوسط الذي اقترحته لونا؟","options":["هي تقود المشروع وحدها من الألف إلى الياء","هو يقود المشروع وحده دون مساعدة","هو يقود علاقة العميل وهي تنسّق الداخلي، وكلاهما يوقّع على التسليمات"],"answer":"هو يقود علاقة العميل وهي تنسّق الداخلي، وكلاهما يوقّع على التسليمات","rationale":"«tú lideras la relación con el cliente... yo coordino la parte interna» و«Las firmamos los dos»."},{"q":"لماذا سأل باكو «¿Y a la hora de la verdad quién firma las entregas?»؟","options":["لأنه يريد أن يعرف موعد التسليم النهائي لهذا المشروع","ليعرف من صاحب القرار الرسمي على التسليمات","لأنه خائف من الأوراق والتوقيعات الرسمية الكثيرة"],"answer":"ليعرف من صاحب القرار الرسمي على التسليمات","rationale":"سأل «¿Y a la hora de la verdad quién firma las entregas?» أي عند الجد من المسؤول رسميًا."}]},{"id":"c1-amigo-impuntual","level":"C1","title":"صديقي الذي يتأخر دائمًا","desc":"قررت لونا أن تواجه باكو بمشكلة تأخيره المزمن، لكن دون أن تكسر الصداقة.","lines":[{"speaker":"luna","es":"Por fin, ¿no? Te estaba esperando desde las ocho.","ar":"أخيرًا، أليس كذلك؟ كنت أنتظرك منذ الساعة الثامنة."},{"speaker":"paco","es":"Son las ocho y cuarto, mujer, tampoco es para tanto.","ar":"إنها الثامنة والربع يا لونا، الأمر لا يستحق كل هذا أيضًا."},{"speaker":"luna","es":"Paco, quedamos a las ocho. Y la semana pasada fueron veinte minutos, y la anterior, media hora. Como para no llevar la cuenta.","ar":"يا باكو، نحن اتفقنا على الساعة الثامنة. والأسبوع الماضي كانت عشرين دقيقة، والذي قبله نصف ساعة. فكيف لا أحسبها؟"},{"speaker":"paco","es":"Vale, ya veo por dónde vas. No es una queja, es un historial.","ar":"حسنًا، أنا أفهم إلى أين تذهبين. هذه ليست شكوى، هذه كشف حساب."},{"speaker":"luna","es":"Es que me fastidia, de verdad. No es por los quince minutos, es que me hace sentir que mi tiempo vale menos que el tuyo.","ar":"الموضوع يزعجني حقًا. ليس بسبب الربع ساعة، بل لأنه يشعرني أن وقتي أقل قيمة من وقتك."},{"speaker":"paco","es":"Venga, no exageres. Sabes que no pienso eso.","ar":"يا لونا لا تكبّري الموضوع. أنتِ تعلمين أنني لا أفكر هكذا."},{"speaker":"luna","es":"Lo que piensas no lo sé, lo que veo es que siempre llegas tarde y siempre hay una razón buena. El tráfico, una llamada, lo que sea.","ar":"بماذا تفكر لا أعرف، لكن ما أراه أنك دائمًا تتأخر ودائمًا يوجد سبب حسن. الزحام، مكالمة، أي شيء."},{"speaker":"paco","es":"Uf. Vale. Puede que tengas razón en una cosa: yo siempre calculo el tiempo justo, y siempre pasa algo.","ar":"أوف. حسنًا. ربما يكون معك حق في شيء: أنا دائمًا أحسب الوقت بالضبط، ودائمًا يحدث شيء."},{"speaker":"luna","es":"Pues cuenta con un margen, como hago yo contigo desde hace años, por cierto.","ar":"إذن احسب حسابك بهامش إضافي، كما أفعل أنا معك منذ سنوات، بالمناسبة."},{"speaker":"paco","es":"¿Cómo que como haces tú conmigo?","ar":"ماذا تعنين بكما تفعلين أنت معي؟"},{"speaker":"luna","es":"Pues que cuando quedamos a las ocho, yo sé que llegarás a las ocho y cuarto, así que yo salgo de casa para llegar a las ocho y diez. Y hoy, mira, hoy llegué a las ocho en punto para comprobarlo. Y aquí estoy, esperando.","ar":"أعني أننا حين نتفق على الثامنة، أعرف أنك ستصل الثامنة والربع، فأخرج من البيت بحيث أصل الثامنة وعشر دقائق. واليوم، انظر، اليوم وصلت الثامنة تمامًا لأتأكد. وها أنا أنتظر."},{"speaker":"paco","es":"Es broma, ¿no? Llevas años llegando tarde a propósito para no esperarme.","ar":"تمازحينني، أليس كذلك؟ أنتِ منذ سنوات تتأخرين عمدًا حتى لا تنتظريني."},{"speaker":"luna","es":"A propósito no, con conocimiento de causa. Que es distinto.","ar":"ليس عمدًا، بل عن دراية بالأمر. وهذا شيء مختلف."},{"speaker":"paco","es":"Ja, ja. Está bien, me has ganado. Ocho en punto la próxima vez. Y si llego tarde, pago la cena.","ar":"ههه. حسنًا، لقد غلبتني. الثامنة تمامًا في المرة القادمة. وإن تأخرت، فالعشاء عليّ."},{"speaker":"luna","es":"Apuntado. Y ya que estás, la de hoy también la pagas tú, que la espera ha sido larga.","ar":"سُجّل. وما دمت كذلك، فعشاء اليوم أيضًا عليك، لأن الانتظار كان طويلًا."},{"speaker":"paco","es":"Negociadora nata. Venga, invito yo. Pero que conste que son las ocho y dieciséis.","ar":"مفاوضة بالفطرة. حسنًا، العشاء عليّ. لكن ليُعلَم أن الساعة الثامنة وست عشرة دقيقة."}],"questions":[{"q":"شكوى لونا الحقيقية ليست عن الوقت نفسه، فعماذا هي؟","options":["أن المكان الذي ذاهبان إليه بعيد جدًا","أنها جائعة والمطعم سيغلق مبكرًا","الشعور بأن وقتها أقل قيمة من وقته"],"answer":"الشعور بأن وقتها أقل قيمة من وقته","rationale":"قالت «me hace sentir que mi tiempo vale menos que el tuyo» أي إنه يشعرها أن وقتها أقل قيمة من وقته."},{"q":"كيف كان رد باكو الأول؟","options":["اعتذر لها فورًا من أول كلمة وقال إنه مخطئ","قلّل من الموضوع: «الأمر لا يستحق كل هذا أيضًا» و«لا تكبّري الموضوع»","غيّر الموضوع تمامًا وتحدث معها في شيء آخر عن العمل والصداقة"],"answer":"قلّل من الموضوع: «الأمر لا يستحق كل هذا أيضًا» و«لا تكبّري الموضوع»","rationale":"قال «tampoco es para tanto» و«no exageres» أي إن الأمر لا يستحق كل هذا ولا تكبّري الموضوع."},{"q":"ما الاعتراف الجزئي الذي قدمه باكو؟","options":["أنه يحسب الوقت بالضبط ودائمًا يحدث شيء","أنه لا يحترمها ولا يحترم وقتها","أنه لن يتغير أبدًا مهما حدث"],"answer":"أنه يحسب الوقت بالضبط ودائمًا يحدث شيء","rationale":"«Puede que tengas razón en una cosa: yo siempre calculo el tiempo justo, y siempre pasa algo»."},{"q":"ما كان كشف لونا الكبير؟","options":["أنها كلمت أصدقاءهما المشتركين واشتكت لهم أنه دائمًا يتأخر عنها","أنها قررت أن تتوقف عن الخروج معه نهائيًا مهما اعتذر","أنها منذ سنوات تحسب تأخيره وتخرج متأخرة حتى لا تنتظره"],"answer":"أنها منذ سنوات تحسب تأخيره وتخرج متأخرة حتى لا تنتظره","rationale":"«yo salgo de casa para llegar a las ocho y diez... hoy llegué a las ocho en punto para comprobarlo»."},{"q":"ما الاتفاق النهائي؟","options":["سيبقى كلاهما يتأخر كما هما","المرة القادمة الثامنة تمامًا، وإن تأخر يدفع العشاء، وعشاء اليوم عليه","لونا ستنتظره دون أي شكوى أخرى"],"answer":"المرة القادمة الثامنة تمامًا، وإن تأخر يدفع العشاء، وعشاء اليوم عليه","rationale":"«si llego tarde, pago la cena» وأضافت لونا «la de hoy también la pagas tú»."},{"q":"ما الذي جعل الموقف ينتهي بضحك؟","options":["قدمت لونا الشكوى بكشف مضحك، واعترف باكو دون أن يهينه أحد","لونا صمتت تمامًا ولم ترد عليه","باكو اعتذر منذ أول ما وصل دون نقاش"],"answer":"قدمت لونا الشكوى بكشف مضحك، واعترف باكو دون أن يهينه أحد","rationale":"ضحك باكو وقال «Está bien, me has ganado» بعدما عرف أنها تحسب تأخيره منذ سنوات."}]},{"id":"c1-subida-alquiler","level":"C1","title":"صاحب العقار يريد زيادة الإيجار","desc":"باكو صاحب الشقة يريد زيادة الإيجار ولونا مستأجرة قديمة وتعرف السوق جيدًا. مفاوضة هادئة ومشدودة.","lines":[{"speaker":"paco","es":"Luna, gracias por recibirme. Voy al grano: el contrato se renueva en dos meses y el precio de la zona ha subido mucho.","ar":"يا لونا، شكرًا لأنك استقبلتيني. سأدخل في الموضوع مباشرة: العقد يتجدد بعد شهرين وأسعار المنطقة زادت جدًا."},{"speaker":"luna","es":"¿Cuánto piensa subirme?","ar":"كم تنوي أن تزيد لي؟"},{"speaker":"paco","es":"Cincuenta euros al mes. Sigue siendo menos de lo que piden por pisos peores en esta calle.","ar":"خمسون يورو في الشهر. وهذا لا يزال أقل مما يطلبونه في شقق أسوأ في الشارع نفسه."},{"speaker":"luna","es":"Mire, Paco, yo también me he mirado los precios. Los pisos que usted dice llevan meses anunciados sin alquilarse. El precio que piden no es el precio que pagan.","ar":"انظر يا أستاذ باكو، أنا أيضًا اطلعت على الأسعار. الشقق التي تتحدث عنها ظلت أشهرًا مُعلَنة دون أن تُؤجَّر. السعر المطلوب ليس هو السعر المدفوع."},{"speaker":"paco","es":"Puede ser, pero el mío se alquila mañana. Es una zona con mucha demanda.","ar":"ربما، لكن شقتي ستُؤجَّر غدًا. فهذه منطقة عليها طلب كبير."},{"speaker":"luna","es":"Se alquila mañana, sí. Y luego usted tiene un inquilino nuevo que no conoce, que a saber si le paga a tiempo o le destroza la cocina. Yo llevo cuatro años pagando el día uno, y la caldera nueva se la pagué a medias, ¿se acuerda?","ar":"ستُؤجَّر غدًا، نعم. وبعدها سيكون لديك مستأجر جديد لا تعرفه، ومن يدري هل سيدفع في موعده أم سيتلف المطبخ. أنا منذ أربع سنوات أدفع في اليوم الأول من كل شهر، والسخان الجديد دفعت نصفه معك، أتذكر؟"},{"speaker":"paco","es":"Y se lo agradezco, de verdad. Pero usted entenderá que yo tampoco puedo regalar el dinero.","ar":"وأنا مقدّر ذلك حقًا. لكنك بالتأكيد تفهمين أنني أنا أيضًا لا أستطيع أن أعطي المال مجانًا."},{"speaker":"luna","es":"No le pido que regale nada. Le pido que valore lo que tiene: un inquilino que no le da problemas y que cuida el piso como si fuera suyo. ¿Cuánto le cuesta un mes de piso vacío entre inquilino e inquilino? ¿Seiscientos euros? ¿Más?","ar":"لا أطلب منك أن تعطي شيئًا مجانًا. أطلب منك أن تقدّر ما لديك: مستأجرة لا تُحدث مشكلات وتحافظ على الشقة كأنها ملكها. شهرُ بقاء الشقة فارغة بين مستأجر وآخر يكلف كم؟ ستمئة يورو؟ أكثر؟"},{"speaker":"paco","es":"Ya veo que se lo ha pensado, y bien pensado.","ar":"أرى أنك أعددت حساباتك، وأعددتها صحيحة."},{"speaker":"luna","es":"Me lo he pensado porque me gusta esta casa y quiero quedarme. Por eso le propongo esto: veinticinco euros de subida ahora, y otros veinticinco dentro de un año si el mercado sigue subiendo. Usted cobra más, yo no me voy, y nadie busca pisos ni inquilinos.","ar":"أعددت حساباتي لأنني أحب هذا البيت وأريد البقاء فيه. لهذا أعرض عليك: خمسة وعشرون يورو زيادة الآن، وخمسة وعشرون أخرى بعد سنة إذا ظل السوق في ازدياد. أنت ستقبض أكثر، أنا لن أرحل، ولن يبحث أحد لا عن شقة ولا عن مستأجر."},{"speaker":"paco","es":"Treinta ahora y quince más dentro de un año.","ar":"ثلاثون الآن وخمسة عشر أخرى بعد سنة."},{"speaker":"luna","es":"Trato hecho. Y me lo manda por escrito esta semana, que luego los números bailan.","ar":"اتفقنا. وأرسله لي مكتوبًا هذا الأسبوع، فالأرقام تختلط لاحقًا."}],"questions":[{"q":"بماذا افتتح باكو المفاوضة؟","options":["طلب منها أن تخلي الشقة خلال شهرين على الأكثر","زيادة خمسين يورو لأن أسعار المنطقة زادت","عرض تجديد العقد بالسعر القديم نفسه لسنة أخرى"],"answer":"زيادة خمسين يورو لأن أسعار المنطقة زادت","rationale":"قال «Voy al grano» أي سيقول المطلوب مباشرة، ثم «Cincuenta euros al mes»."},{"q":"كيف ردت لونا على حجة السوق؟","options":["الشقق المُعلَنة بأسعار عالية ظلت أشهرًا دون أن تُؤجَّر","قالت له إنها غير مهتمة بأسعار السوق إطلاقًا","قالت له إن الأسعار نزلت هذه السنة فعلًا"],"answer":"الشقق المُعلَنة بأسعار عالية ظلت أشهرًا دون أن تُؤجَّر","rationale":"«llevan meses anunciados sin alquilarse. El precio que piden no es el precio que pagan» أي إن سعر الإعلان ليس سعر الصفقة."},{"q":"ما ورقة لونا الأقوى في المفاوضة؟","options":["أنها محامية وتعرف كل قوانين الإيجار وسترفع قضية","أن لديها معارف قوية في كل شركات العقارات الكبيرة في المدينة","تاريخها كمستأجرة مثالية: تدفع في اليوم الأول من كل شهر وشاركت في السخان"],"answer":"تاريخها كمستأجرة مثالية: تدفع في اليوم الأول من كل شهر وشاركت في السخان","rationale":"«llevo cuatro años pagando el día uno, y la caldera nueva se la pagué a medias» أي إنها تدفع في اليوم الأول من كل شهر وشاركت في السخان."},{"q":"ما العرض الذي قدمته لونا؟","options":["رفض أي زيادة إطلاقًا مهما كان السبب","زيادة خمسة وعشرين الآن وخمسة وعشرين أخرى بعد سنة إذا ظل السوق في ازدياد","موافقة على الخمسين كما طلب بالضبط"],"answer":"زيادة خمسة وعشرين الآن وخمسة وعشرين أخرى بعد سنة إذا ظل السوق في ازدياد","rationale":"«veinticinco euros de subida ahora, y otros veinticinco dentro de un año si el mercado sigue subiendo»."},{"q":"ما الصفقة النهائية؟","options":["ثلاثون الآن وخمسة عشر أخرى بعد سنة","خمسون زيادة كاملة من أول شهر","خمسة وعشرون فقط دون زيادة أخرى"],"answer":"ثلاثون الآن وخمسة عشر أخرى بعد سنة","rationale":"قال باكو «Treinta ahora y quince más dentro de un año» وقالت لونا «Trato hecho»."},{"q":"لماذا طلبت لونا الاتفاق مكتوبًا؟","options":["لأنها تريد الانسحاب من الاتفاق لاحقًا","لأن محاميها طلب منها ذلك","حتى لا تختلط الأرقام لاحقًا"],"answer":"حتى لا تختلط الأرقام لاحقًا","rationale":"قالت «me lo manda por escrito esta semana, que luego los números bailan» أي إن الأرقام تختلط لاحقًا."}]},{"id":"c2-ascenso-perdido","level":"C2","title":"الترقية التي ذهبت لغيري","desc":"لونا خُطفت منها ترقية لصالح زميل، وتطلب مقابلة مع مديرها باكو لتعرف الحقيقة دون أن تحرق مراكبها.","lines":[{"speaker":"luna","es":"Gracias por verme, Paco. Iré directa: quiero entender qué le faltó a mi candidatura para la dirección del departamento.","ar":"شكرًا لأنك وافقت على مقابلتي يا باكو. سأدخل في الموضوع: أريد أن أفهم ما الذي نقص في ملفي لإدارة القسم."},{"speaker":"paco","es":"Y yo te agradezco que preguntes en vez de hacer conjeturas. Mira, tu candidatura era excelente. La de Andrés también.","ar":"وأنا أشكرك أنك تسألين بدل أن تفترضي. انظري، ملفك كان ممتازًا. وملف أندريس أيضًا."},{"speaker":"luna","es":"Eso lo entiendo. Lo que no entiendo es qué tenía la suya que no tuviera la mía, porque los resultados de mi equipo hablan solos.","ar":"هذا أفهمه. ما لا أفهمه هو ما الذي كان في ملفه وغير موجود في ملفي، لأن نتائج فريقي تتحدث عن نفسها."},{"speaker":"paco","es":"Y hablan, nadie lo discute. Pero el puesto no era solo de resultados. Andrés llevaba dos años en proyectos internacionales, y la dirección quiere abrir ese mercado.","ar":"وتتحدث فعلًا، لا أحد يختلف على ذلك. لكن الوظيفة لم تكن نتائج فقط. أندريس أمضى عامين في مشاريع دولية، والإدارة تنوي فتح ذلك السوق."},{"speaker":"luna","es":"O sea que el criterio decisivo era un perfil que, por mucho que rindiera, yo no podía tener, porque nunca se me ofreció uno de esos proyectos.","ar":"أي إن المعيار الحاسم كان ملفًا مهما عملت جيدًا يستحيل أن يكون عندي، لأنني لم يُعرَض عليّ أبدًا مشروع من تلك."},{"speaker":"paco","es":"Si te digo que no, te miento. Se le ofrecieron a él porque él los pidió. Ahí sí te digo algo: tú nunca pides nada. Rindes mejor que nadie y te quedas esperando a que lo noten.","ar":"إن قلت لك لا، أكون أكذب عليك. لقد عُرضوا عليه لأنه هو طلبهم. وهنا أقول لك شيئًا بجدية: أنتِ لم تطلبي شيئًا أبدًا. تعملين أفضل من الجميع وتنتظرين أن يلاحظ أحد."},{"speaker":"luna","es":"¿Me está diciendo que el error fue no llamar a su puerta?","ar":"أتقول إن خطأي أنني لم أطرق بابك؟"},{"speaker":"paco","es":"Te estoy diciendo que en esta empresa hay dos formas de ascender: ser imprescindible, que tú lo eres, y que se te vea pidiendo el siguiente escalón, que es lo que hizo Andrés. La próxima plaza se abrirá en un año, como mucho. Lo que hagas hasta entonces cuenta.","ar":"أقول لك إن في هذه الشركة طريقتين للترقية: أن تكوني شيئًا لا مثيل له، وأنتِ كذلك فعلًا، وأن يراك الناس وأنتِ تطلبين الدرجة التالية، وهذا ما فعله أندريس. الوظيفة القادمة ستُفتَح خلال سنة كحد أقصى. ما ستفعلينه حتى ذلك الحين هو ما سيُحتَسب."},{"speaker":"luna","es":"Entonces pido formalmente el proyecto internacional que se está gestando. Y pido que conste en algún sitio que lo he pedido.","ar":"إذن أنا أطلب رسميًا المشروع الدولي الذي يجري الإعداد له. وأطلب أن يُسجَّل طلبي في محضر رسمي."},{"speaker":"paco","es":"Consta desde hoy. Y una cosa más, ya que estamos siendo directos: si en un año no se abre nada, ¿qué harás?","ar":"سُجّل من اليوم. وشيء آخر، ما دمنا نتحدث بصراحة: لو مرت سنة ولم يُفتَح شيء، ماذا ستفعلين؟"},{"speaker":"luna","es":"Le voy a ser tan directa como usted: tengo dos ofertas guardadas en el cajón desde hace meses. No las he respondido porque creo en este equipo. Pero creer tiene fecha de caducidad.","ar":"سأكون صريحة مثلك تمامًا: لدي عرضان محفوظان في الدرج منذ أشهر. لم أرد عليهما لأنني مؤمنة بهذا الفريق. لكن إيماني له تاريخ صلاحية."},{"speaker":"paco","es":"Recibido. Y créeme, lo voy a tener muy en cuenta.","ar":"وصلت الرسالة. وصدقيني، سآخذ ذلك في الحسبان جدًا."}],"questions":[{"q":"لماذا أخذ أندريس الترقية رغم أن نتائج لونا كانت قوية؟","options":["الوظيفة تحتاج خبرة دولية والإدارة تنوي فتح سوق خارجي","أندريس قريب المدير وهذا ما حسم الموضوع في النهاية","نتائج لونا كانت فعلًا أضعف من المطلوب في آخر سنتين تقريبًا"],"answer":"الوظيفة تحتاج خبرة دولية والإدارة تنوي فتح سوق خارجي","rationale":"قال «la dirección quiere abrir ese mercado» أي إن الإدارة تنوي فتح ذلك السوق. لا قرابة ولا نتائج ضعيفة في الكلام."},{"q":"ما المفارقة التي كشفتها لونا؟","options":["أن أندريس أصغر منها في السن بكثير","أن هذه الترقية من الأساس دون زيادة في الراتب","المعيار الحاسم ملف يستحيل أن يكون عندها لأن تلك المشاريع لم تُعرَض عليها أبدًا"],"answer":"المعيار الحاسم ملف يستحيل أن يكون عندها لأن تلك المشاريع لم تُعرَض عليها أبدًا","rationale":"قالت «un perfil que, por mucho que rindiera, yo no podía tener» واعترف باكو: «Si te digo que no, te miento» أي لو قال لا يكون يكذب."},{"q":"ما تشخيص باكو لمشكلة لونا؟","options":["أنها تتكلم كثيرًا في الاجتماعات دون فائدة","تعمل أفضل من الجميع لكنها لم تطلب شيئًا أبدًا وتنتظر أن يلاحظ أحد","أنها لا تعمل جيدًا من الأساس في الفترة الأخيرة"],"answer":"تعمل أفضل من الجميع لكنها لم تطلب شيئًا أبدًا وتنتظر أن يلاحظ أحد","rationale":"وصفها بأنها «esperando a que lo noten» أي تنتظر أن يلاحظ أحد."},{"q":"ما الذي فعلته لونا فورًا بعد النصيحة؟","options":["طلبت رسميًا المشروع الدولي وأن يُسجَّل طلبها","قدمت استقالتها على المكتب في اليوم نفسه قبل أن تفكر","ذهبت واشتكت أندريس للإدارة العليا في اليوم نفسه"],"answer":"طلبت رسميًا المشروع الدولي وأن يُسجَّل طلبها","rationale":"«pido formalmente el proyecto internacional» أي طلبت المشروع رسميًا، وطلبت أن يُسجَّل طلبها. لم تحدث استقالة ولا شكوى."},{"q":"ما كانت رسالة لونا المبطّنة الأخيرة؟","options":["أنها ستستقيل غدًا صباحًا فور وصولها إلى العمل ودون رجعة","أنها غير مهتمة بهذه الترقية من الأساس منذ زمن","لديها عروض في الخارج وستصبر إلى حد معين، لكن صبرها ليس مفتوحًا"],"answer":"لديها عروض في الخارج وستصبر إلى حد معين، لكن صبرها ليس مفتوحًا","rationale":"قالت إن لديها عرضين في الدرج و«creer tiene fecha de caducidad» أي إن الثقة لها تاريخ صلاحية، دون كلمة تهديد واحدة."},{"q":"ما الطريقتان للترقية في الشركة بحسب باكو؟","options":["أن تكون قريبًا من المديرين وتسافر معهم","أن تكون شيئًا لا مثيل له، وأن تظهر وأنت تطلب الدرجة التالية","أن تعمل ساعات إضافية وتسكت عن حقك"],"answer":"أن تكون شيئًا لا مثيل له، وأن تظهر وأنت تطلب الدرجة التالية","rationale":"قال «ser imprescindible» أي لا مثيل لك، و«que se te vea pidiendo el siguiente escalón» أي تظهر وأنت تطلب الدرجة التالية."}]},{"id":"c2-oferta-competencia","level":"C2","title":"عرض من المنافس","desc":"باكو جاءه عرض من شركة منافسة ويقول لمديرته لونا، وكلاهما يلعب لعبة ولاء وطموح بكلمات محسوبة.","lines":[{"speaker":"paco","es":"Luna, ¿tienes diez minutos? Es algo que prefiero contarte yo antes de que llegue por otros cauces.","ar":"يا لونا، عندك عشر دقائق؟ يوجد أمر أفضل أن أقوله لك أنا قبل أن يصلك من شخص آخر."},{"speaker":"luna","es":"Cuéntame.","ar":"قُل."},{"speaker":"paco","es":"Me han hecho una oferta. De la competencia. Buena, la verdad.","ar":"جاءني عرض. من المنافس. عرض جيد، بصراحة."},{"speaker":"luna","es":"Ya. ¿Y vienes a despedirte o a negociar? Porque una cosa la haces con Recursos Humanos y la otra, conmigo.","ar":"آها. وأنت جئت لتقول مع السلامة أم لتفاوضني؟ لأن واحدة منهما تُفعَل مع الموارد البشرية والأخرى معي أنا."},{"speaker":"paco","es":"Si quisiera irme, ya estaría escribiendo el correo. Vengo porque llevo seis años aquí y porque quiero saber si mi sitio sigue siendo aquí.","ar":"لو كنت أريد الرحيل، لكنت قد انتهيت من كتابة البريد الإلكتروني. أنا جئت لأنني هنا منذ ست سنوات ولأنني أريد أن أعرف إن كان مكاني لا يزال هنا أم لا."},{"speaker":"luna","es":"Eso es una respuesta bonita. También es la respuesta de quien quiere una contraoferta. No me ofende, ojo; me parece legítimo. Pero hablemos claro: ¿qué te falta aquí que allí te sobra?","ar":"هذه إجابة جميلة. وهي أيضًا إجابة من يريد عرضًا مضادًا. ولست غاضبة منك، انتبه؛ فهذا حقك. لكن لنتحدث بصراحة: ما الذي ينقصك هنا ومتوفر عندهم هناك؟"},{"speaker":"paco","es":"Dos cosas. El sueldo, un treinta por ciento. Y liderar el equipo nuevo que están montando. Aquí hago el trabajo de líder sin el título ni el sueldo desde hace dos años.","ar":"شيئان. الراتب، ثلاثون في المئة. وقيادة الفريق الجديد الذي يُنشئونه. منذ سنتين وأنا أؤدي عمل القائد هنا دون اللقب ولا الراتب."},{"speaker":"luna","es":"Lo del título te lo debo, es verdad. Lo del sueldo, un treinta por ciento no puedo dártelo mañana. Puedo darte el título este mes y una revisión salarial seria en enero, con números por escrito.","ar":"اللقب أنا متأخرة فيه لك، هذا صحيح. أما الراتب، فثلاثون في المئة لا أستطيع إعطاءه لك غدًا. أستطيع أن أعطيك اللقب هذا الشهر ومراجعة راتب جدية في يناير، بأرقام مكتوبة."},{"speaker":"paco","es":"¿Y quién me garantiza a mí que enero no vaya a ser como la última vez, cuando la revisión se quedó en agua de borrajas?","ar":"وما الذي يضمن لي أن يناير لن يكون كالمرة الماضية، حين ذهبت المراجعة أدراج الرياح وظلت مجرد كلام؟"},{"speaker":"luna","es":"Que esta vez te doy el título primero, que eso sí está en mi mano y no se desdice. Y que si en enero el número no te convence, yo misma te escribo la recomendación para donde quieras ir. Eso no te lo ofrece nadie.","ar":"أنني هذه المرة سأعطيك اللقب أولًا، وهذا في يدي فعلًا ولا يستطيع أحد التراجع عنه. وإن لم يعجبك الرقم في يناير، فسأكتب لك بنفسي خطاب توصية إلى أي مكان تريد الذهاب إليه. هذا لن يعرضه عليك أحد."},{"speaker":"paco","es":"¿Sabes que tu oferta es tan buena que casi me desarma?","ar":"أتعلمين أن عرضك جيد لدرجة أنه جعلني لا أعرف كيف أرد تقريبًا؟"},{"speaker":"luna","es":"Es que no te quiero convencido, Paco. Te quiero con los ojos abiertos. Si te quedas, te quedas sabiendo lo que tienes. Y si te vas, que te vayas bien, que la vida da muchas vueltas y prefiero que nos veamos otra vez en buenos términos.","ar":"لأنني لا أريدك مقتنعًا يا باكو. أريدك فاتحًا عينيك. إن بقيت، فابقَ وأنت تعلم ما معك. وإن رحلت، فارحل على خير، لأن الدنيا صغيرة، وأنا أريد أن نتقابل مرة أخرى ونحن على خير."},{"speaker":"paco","es":"Vale. Dame el lunes para pensarlo. El título, mientras tanto, lo acepto desde ya.","ar":"حسنًا. أعطيني حتى يوم الاثنين أفكر. اللقب، في أثناء ذلك، أوافق عليه من الآن."}],"questions":[{"q":"لماذا أخبر باكو لونا بنفسه عن العرض؟","options":["ليستقيل فورًا ويرحل في اليوم نفسه","ليفتخر أمامها بالعرض الذي جاءه","ليصلها منه هو قبل أن يصلها من شخص آخر، ويفتح باب التفاوض"],"answer":"ليصلها منه هو قبل أن يصلها من شخص آخر، ويفتح باب التفاوض","rationale":"قال إنه فضّل أن يقولها بنفسه «antes de que llegue» أي قبل أن يصلها من شخص آخر، وإنه جاء ليعرف إن كان مكانه لا يزال هنا."},{"q":"لونا حددت الموقف بجملة واحدة، فما هي؟","options":["«ممنوع أن تترك الشركة مهما حدث، اتفقنا؟»","«جئت لتقول لي مع السلامة أم لتفاوضني؟»","«بكم العرض بالضبط؟ قُل لي الرقم الآن»"],"answer":"«جئت لتقول لي مع السلامة أم لتفاوضني؟»","rationale":"«¿vienes a despedirte o a negociar?» فرّقت بين سيناريوهين: الوداع مكانه الموارد البشرية والتفاوض معها."},{"q":"ما الذي يطالبه باكو بالضبط؟","options":["اللقب والراتب، لأنه منذ سنتين يؤدي عمل القائد دونهما","مكتب أكبر وسائق خاص بالشركة","إجازات أطول من التي يأخذها الآن"],"answer":"اللقب والراتب، لأنه منذ سنتين يؤدي عمل القائد دونهما","rationale":"قال إنه يؤدي عمل القائد «sin el título ni el sueldo» أي دون اللقب ولا الراتب منذ سنتين."},{"q":"لماذا شك باكو في وعد يناير؟","options":["لأنه لا يحب شهر يناير من الأساس ويكره البرد","لأن الشركة على وشك الإفلاس وستغلق أبوابها قريبًا","لأن مراجعة المرة الماضية ظلت مجرد كلام"],"answer":"لأن مراجعة المرة الماضية ظلت مجرد كلام","rationale":"قال إن المرة الماضية المراجعة «se quedó en agua de borrajas» أي ذهبت أدراج الرياح ولم يحدث منها شيء."},{"q":"ما الضمان الذي قدمته لونا؟","options":["حصة وأسهم كاملة في الشركة","اللقب فورًا لأنه في يدها، وإن لم يعجبه رقم يناير ستكتب له توصية بنفسها","ضعف الراتب فورًا من أول الشهر القادم"],"answer":"اللقب فورًا لأنه في يدها، وإن لم يعجبه رقم يناير ستكتب له توصية بنفسها","rationale":"قالت «te doy el título» أولًا، وإنها بنفسها «te escribo la recomendación» إن لم يعجبه رقم يناير. لا أسهم ولا ضعف راتب."},{"q":"جملة لونا «no te quiero convencido... te quiero con los ojos abiertos» معناها ماذا؟","options":["لا تريده يبقى غصبًا عنه؛ تريده فاتحًا عينيه","أنها غير مهتمة به شخصيًا إطلاقًا ولا بمستقبله","أنها تريده أن يرحل في أقرب وقت ممكن"],"answer":"لا تريده يبقى غصبًا عنه؛ تريده فاتحًا عينيه","rationale":"وكمّلت «te quedas sabiendo lo que tienes» أي ستبقى وأنت تعلم ما معك، وإن رحلت فارحل على خير."}]},{"id":"c2-cena-familiar","level":"C2","title":"الخبر على العشاء","desc":"في عشاء عائلي، يعلن باكو أنه ولونا سيسافران للعيش خارج إسبانيا، وردود فعل أهلهما تقول أكثر من كلامهم.","lines":[{"speaker":"paco","es":"Bueno, ya que estáis todos, mamá, papá... tenemos algo que contaros. Nos vamos a vivir fuera. A Chile.","ar":"حسنًا، ما دمنا جميعًا موجودين، يا ماما يا بابا... عندنا خبر نقوله. نحن مسافرون للعيش في الخارج. في تشيلي."},{"speaker":"luna","es":"Me ha salido un puesto allí. Es una oportunidad que no se da dos veces.","ar":"جاءني منصب هناك. فرصة لا تتكرر مرتين."},{"speaker":"paco","es":"Mamá, di algo.","ar":"يا ماما، قولي شيئًا."},{"speaker":"luna","es":"Es normal que necesiten un momento.","ar":"طبيعي أن يحتاجوا لحظة."},{"speaker":"paco","es":"Un momento sí. Silencio total, no.","ar":"لحظة نعم. صمت كامل، لا."},{"speaker":"luna","es":"Paco, tranquilo.","ar":"يا باكو اهدأ."},{"speaker":"paco","es":"Es que ya sé lo que viene: que si estamos locos, que si los nietos, que si aquí tienes todo. Llevamos meses pensándolo, no es un capricho.","ar":"لأنني أعرف ما هو قادم: أننا مجانين، والأحفاد، وأن عندك هنا كل شيء. نحن نفكر في هذا منذ أشهر، إنه ليس نزوة."},{"speaker":"luna","es":"Y aun así, es su derecho llevarse una sorpresa. Nosotros tuvimos meses; ellos han tenido diez segundos.","ar":"ومع ذلك، من حقهم أن يتفاجئوا. نحن كان عندنا أشهر؛ هم عندهم عشر ثوانٍ."},{"speaker":"paco","es":"Tienes razón. Perdón. Es que... yo también estoy asustado, ¿sabes? Y cuando me asusto me pongo a la defensiva.","ar":"معك حق. عذرًا. لأنني... أنا أيضًا خائف، أتعلمين؟ وحين أخاف أدخل في وضع الدفاع."},{"speaker":"luna","es":"Pues diles eso. Diles que estás asustado y que aun así lo vas a hacer. Eso lo entiende cualquier madre mejor que un discurso.","ar":"إذن قل لهم ذلك. قل لهم إنك خائف ومع ذلك ستفعلها. هذا تفهمه أي أم أفضل من أي خطاب."},{"speaker":"paco","es":"Mamá... estoy asustado. Y aun así quiero ir. Y necesito que no me lo pongas más difícil, porque me cuesta lo mío ya.","ar":"يا ماما... أنا خائف. ومع ذلك أريد أن أذهب. وأحتاج ألا تصعّبيها عليّ أكثر، لأن الموضوع صعب عليّ بما يكفي."},{"speaker":"luna","es":"Y yo os prometo que, por muy lejos que esté Chile (que no está en la luna, aunque lo parezca), habrá vuelos y videollamadas.","ar":"وأنا أعدكم أنه مهما كانت تشيلي بعيدة، وهي ليست على القمر ولو بدت كذلك، سيكون هناك طيران ومكالمات فيديو."},{"speaker":"paco","es":"Bueno, mamá, ahora sí: ¿qué dices?","ar":"حسنًا يا ماما، الآن حقًا: ماذا تقولين؟"}],"questions":[{"q":"ما الخبر الذي أُعلن على العشاء؟","options":["باكو فُصل من عمله فجأة الأسبوع الماضي ودون تعويض","باكو ولونا مسافران للعيش في تشيلي بسبب منصب لونا","لونا حامل في أشهرها الأولى والعائلة ستكبر"],"answer":"باكو ولونا مسافران للعيش في تشيلي بسبب منصب لونا","rationale":"«Nos vamos a vivir fuera. A Chile» و«Me ha salido un puesto allí» أي إنه جاءها منصب هناك. لم يُذكر حمل ولا فصل."},{"q":"ما كان رد فعل أم باكو الأول؟","options":["صمت تام","فرحت وبكت من الفرحة فورًا","تشاجرت مع باكو على السفر"],"answer":"صمت تام","rationale":"قال باكو إن الذي ضايقه هو «Silencio total» أي سكوتها التام، ولهذا قال لها «di algo»."},{"q":"لماذا انزعج باكو من الصمت؟","options":["لأن أمه دائمًا تتأخر في الرد عليه في كل شيء","لأن الطعام يبرد على الطاولة وهم صامتون","لأنه هو أيضًا خائف، والخوف يجعله يهاجم"],"answer":"لأنه هو أيضًا خائف، والخوف يجعله يهاجم","rationale":"اعترف أنه حين يخاف «me pongo a la defensiva» أي يدخل في وضع الدفاع والهجوم."},{"q":"لونا دافعت عن الأهل بجملة منصفة، فما هي؟","options":["«لنرحل من هنا فورًا»","«نحن كان عندنا أشهر؛ هم عندهم عشر ثوانٍ»","«أهلك لم يحبوك يومًا من الأساس»"],"answer":"«نحن كان عندنا أشهر؛ هم عندهم عشر ثوانٍ»","rationale":"قالت إنهم كان عندهم «meses» أي أشهر ليستوعبوا، والأهل عندهم «diez segundos» أي عشر ثوانٍ فقط."},{"q":"ما كانت نصيحة لونا لباكو؟","options":["يقول لأمه إنه خائف وسيفعلها مع ذلك، لأن الصدق يصل أفضل من الخطب","يكذب ويقول إنه غير خائف إطلاقًا","يؤجل السفر حتى توافق أمه"],"answer":"يقول لأمه إنه خائف وسيفعلها مع ذلك، لأن الصدق يصل أفضل من الخطب","rationale":"قالت إن هذا الكلام «lo entiende cualquier madre» أي إن أي أم ستفهمه، أفضل من خطاب مُتقَن."},{"q":"كيف تنتهي القصة؟","options":["الأم وافقت فورًا وباركت السفر","العائلة تشاجرت ومضى كل واحد في حاله","الأم لم ترد بعد، وباكو صار مستعدًا لسماعها"],"answer":"الأم لم ترد بعد، وباكو صار مستعدًا لسماعها","rationale":"القصة تنتهي بسؤال باكو «¿qué dices?» أي ماذا تقولين، دون أن نسمع رد أمه."}]},{"id":"c2-disculpas-anos","level":"C2","title":"اعتذار تأخر سنوات","desc":"بعد سنوات من القطيعة، يتصل باكو بلونا ليعتذر عن أمر قديم. ما لا يُقال أهم مما يُقال.","lines":[{"speaker":"paco","es":"Gracias por aceptar verme. No sabía si vendrías.","ar":"شكرًا لأنك وافقتِ على مقابلتي. لم أكن أعرف إن كنتِ ستأتين أم لا."},{"speaker":"luna","es":"Yo tampoco sabía si vendría. Y aquí estoy.","ar":"وأنا أيضًا لم أكن أعرف إن كنت سآتي أم لا. وها أنا قد جئت."},{"speaker":"paco","es":"Te debo una conversación desde hace seis años. Lo de aquella noche, lo que dije delante de todos...","ar":"أنا مدين لك بحديث منذ ست سنوات. موضوع تلك الليلة، ما قلته أمام الناس كلهم..."},{"speaker":"luna","es":"No hace falta que lo repitas. Me acuerdo palabra por palabra. Ese es el problema de las palabras así: quien las dice las olvida; quien las oye las archiva.","ar":"لا داعي لأن تعيده. أنا أذكره كلمة كلمة. هذه مشكلة الكلام من هذا النوع: من يقوله ينساه، ومن يسمعه يخزنه."},{"speaker":"paco","es":"No las he olvidado. Las he llevado todos estos años. Que es distinto.","ar":"أنا لم أنسَه. أنا حامله طوال هذه السنوات. وهذا شيء مختلف."},{"speaker":"luna","es":"¿Y a qué debo el honor, después de seis años?","ar":"وما سبب هذا الشرف بعد ست سنوات؟"},{"speaker":"paco","es":"A que estuve a punto de escribirte veinte veces y las veinte borré el mensaje. Y a que el mes pasado me enteré de lo de tu padre, y pensé: si mañana te pasara algo, me quedaría con esto dentro para siempre.","ar":"لأنني كدت أكتب لك عشرين مرة، وفي كل مرة مسحت الرسالة. ولأنني الشهر الماضي عرفت أمر والدك، وفكرت: لو حدث لك غدًا شيء، سأبقى حاملًا هذا بداخلي إلى الأبد."},{"speaker":"luna","es":"Así que vienes por ti. Para quitarte el peso.","ar":"إذن أنت جئت من أجل نفسك. لتزيل هذا الحِمل عن صدرك."},{"speaker":"paco","es":"Vengo por mí, sí. Quien te dice que se disculpa solo por el otro, miente. Pero vengo también por ti, aunque no tengas por qué creértelo hoy.","ar":"جئت من أجل نفسي، نعم. من يقول لك إنه يعتذر من أجل الآخر فقط، يكذب. لكنني جئت أيضًا من أجلك أنتِ، ولو لم يكن عليك أن تصدقي ذلك اليوم."},{"speaker":"luna","es":"Esa es la primera cosa honesta que me has dicho en años.","ar":"هذه أول كلمة صادقة قلتها لي منذ سنوات."},{"speaker":"paco","es":"No te pido que lo dejes atrás, que sería pedir demasiado. Ni que volvamos a ser lo que éramos. Te pido diez minutos de vez en cuando. Un café como este. Sin promesas.","ar":"لا أطلب منك أن تنسي، فهذا سيكون طلبًا كبيرًا. ولا أن نعود كما كنا. أطلب عشر دقائق من وقت لآخر. قهوة كهذه. دون وعود."},{"speaker":"luna","es":"¿Sabes qué es lo curioso? Que si me hubieras pedido perdón hace seis años, no te lo habría dado. Estaba demasiado enfadada para perdonar y demasiado orgullosa para admitir que te echaba de menos.","ar":"أتعرف ما الغريب؟ أنك لو طلبت مني السماح قبل ست سنوات، ما كنت سأعطيك إياه. كنت غاضبة جدًا لأسامح ومتكبرة جدًا لأعترف أنني كنت أفتقدك."},{"speaker":"paco","es":"¿Y ahora?","ar":"والآن؟"},{"speaker":"luna","es":"Ahora estoy cansada de llevarlo. Que no es lo mismo que perdonarte, ojo. Pero es un sitio donde se puede empezar.","ar":"الآن أنا سئمت من حمله. وهذا ليس المعنى نفسه أنني سامحتك، انتبه. لكنه مكان يمكن أن نبدأ منه."},{"speaker":"paco","es":"Me basta. De verdad, me basta.","ar":"يكفيني. حقًا، يكفيني."}],"questions":[{"q":"جملة لونا عن الكلام الجارح معناها ماذا؟","options":["من يقولها ينساها ومن يسمعها يخزنها","الكلام غير مهم ويُنسى بسرعة مهما كان جارحًا أو مؤلمًا","هي نسيت الموضوع منذ زمن تمامًا"],"answer":"من يقولها ينساها ومن يسمعها يخزنها","rationale":"«quien las dice las olvida» أي إن من يقول ينسى، وأكد باكو أنه حامل الكلام كل هذه السنوات."},{"q":"ما الذي حرّك باكو الآن بالذات؟","options":["رآها بالصدفة في الشارع الأسبوع الماضي وقرر أن يذهب ويعتذر لها","صديق مشترك بينهما نصحه أن يذهب ويعتذر لها","عرف أمر والد لونا وخاف أن يبقى حاملًا الندم إلى الأبد"],"answer":"عرف أمر والد لونا وخاف أن يبقى حاملًا الندم إلى الأبد","rationale":"قال إنه عرف «lo de tu padre» أي أمر والدها، وفكر: لو «te pasara algo» أي حدث لك شيء، سيبقى حاملًا الندم إلى الأبد."},{"q":"قالت له لونا إنه جاء من أجل نفسه. فما كان رده؟","options":["انزعج من الاتهام وقام ومضى من القهوة فورًا","اعترف أنه جاء من أجل نفسه، لكنه جاء من أجلها أيضًا","أنكر تمامًا وقال إنه جاء من أجلها هي فقط وليس من أجله أبدًا"],"answer":"اعترف أنه جاء من أجل نفسه، لكنه جاء من أجلها أيضًا","rationale":"«Vengo por mí, sí» أي جئت من أجلي، نعم، وقال إن من يدّعي غير ذلك «miente» أي يكذب. واعتبرت لونا هذا أول صدق منذ سنوات."},{"q":"لماذا لم تكن لونا ستسامحه قبل ست سنوات؟","options":["كانت غاضبة جدًا لتسامح ومتكبرة جدًا لتعترف أنها كانت تفتقده","كانت قد نسيت الموضوع تمامًا منذ زمن","كانت مسافرة خارج البلد طوال المدة"],"answer":"كانت غاضبة جدًا لتسامح ومتكبرة جدًا لتعترف أنها كانت تفتقده","rationale":"قالت إنها كانت غاضبة جدًا لتسامح ومتكبرة جدًا لتعترف أنها «te echaba de menos» أي إنها كانت تفتقده."},{"q":"قالت لونا «estoy cansada de llevarlo». ما معناها بالضبط؟","options":["سامحته نهائيًا وعاد كل شيء كما كان","قررت أنها لن تراه مرة أخرى أبدًا","سئمت من حمل الزعل، وهذه بداية لا مسامحة كاملة"],"answer":"سئمت من حمل الزعل، وهذه بداية لا مسامحة كاملة","rationale":"نبّهت أن هذا «no es lo mismo que perdonarte» أي ليس هو المسامحة نفسها، لكنه مكان يمكن أن نبدأ منه."},{"q":"ما الذي طلبه باكو في النهاية؟","options":["أن تنسى تمامًا ما حدث قبل ست سنوات وكأنه لم يحدث","عشر دقائق من وقت لآخر، قهوة كهذه، دون وعود","يعودا أصدقاء مقربين كما كانا ابتداءً من اليوم"],"answer":"عشر دقائق من وقت لآخر، قهوة كهذه، دون وعود","rationale":"«Te pido diez minutos de vez en cuando» أي عشر دقائق من وقت لآخر، وقال صراحة إنه لا يطلب العودة كما كانا."}]},{"id":"b1-cancelar-gimnasio","level":"B1","title":"إلغاء الاشتراك في النادي","desc":"تريد لونا إلغاء اشتراكها في النادي الرياضي، فيعرض عليها الموظف بدائل.","lines":[{"speaker":"luna","es":"Buenos días, quiero cancelar mi suscripción al gimnasio.","ar":"صباح الخير، أريد إلغاء اشتراكي في النادي الرياضي."},{"speaker":"paco","es":"Claro. ¿Puedo preguntarle el motivo?","ar":"بالتأكيد. هل يمكنني أن أسألكِ عن السبب؟"},{"speaker":"luna","es":"Casi no tengo tiempo y hace meses que no vengo.","ar":"لا أملك وقتًا تقريبًا، ومنذ أشهر لم آتِ."},{"speaker":"paco","es":"Lo entiendo. Podemos congelar la cuota durante unos meses si lo prefiere.","ar":"أفهم ذلك. يمكننا تجميد الاشتراك لبضعة أشهر إن أحببتِ."},{"speaker":"luna","es":"¿Y cuánto costaría congelarla?","ar":"وكم سيكلّف التجميد؟"},{"speaker":"paco","es":"Solo una pequeña parte de lo que paga ahora.","ar":"جزءًا صغيرًا فقط ممّا تدفعينه الآن."},{"speaker":"luna","es":"Aun así, prefiero cancelar. ¿Tengo que pagar alguna penalización?","ar":"ومع ذلك أفضّل الإلغاء. هل عليّ دفع غرامة؟"},{"speaker":"paco","es":"No, si avisa con tiempo. Y usted lo hace hoy, así que la baja será efectiva el mes que viene.","ar":"لا، إذا أبلغتِ مبكرًا. وأنتِ تفعلين ذلك اليوم، لذا سيصبح الإلغاء ساريًا في الشهر القادم."},{"speaker":"luna","es":"Perfecto. ¿Necesito firmar algo?","ar":"ممتاز. هل أحتاج إلى توقيع شيء؟"},{"speaker":"paco","es":"Sí, este formulario. Y tiene que devolver la tarjeta de acceso.","ar":"نعم، هذا النموذج. وعليكِ إعادة بطاقة الدخول."},{"speaker":"luna","es":"Aquí la tiene. Muchas gracias por su ayuda.","ar":"تفضّل، ها هي. شكرًا جزيلًا على مساعدتك."},{"speaker":"paco","es":"A usted. Si cambia de opinión, será bienvenida.","ar":"بل شكرًا لكِ. وإذا غيّرتِ رأيكِ فأهلًا بكِ."}],"questions":[{"q":"لماذا تريد لونا إلغاء الاشتراك؟","options":["السعر مرتفع جدًا","لا تملك وقتًا ولم تحضر منذ أشهر","ستنتقل إلى مدينة أخرى"],"answer":"لا تملك وقتًا ولم تحضر منذ أشهر","rationale":"قالت «Casi no tengo tiempo y hace meses que no vengo»، أي أنها لا تملك وقتًا ولم تحضر منذ أشهر. لم تذكر السعر ولا الانتقال."},{"q":"ما الذي اقترحه الموظف أولًا؟","options":["تجميد الاشتراك لبضعة أشهر","تخفيض السعر إلى النصف","الانتقال إلى فرع آخر"],"answer":"تجميد الاشتراك لبضعة أشهر","rationale":"قال «Podemos congelar la cuota durante unos meses»، أي يمكن تجميد الاشتراك لبضعة أشهر."},{"q":"هل ستدفع لونا غرامة؟","options":["نعم، غرامة ثابتة","لا، لأنها أبلغت مبكرًا","نعم، نصف قيمة الاشتراك"],"answer":"لا، لأنها أبلغت مبكرًا","rationale":"قال الموظف «No, si avisa con tiempo»، فلا غرامة لمن يبلّغ مبكرًا، ولونا تفعل ذلك اليوم."},{"q":"ماذا عليها أن تفعل قبل الانصراف؟","options":["دفع المبلغ المتبقي","إحضار صورة من الهوية","توقيع نموذج وإعادة بطاقة الدخول"],"answer":"توقيع نموذج وإعادة بطاقة الدخول","rationale":"قال «este formulario. Y tiene que devolver la tarjeta de acceso»، أي توقيع النموذج وإعادة بطاقة الدخول."}]},{"id":"b2-sala-reuniones","level":"B2","title":"قاعة الاجتماعات المحجوزة مرتين","desc":"تجد لونا فريقًا آخر داخل القاعة التي حجزتها، فيحاول الموظف حلّ المشكلة.","lines":[{"speaker":"luna","es":"Buenos días. Tenía reservada la sala de reuniones, pero hay otro equipo dentro.","ar":"صباح الخير. كنت قد حجزت قاعة الاجتماعات، لكن هناك فريقًا آخر بداخلها."},{"speaker":"paco","es":"Vaya, lo siento. Déjeme comprobar el sistema.","ar":"آسف جدًا. اسمحي لي أن أتحقق من النظام."},{"speaker":"paco","es":"Efectivamente, hay un error: la reserva aparece duplicada.","ar":"فعلًا، هناك خطأ: الحجز يظهر مكرّرًا."},{"speaker":"luna","es":"Es la tercera vez este mes. Mi equipo lleva media hora esperando.","ar":"هذه ثالث مرة هذا الشهر. وفريقي ينتظر منذ نصف ساعة."},{"speaker":"paco","es":"Entiendo su enfado. Puedo ofrecerle la sala pequeña de la planta baja ahora mismo.","ar":"أتفهّم غضبكِ. يمكنني أن أعرض عليكِ القاعة الصغيرة في الطابق الأرضي حالًا."},{"speaker":"luna","es":"Es demasiado pequeña. Somos un equipo grande y necesitamos el proyector.","ar":"إنها صغيرة جدًا. فريقنا كبير ونحتاج إلى جهاز العرض."},{"speaker":"paco","es":"En ese caso, la sala grande quedará libre dentro de un cuarto de hora.","ar":"في هذه الحالة، ستصبح القاعة الكبيرة متاحة بعد ربع ساعة."},{"speaker":"luna","es":"Está bien, esperaremos. Pero quiero que quede constancia de la queja por escrito.","ar":"حسنًا، سننتظر. لكنني أريد أن تُسجَّل الشكوى كتابةً."},{"speaker":"paco","es":"Por supuesto. Le enviaré un correo para que lo confirme, y avisaré al responsable del sistema.","ar":"بالتأكيد. سأرسل إليكِ رسالة بريد لتؤكّديها، وسأُبلغ المسؤول عن النظام."},{"speaker":"luna","es":"Se lo agradezco. Y que no vuelva a ocurrir.","ar":"أشكرك. وأرجو ألّا يتكرّر ذلك."},{"speaker":"paco","es":"Haré todo lo posible para que no se repita.","ar":"سأبذل ما في وسعي حتى لا يتكرّر."}],"questions":[{"q":"ما سبب المشكلة؟","options":["القاعة مغلقة للصيانة","الحجز مكرّر فدخل فريق آخر القاعة","لونا وصلت في الموعد الخطأ"],"answer":"الحجز مكرّر فدخل فريق آخر القاعة","rationale":"قال الموظف «la reserva aparece duplicada»، أي أن الحجز مكرّر، ولذلك كان فريق آخر داخل القاعة."},{"q":"لماذا ترفض لونا القاعة الصغيرة؟","options":["لأنها بعيدة","لأنها لا تتّسع لفريق كبير ولا يوجد فيها جهاز عرض","لأنها محجوزة أيضًا"],"answer":"لأنها لا تتّسع لفريق كبير ولا يوجد فيها جهاز عرض","rationale":"قالت «Es demasiado pequeña. Somos un equipo grande y necesitamos el proyector»."},{"q":"ماذا تقرّر لونا في النهاية؟","options":["إلغاء الاجتماع","الانتظار حتى تصبح القاعة الكبيرة متاحة","إجراء الاجتماع في الممر"],"answer":"الانتظار حتى تصبح القاعة الكبيرة متاحة","rationale":"قالت «Está bien, esperaremos»، فهي ستنتظر ربع ساعة حتى تُخلى القاعة الكبيرة."},{"q":"ماذا تطلب لونا بخصوص الشكوى؟","options":["أن تُسجَّل كتابةً","أن تُحذف من النظام","أن تُرسل إلى فريقها"],"answer":"أن تُسجَّل كتابةً","rationale":"قالت «quiero que quede constancia de la queja por escrito»، أي أن تُسجَّل الشكوى كتابةً."}]},{"id":"c1-teletrabajo-propuesta","level":"C1","title":"اقتراح العمل عن بُعد","desc":"تعرض لونا على مديرها اقتراحًا لتغيير جدول عملها مدعومًا بتقرير عن أدائها.","lines":[{"speaker":"luna","es":"¿Tiene un momento? Quería plantearle una propuesta sobre mi horario.","ar":"هل لديك لحظة؟ أردت أن أطرح عليك اقتراحًا بشأن جدول عملي."},{"speaker":"paco","es":"Claro, adelante. Cuénteme.","ar":"بالطبع، تفضّلي. أخبريني."},{"speaker":"luna","es":"Desde que cambió el equipo, paso mucho tiempo en desplazamientos. Me gustaría teletrabajar algunos días por semana.","ar":"منذ أن تغيّر الفريق وأنا أقضي وقتًا طويلًا في التنقّل. وأودّ العمل عن بُعد بضعة أيام في الأسبوع."},{"speaker":"paco","es":"Lo entiendo, pero la dirección se ha mostrado reticente a ampliar el teletrabajo.","ar":"أتفهّم ذلك، لكن الإدارة كانت متردّدة في توسيع العمل عن بُعد."},{"speaker":"luna","es":"Lo sé. Por eso he preparado un informe con los resultados de los últimos meses, para demostrar que mi rendimiento no se ve afectado.","ar":"أعرف ذلك. لهذا أعددت تقريرًا بنتائج الأشهر الأخيرة لأثبت أن أدائي لا يتأثر."},{"speaker":"paco","es":"Aprecio la iniciativa. ¿Y cómo garantizaría la coordinación con el resto del equipo?","ar":"أقدّر هذه المبادرة. وكيف ستضمنين التنسيق مع بقية الفريق؟"},{"speaker":"luna","es":"Estaría disponible en las reuniones clave y mantendría abiertos los canales de comunicación durante toda la jornada.","ar":"سأكون متاحة في الاجتماعات الأساسية، وسأُبقي قنوات التواصل مفتوحة طوال اليوم."},{"speaker":"paco","es":"No me opongo, pero necesito el visto bueno de recursos humanos.","ar":"لا أعارض، لكنني أحتاج إلى موافقة قسم الموارد البشرية."},{"speaker":"luna","es":"¿Podría presentarles la propuesta junto conmigo? Así evitaríamos malentendidos.","ar":"هل يمكنك تقديم الاقتراح معي؟ بهذا نتفادى سوء الفهم."},{"speaker":"paco","es":"De acuerdo. Propongo un periodo de prueba de unos meses y, si funciona, lo formalizamos.","ar":"موافق. أقترح فترة تجريبية لبضعة أشهر، وإن نجحت فإننا نُقرّها رسميًا."},{"speaker":"luna","es":"Me parece razonable. Gracias por escucharme.","ar":"يبدو ذلك معقولًا. شكرًا لإصغائك."}],"questions":[{"q":"ما الذي تطلبه لونا؟","options":["زيادة في الراتب","العمل عن بُعد بضعة أيام في الأسبوع","الانتقال إلى فريق آخر"],"answer":"العمل عن بُعد بضعة أيام في الأسبوع","rationale":"قالت «Me gustaría teletrabajar algunos días por semana»، أي العمل عن بُعد بضعة أيام أسبوعيًا."},{"q":"ما العقبة التي ذكرها المدير؟","options":["الإدارة متردّدة في توسيع العمل عن بُعد","ميزانية الشركة محدودة","لونا جديدة في الشركة"],"answer":"الإدارة متردّدة في توسيع العمل عن بُعد","rationale":"قال «la dirección se ha mostrado reticente a ampliar el teletrabajo»، أي أن الإدارة متردّدة."},{"q":"كيف تدعم لونا طلبها؟","options":["بتقرير عن نتائج الأشهر الأخيرة","بطلب من زملائها","بشهادة طبية"],"answer":"بتقرير عن نتائج الأشهر الأخيرة","rationale":"قالت «he preparado un informe con los resultados de los últimos meses»."},{"q":"ما الحلّ الذي يقترحه المدير في النهاية؟","options":["رفض الطلب نهائيًا","فترة تجريبية لبضعة أشهر ثم إقرارها إن نجحت","تأجيل القرار إلى العام القادم"],"answer":"فترة تجريبية لبضعة أشهر ثم إقرارها إن نجحت","rationale":"قال «Propongo un periodo de prueba de unos meses y, si funciona, lo formalizamos»."}]},{"id":"c2-premio-literario","level":"C2","title":"الجائزة الأدبية","desc":"تتحدّث لونا إلى صحفي عن فوزها بجائزة أدبية وعن قلقها من الشهرة.","lines":[{"speaker":"paco","es":"Enhorabuena por el premio. Imagino que no se lo esperaba.","ar":"مبروك على الجائزة. أظنّكِ لم تتوقّعيها."},{"speaker":"luna","es":"Para nada. Llevaba años escribiendo en la sombra, y de repente todo el mundo quiere entrevistarme.","ar":"أبدًا. قضيت سنوات أكتب في الظلّ، وفجأة يريد الجميع محاورتي."},{"speaker":"paco","es":"¿Le abruma tanta atención?","ar":"هل يُثقل عليكِ هذا القدر من الاهتمام؟"},{"speaker":"luna","es":"Un poco. Agradezco el reconocimiento, pero me inquieta que se hable más de mí que de la novela.","ar":"قليلًا. أقدّر هذا التكريم، لكنّه يقلقني أن يُتحدَّث عنّي أكثر ممّا يُتحدَّث عن الرواية."},{"speaker":"paco","es":"Es el precio de la notoriedad, supongo. ¿Cree que el premio cambiará su manera de escribir?","ar":"هذا ثمن الشهرة على ما أظن. هل تعتقدين أن الجائزة ستغيّر طريقتكِ في الكتابة؟"},{"speaker":"luna","es":"Ojalá que no. Temo caer en la tentación de escribir pensando en complacer al jurado.","ar":"أرجو ألّا تفعل. أخشى أن أنجرف إلى الكتابة بهدف إرضاء لجنة التحكيم."},{"speaker":"paco","es":"Algunos críticos sostienen que la novela es deliberadamente ambigua. ¿Está de acuerdo?","ar":"يرى بعض النقّاد أن الرواية غامضة عن قصد. هل توافقين؟"},{"speaker":"luna","es":"Más bien la considero honesta: la vida rara vez ofrece finales cerrados, y no veía por qué la ficción debía hacerlo.","ar":"بل أراها صادقة: فالحياة نادرًا ما تقدّم نهايات مغلقة، ولم أجد سببًا لأن يفعل الخيال ذلك."},{"speaker":"paco","es":"Una postura valiente, sobre todo en un mercado que premia lo previsible.","ar":"موقف شجاع، خاصة في سوق يكافئ ما يمكن توقّعه."},{"speaker":"luna","es":"Quizá, aunque confío en que los lectores agradezcan que no se les subestime.","ar":"ربما، لكنني أثق بأن القرّاء يقدّرون ألّا يُستهان بهم."}],"questions":[{"q":"كيف استقبلت لونا خبر الفوز؟","options":["توقّعته منذ زمن","فوجئت به تمامًا","لم تهتم به"],"answer":"فوجئت به تمامًا","rationale":"قالت «Para nada» ردًّا على أنها لم تتوقّعه، وأضافت أنها كانت تكتب في الظلّ منذ سنوات."},{"q":"ما الذي يقلقها في الاهتمام الإعلامي؟","options":["أن يُتحدَّث عنها أكثر من الرواية","أن تنخفض مبيعات الكتاب","أن يعرف الناس عنوانها"],"answer":"أن يُتحدَّث عنها أكثر من الرواية","rationale":"قالت «me inquieta que se hable más de mí que de la novela»."},{"q":"ما الذي تخشاه بشأن كتابتها المقبلة؟","options":["أن تنقطع عن الكتابة","أن تكتب لإرضاء لجنة التحكيم","أن تتأثر بآراء الأصدقاء"],"answer":"أن تكتب لإرضاء لجنة التحكيم","rationale":"قالت «Temo caer en la tentación de escribir pensando en complacer al jurado»."},{"q":"كيف تصف الرواية؟","options":["غامضة عن قصد لإرباك القارئ","صادقة لأن الحياة قلّما تقدّم نهايات مغلقة","سهلة وسريعة القراءة"],"answer":"صادقة لأن الحياة قلّما تقدّم نهايات مغلقة","rationale":"قالت «la considero honesta: la vida rara vez ofrece finales cerrados»."}]},{"id":"a1-tienda-de-ropa","level":"A1","title":"في متجر الملابس","desc":"تذهب لونا إلى متجر ملابس لتشتري بنطالًا، ويساعدها البائع في اختيار المقاس.","lines":[{"speaker":"luna","es":"Buenos días, busco unos pantalones.","ar":"صباح الخير، أبحث عن بنطال."},{"speaker":"paco","es":"¿Qué talla usa?","ar":"ما مقاسك؟"},{"speaker":"luna","es":"No sé. Normalmente llevo la talla mediana.","ar":"لا أعرف. عادةً ألبس المقاس المتوسط."},{"speaker":"paco","es":"Estos son muy bonitos. ¿Le gusta el color azul?","ar":"هذا جميل جدًا. هل يعجبك اللون الأزرق؟"},{"speaker":"luna","es":"Sí, me gusta mucho. ¿Puedo probarme los pantalones?","ar":"نعم، يعجبني كثيرًا. هل يمكنني أن أقيس البنطال؟"},{"speaker":"paco","es":"Claro. El probador está al fondo, a la derecha.","ar":"بالتأكيد. غرفة القياس في الخلف، على اليمين."},{"speaker":"luna","es":"Me quedan un poco grandes. ¿Tiene una talla más pequeña?","ar":"إنه واسع عليّ قليلًا. هل لديك مقاس أصغر؟"},{"speaker":"paco","es":"Sí, aquí tiene la talla pequeña.","ar":"نعم، تفضّلي المقاس الصغير."},{"speaker":"luna","es":"Perfecto, ahora están bien. ¿Cuánto cuestan?","ar":"ممتاز، الآن مناسب. كم سعره؟"},{"speaker":"paco","es":"Veinticinco euros. Puede pagar en la caja, allí.","ar":"خمسة وعشرون يورو. يمكنك الدفع عند الصندوق، هناك."}],"questions":[{"q":"ماذا تبحث عنه لونا؟","options":["حقيبة","بنطال","حذاء"],"answer":"بنطال","rationale":"قالت «busco unos pantalones»، أي أنها تبحث عن بنطال."},{"q":"ما المقاس الذي تلبسه لونا عادةً؟","options":["المقاس المتوسط","المقاس الصغير","المقاس الكبير"],"answer":"المقاس المتوسط","rationale":"قالت «Normalmente llevo la talla mediana»، أي المقاس المتوسط."},{"q":"لماذا تطلب لونا مقاسًا آخر؟","options":["لأن اللون لا يعجبها","لأن البنطال واسع عليها قليلًا","لأن السعر مرتفع"],"answer":"لأن البنطال واسع عليها قليلًا","rationale":"قالت «Me quedan un poco grandes»، أي أنه واسع عليها قليلًا."},{"q":"كم سعر البنطال؟","options":["خمسة عشر يورو","عشرون يورو","خمسة وعشرون يورو"],"answer":"خمسة وعشرون يورو","rationale":"قال البائع «Veinticinco euros»، أي خمسة وعشرين يورو."}]},{"id":"a1-billete-de-tren","level":"A1","title":"تذكرة قطار إلى بلنسية","desc":"تريد لونا السفر إلى بلنسية غدًا، فتسأل موظف المحطة عن التذاكر والأوقات.","lines":[{"speaker":"luna","es":"Buenas tardes, quiero un billete para Valencia, por favor.","ar":"مساء الخير، أريد تذكرة إلى بلنسية، من فضلك."},{"speaker":"paco","es":"¿Para qué día?","ar":"لأي يوم؟"},{"speaker":"luna","es":"Para mañana por la mañana.","ar":"لغدٍ صباحًا."},{"speaker":"paco","es":"Hay un tren a las ocho y otro a las diez.","ar":"هناك قطار في الثامنة وآخر في العاشرة."},{"speaker":"luna","es":"Prefiero el de las ocho. ¿Cuánto dura el viaje?","ar":"أفضّل قطار الثامنة. كم تستغرق الرحلة؟"},{"speaker":"paco","es":"Dos horas y media, más o menos.","ar":"ساعتان ونصف تقريبًا."},{"speaker":"luna","es":"Muy bien. ¿Cuánto cuesta el billete?","ar":"جيد جدًا. كم سعر التذكرة؟"},{"speaker":"paco","es":"Treinta euros. ¿Ida y vuelta?","ar":"ثلاثون يورو. ذهاب وعودة؟"},{"speaker":"luna","es":"No, solo de ida. ¿De qué vía sale el tren?","ar":"لا، ذهاب فقط. من أي رصيف ينطلق القطار؟"},{"speaker":"paco","es":"De la vía cuatro. Venga un poco antes, por favor.","ar":"من الرصيف الرابع. تعالي قبل الموعد بقليل، من فضلك."}],"questions":[{"q":"إلى أين تريد لونا أن تسافر؟","options":["إلى مدريد","إلى بلنسية","إلى إشبيلية"],"answer":"إلى بلنسية","rationale":"قالت «quiero un billete para Valencia»، أي تذكرة إلى بلنسية."},{"q":"أي قطار تختار لونا؟","options":["قطار الثامنة","قطار العاشرة","قطار الظهر"],"answer":"قطار الثامنة","rationale":"قالت «Prefiero el de las ocho»، أي تفضّل قطار الثامنة."},{"q":"كم تستغرق الرحلة؟","options":["ساعة واحدة","ساعتان ونصف","ثلاث ساعات"],"answer":"ساعتان ونصف","rationale":"قال الموظف «Dos horas y media, más o menos»."},{"q":"من أي رصيف ينطلق القطار؟","options":["الرصيف الثاني","الرصيف الثالث","الرصيف الرابع"],"answer":"الرصيف الرابع","rationale":"قال «De la vía cuatro»، أي من الرصيف الرابع."}]},{"id":"a1-primera-clase","level":"A1","title":"أول درس في الإسبانية","desc":"تدخل لونا إلى صف اللغة الإسبانية للمرة الأولى، فيرحّب بها المعلّم ويسألها عن اسمها.","lines":[{"speaker":"paco","es":"Buenos días. ¿Es usted alumna nueva?","ar":"صباح الخير. هل أنت طالبة جديدة؟"},{"speaker":"luna","es":"Sí, hoy es mi primera clase.","ar":"نعم، اليوم درسي الأول."},{"speaker":"paco","es":"Bienvenida. Me llamo Paco y soy el profesor. ¿Cómo se llama usted?","ar":"أهلًا بك. اسمي باكو وأنا المعلّم. ما اسمك؟"},{"speaker":"luna","es":"Me llamo Luna. Soy de Egipto, pero vivo aquí.","ar":"اسمي لونا. أنا من مصر، لكنني أعيش هنا."},{"speaker":"paco","es":"¿Habla un poco de español?","ar":"هل تتحدثين الإسبانية قليلًا؟"},{"speaker":"luna","es":"Sí, un poco. Estudio en casa todos los días.","ar":"نعم، قليلًا. أدرس في البيت كل يوم."},{"speaker":"paco","es":"Muy bien. En clase hablamos solo en español.","ar":"جيد جدًا. في الصف نتحدث بالإسبانية فقط."},{"speaker":"luna","es":"¿Hay deberes para mañana?","ar":"هل هناك واجبات للغد؟"},{"speaker":"paco","es":"Sí, una página del libro. Y necesita un cuaderno.","ar":"نعم، صفحة من الكتاب. وتحتاجين إلى دفتر."},{"speaker":"luna","es":"De acuerdo. Muchas gracias, profesor.","ar":"حسنًا. شكرًا جزيلًا، أستاذ."}],"questions":[{"q":"من هي لونا في هذا الصف؟","options":["طالبة جديدة","المعلّمة","أم أحد الطلاب"],"answer":"طالبة جديدة","rationale":"قال المعلّم «¿Es usted alumna nueva?» وأجابت لونا «hoy es mi primera clase»."},{"q":"من أين لونا؟","options":["من المغرب","من مصر","من إسبانيا"],"answer":"من مصر","rationale":"قالت «Soy de Egipto, pero vivo aquí»."},{"q":"ماذا تفعل لونا كل يوم؟","options":["تشاهد التلفاز","تدرس الإسبانية في البيت","تعمل في مقهى"],"answer":"تدرس الإسبانية في البيت","rationale":"قالت «Estudio en casa todos los días»."},{"q":"ماذا تحتاج لونا للدرس القادم؟","options":["كتابًا فقط","دفترًا وواجبًا من صفحة واحدة","قاموسًا"],"answer":"دفترًا وواجبًا من صفحة واحدة","rationale":"قال المعلّم «una página del libro. Y necesita un cuaderno»، أي صفحة واجب ودفتر."}]},{"id":"a1-alquilar-una-bici","level":"A1","title":"استئجار دراجة","desc":"تستأجر لونا دراجة هوائية لساعتين، فيشرح لها الموظف السعر والطريق.","lines":[{"speaker":"luna","es":"Hola, quiero alquilar una bicicleta.","ar":"مرحبًا، أريد استئجار دراجة هوائية."},{"speaker":"paco","es":"¿Por cuánto tiempo?","ar":"لأي مدة؟"},{"speaker":"luna","es":"Dos horas, por favor.","ar":"ساعتين، من فضلك."},{"speaker":"paco","es":"Son cinco euros. Necesito su documento de identidad.","ar":"خمسة يورو. أحتاج إلى وثيقة هويتك."},{"speaker":"luna","es":"Aquí está. ¿Hay un camino bonito cerca?","ar":"ها هي. هل هناك طريق جميل قريب؟"},{"speaker":"paco","es":"Sí, el parque está muy cerca. Puede ir por esta calle.","ar":"نعم، الحديقة قريبة جدًا. يمكنك الذهاب عبر هذا الشارع."},{"speaker":"luna","es":"¿Y dónde dejo la bicicleta cuando vuelvo?","ar":"وأين أترك الدراجة عندما أعود؟"},{"speaker":"paco","es":"Aquí mismo, delante de la tienda.","ar":"هنا تمامًا، أمام المتجر."},{"speaker":"luna","es":"Vale. ¿La bicicleta tiene luces?","ar":"حسنًا. هل للدراجة أضواء؟"},{"speaker":"paco","es":"Sí, y también un candado. El casco es obligatorio.","ar":"نعم، وأيضًا قفل. والخوذة إلزامية."}],"questions":[{"q":"لكم من الوقت تستأجر لونا الدراجة؟","options":["ساعة واحدة","ساعتين","يومًا كاملًا"],"answer":"ساعتين","rationale":"قالت «Dos horas, por favor»، أي ساعتين."},{"q":"كم سعر الاستئجار؟","options":["خمسة يورو","عشرة يورو","خمسة عشر يورو"],"answer":"خمسة يورو","rationale":"قال الموظف «Son cinco euros»."},{"q":"ماذا تحتاج لونا لتستأجر الدراجة؟","options":["بطاقة مصرفية","جواز سفر","وثيقة هوية"],"answer":"وثيقة هوية","rationale":"قال الموظف «Necesito su documento de identidad»، أي وثيقة الهوية."},{"q":"أين تترك لونا الدراجة عند العودة؟","options":["في الحديقة","أمام المتجر","في محطة القطار"],"answer":"أمام المتجر","rationale":"قال «Aquí mismo, delante de la tienda»، أي أمام المتجر."}]},{"id":"a1-invitacion-a-cenar","level":"A1","title":"دعوة إلى العشاء","desc":"تتصل لونا بصديقها باكو لتدعوه إلى العشاء يوم السبت في بيتها.","lines":[{"speaker":"paco","es":"Sí, dígame.","ar":"ألو، نعم؟"},{"speaker":"luna","es":"Hola, Paco, soy Luna. ¿Cómo estás?","ar":"مرحبًا باكو، أنا لونا. كيف حالك؟"},{"speaker":"paco","es":"Muy bien, gracias. ¿Y tú?","ar":"بخير، شكرًا. وأنتِ؟"},{"speaker":"luna","es":"Bien. El sábado cocino en casa. ¿Quieres venir a cenar?","ar":"بخير. يوم السبت أطبخ في البيت. هل تريد أن تأتي للعشاء؟"},{"speaker":"paco","es":"Me encanta. ¿A qué hora?","ar":"يسعدني ذلك. في أي ساعة؟"},{"speaker":"luna","es":"A las nueve. Vivo cerca del parque, en la calle Mayor.","ar":"في التاسعة. أسكن قرب الحديقة، في شارع مايور."},{"speaker":"paco","es":"Perfecto. ¿Puedo llevar algo?","ar":"ممتاز. هل يمكنني أن أحضر شيئًا؟"},{"speaker":"luna","es":"Sí, una botella de agua, por favor.","ar":"نعم، زجاجة ماء، من فضلك."},{"speaker":"paco","es":"Vale. ¿Y quién más viene?","ar":"حسنًا. ومن سيأتي أيضًا؟"},{"speaker":"luna","es":"Solo nosotros dos. Mi hermana está de viaje.","ar":"نحن الاثنان فقط. أختي في رحلة."}],"questions":[{"q":"إلى ماذا تدعو لونا باكو؟","options":["إلى العشاء يوم السبت","إلى الغداء يوم الأحد","إلى فنجان قهوة صباحًا"],"answer":"إلى العشاء يوم السبت","rationale":"قالت «El sábado cocino en casa. ¿Quieres venir a cenar?»، أي عشاء في بيتها يوم السبت."},{"q":"في أي ساعة العشاء؟","options":["الثامنة","التاسعة","العاشرة"],"answer":"التاسعة","rationale":"قالت «A las nueve»، أي في التاسعة."},{"q":"ماذا تطلب لونا من باكو أن يحضر؟","options":["حلوى","عصيرًا","زجاجة ماء"],"answer":"زجاجة ماء","rationale":"قالت «una botella de agua, por favor»، أي زجاجة ماء."},{"q":"من سيأتي إلى العشاء؟","options":["أصدقاء كثيرون","هما فقط","أخت لونا"],"answer":"هما فقط","rationale":"قالت «Solo nosotros dos»، أي هما فقط، وأختها في رحلة."}]},{"id":"a1-en-la-peluqueria","level":"A1","title":"في صالون الحلاقة","desc":"تذهب لونا إلى صالون الحلاقة لتقصّ شعرها قبل حفلة صديقتها.","lines":[{"speaker":"luna","es":"Buenas tardes. ¿Tiene hora libre?","ar":"مساء الخير. هل لديك موعد متاح؟"},{"speaker":"paco","es":"Sí, ahora mismo. ¿Qué quiere hacer?","ar":"نعم، الآن مباشرة. ماذا تريدين أن نفعل؟"},{"speaker":"luna","es":"Quiero cortar el pelo, pero no muy corto.","ar":"أريد قصّ شعري، لكن ليس قصيرًا جدًا."},{"speaker":"paco","es":"De acuerdo. ¿Lo quiere lavar también?","ar":"حسنًا. هل تريدين غسله أيضًا؟"},{"speaker":"luna","es":"Sí, por favor. Mañana tengo una fiesta.","ar":"نعم، من فضلك. غدًا لديّ حفلة."},{"speaker":"paco","es":"Qué bien. ¿Una boda?","ar":"ما أجمل ذلك. زفاف؟"},{"speaker":"luna","es":"No, es el cumpleaños de una amiga.","ar":"لا، إنه عيد ميلاد صديقة."},{"speaker":"paco","es":"Ya está. ¿Le gusta?","ar":"انتهينا. هل يعجبك؟"},{"speaker":"luna","es":"Me gusta mucho. ¿Cuánto es?","ar":"يعجبني كثيرًا. كم المبلغ؟"},{"speaker":"paco","es":"Quince euros.","ar":"خمسة عشر يورو."}],"questions":[{"q":"ماذا تريد لونا أن تفعل بشعرها؟","options":["أن تصبغه","أن تقصّه قصيرًا جدًا","أن تقصّه قليلًا فقط"],"answer":"أن تقصّه قليلًا فقط","rationale":"قالت «Quiero cortar el pelo, pero no muy corto»، أي أنها تريد قصًّا غير قصير جدًا."},{"q":"لماذا تريد لونا أن تبدو جميلة غدًا؟","options":["لأن عندها مقابلة عمل","لأن غدًا عيد ميلاد صديقة","لأنها مسافرة"],"answer":"لأن غدًا عيد ميلاد صديقة","rationale":"قالت «Mañana tengo una fiesta» ثم «es el cumpleaños de una amiga»."},{"q":"كم سعر القصّ؟","options":["خمسة عشر يورو","عشرون يورو","عشرة يورو"],"answer":"خمسة عشر يورو","rationale":"قال الموظف «Quince euros»، أي خمسة عشر يورو."},{"q":"هل أعجب لونا الشعر الجديد؟","options":["لا، لم يعجبها","نعم، أعجبها كثيرًا","لم تقل شيئًا"],"answer":"نعم، أعجبها كثيرًا","rationale":"قالت «Me gusta mucho»، أي أنه أعجبها كثيرًا."}]},{"id":"a2-ver-un-piso","level":"A2","title":"زيارة شقة للإيجار","desc":"تزور لونا شقة معروضة للإيجار، ويسألها صاحب الشقة عن عملها وعن مدة العقد.","lines":[{"speaker":"paco","es":"Pase, pase. Esta es la sala.","ar":"تفضّلي، تفضّلي. هذه هي غرفة الجلوس."},{"speaker":"luna","es":"Es más grande. Pensé que era más pequeño. ¿Cuánto es el alquiler?","ar":"إنها أكبر. ظننتها أصغر. كم الإيجار؟"},{"speaker":"paco","es":"Seiscientos euros al mes, con los gastos incluidos.","ar":"ستمئة يورو شهريًا، والمصاريف مشمولة."},{"speaker":"luna","es":"No está mal. He visto pisos más caros en este barrio.","ar":"ليس سيئًا. لقد رأيت شققًا أغلى في هذا الحي."},{"speaker":"paco","es":"El piso está libre desde el mes pasado. La inquilina anterior se fue a otra ciudad.","ar":"الشقة متاحة منذ الشهر الماضي. المستأجرة السابقة انتقلت إلى مدينة أخرى."},{"speaker":"luna","es":"¿Y el contrato es por un año?","ar":"وهل العقد لمدة سنة؟"},{"speaker":"paco","es":"Sí, un año, y luego podemos renovarlo.","ar":"نعم، سنة، ثم يمكننا تجديده."},{"speaker":"luna","es":"Trabajo en una oficina cerca de aquí, así que me viene muy bien.","ar":"أعمل في مكتب قريب من هنا، لذا تناسبني كثيرًا."},{"speaker":"paco","es":"Perfecto. ¿Vive sola?","ar":"ممتاز. هل تعيشين وحدك؟"},{"speaker":"luna","es":"Sí, sola. ¿Puedo ver la cocina?","ar":"نعم، وحدي. هل يمكنني رؤية المطبخ؟"},{"speaker":"paco","es":"Claro, está al fondo. La nevera es nueva.","ar":"بالطبع، إنه في الخلف. الثلاجة جديدة."},{"speaker":"luna","es":"Me gusta mucho. Voy a pensarlo esta noche y mañana le llamo.","ar":"تعجبني كثيرًا. سأفكّر في الأمر الليلة وأتصل بك غدًا."}],"questions":[{"q":"كم إيجار الشقة شهريًا؟","options":["خمس مئة يورو","ستمئة يورو مع المصاريف","سبع مئة يورو بدون مصاريف"],"answer":"ستمئة يورو مع المصاريف","rationale":"قال صاحب الشقة «Seiscientos euros al mes, con los gastos incluidos»."},{"q":"لماذا الشقة متاحة الآن؟","options":["لأن المالك يبيعها","لأن الشقة جديدة","لأن المستأجرة السابقة انتقلت إلى مدينة أخرى"],"answer":"لأن المستأجرة السابقة انتقلت إلى مدينة أخرى","rationale":"قال «La inquilina anterior se fue a otra ciudad»."},{"q":"كم مدة العقد؟","options":["ستة أشهر","سنة قابلة للتجديد","سنتان"],"answer":"سنة قابلة للتجديد","rationale":"قال «un año, y luego podemos renovarlo»."},{"q":"ماذا ستفعل لونا بعد الزيارة؟","options":["ستوقّع العقد الآن","ستبحث عن شقة أخرى","ستفكّر في الأمر وتتصل غدًا"],"answer":"ستفكّر في الأمر وتتصل غدًا","rationale":"قالت «Voy a pensarlo esta noche y mañana le llamo»."},{"q":"ماذا قالت لونا عن الأسعار في هذا الحي؟","options":["رأت شققًا أغلى منه","لا تعرف الحي","الأسعار أرخص بكثير"],"answer":"رأت شققًا أغلى منه","rationale":"قالت «He visto pisos más caros en este barrio»، أي أنها رأت شققًا أغلى في هذا الحي."}]},{"id":"a2-devolver-unos-auriculares","level":"A2","title":"إرجاع سماعات معطوبة","desc":"ترجع لونا سماعات اشترتها قبل أسبوع لأن الصوت لا يعمل، فيشرح لها الموظف الخيارات.","lines":[{"speaker":"luna","es":"Buenos días. He comprado estos auriculares aquí la semana pasada y no funcionan.","ar":"صباح الخير. اشتريت هذه السماعات من هنا الأسبوع الماضي وهي لا تعمل."},{"speaker":"paco","es":"¿Qué les pasa exactamente?","ar":"ما المشكلة بالضبط؟"},{"speaker":"luna","es":"El auricular derecho no suena. Lo he probado con dos móviles.","ar":"السماعة اليمنى لا تصدر صوتًا. جرّبتها مع هاتفين."},{"speaker":"paco","es":"¿Tiene el recibo?","ar":"هل لديك الفاتورة؟"},{"speaker":"luna","es":"Sí, aquí está. También he traído la caja.","ar":"نعم، ها هي. وأحضرت العلبة أيضًا."},{"speaker":"paco","es":"Gracias. Puedo devolverle el dinero o cambiarle el producto. ¿Qué prefiere?","ar":"شكرًا. يمكنني إعادة المال إليك أو تبديل المنتج. ماذا تفضّلين؟"},{"speaker":"luna","es":"Prefiero unos iguales, si los tienen.","ar":"أفضّل زوجًا آخر مثله، إن كان لديكم."},{"speaker":"paco","es":"Voy a mirar en el almacén. Un momento, por favor.","ar":"سأتحقق في المخزن. لحظة من فضلك."},{"speaker":"paco","es":"Lo siento, de ese modelo no queda ninguno. Llegarán el jueves.","ar":"آسف، لم يبقَ أي واحد من هذا الطراز. ستصل يوم الخميس."},{"speaker":"luna","es":"Entonces prefiero el dinero. No puedo esperar hasta el jueves.","ar":"إذن أفضّل المال. لا أستطيع الانتظار حتى الخميس."},{"speaker":"paco","es":"De acuerdo. Firme aquí y el dinero vuelve a su tarjeta en dos días.","ar":"حسنًا. وقّعي هنا وسيعود المال إلى بطاقتك في يومين."},{"speaker":"luna","es":"Muchas gracias. Ha sido muy amable.","ar":"شكرًا جزيلًا. لقد كنت لطيفًا جدًا."}],"questions":[{"q":"ماذا اشترت لونا الأسبوع الماضي؟","options":["هاتفًا","حاسوبًا","سماعات"],"answer":"سماعات","rationale":"قالت «He comprado estos auriculares aquí la semana pasada»."},{"q":"ما المشكلة في السماعات؟","options":["اللون مختلف","السماعة اليمنى لا تصدر صوتًا","العلبة مفتوحة"],"answer":"السماعة اليمنى لا تصدر صوتًا","rationale":"قالت «El auricular derecho no suena»."},{"q":"ماذا يعرض عليها الموظف؟","options":["خصمًا على منتج آخر","إصلاحًا مجانيًا","إعادة المال أو تبديل المنتج"],"answer":"إعادة المال أو تبديل المنتج","rationale":"قال «Puedo devolverle el dinero o cambiarle el producto»."},{"q":"لماذا تختار لونا استعادة المال؟","options":["لأنها لا تحب الطراز","لأن الطراز سيصل يوم الخميس ولا تستطيع الانتظار","لأن السعر ارتفع"],"answer":"لأن الطراز سيصل يوم الخميس ولا تستطيع الانتظار","rationale":"قالت «No puedo esperar hasta el jueves»."},{"q":"متى يعود المال إلى بطاقتها؟","options":["في اليوم نفسه","في يومين","في أسبوع"],"answer":"في يومين","rationale":"قال «el dinero vuelve a su tarjeta en dos días»."}]},{"id":"a2-dia-de-mudanza","level":"A2","title":"يوم الانتقال","desc":"انتقلت لونا إلى شقة جديدة، ويساعدها صديقها باكو في حمل الأشياء وترتيب الغرفة.","lines":[{"speaker":"paco","es":"¡Cuántas cajas! ¿Dónde las pongo?","ar":"كم من الصناديق! أين أضعها؟"},{"speaker":"luna","es":"En el salón, por favor. Allí hay más sitio.","ar":"في غرفة الجلوس، من فضلك. هناك مساحة أكبر."},{"speaker":"paco","es":"Vale. ¿Has traído el sofá tú sola?","ar":"حسنًا. هل أحضرتِ الأريكة وحدكِ؟"},{"speaker":"luna","es":"No, mis vecinos me ayudaron esta mañana. Han sido muy amables.","ar":"لا، ساعدني جيراني هذا الصباح. كانوا لطفاء جدًا."},{"speaker":"paco","es":"Me alegro. ¿Y la cama ya está montada?","ar":"يسعدني ذلك. وهل رُكّب السرير؟"},{"speaker":"luna","es":"Todavía no. Voy a montarla esta tarde.","ar":"ليس بعد. سأركّبه بعد الظهر."},{"speaker":"paco","es":"Te ayudo, si quieres. He montado muchas camas en mi vida.","ar":"سأساعدك إن أردت. لقد ركّبت أسرّة كثيرة في حياتي."},{"speaker":"luna","es":"Gracias, Paco. ¿Tienes hambre? He comprado pizza.","ar":"شكرًا باكو. هل أنت جائع؟ اشتريت بيتزا."},{"speaker":"paco","es":"Mucho. No he comido nada desde las ocho.","ar":"كثيرًا. لم آكل شيئًا منذ الثامنة."},{"speaker":"luna","es":"Come algo mientras yo abro las cajas.","ar":"كل شيئًا بينما أفتح الصناديق."},{"speaker":"paco","es":"Está muy bien esta cocina. ¿Es nueva?","ar":"هذا المطبخ جميل جدًا. هل هو جديد؟"},{"speaker":"luna","es":"Sí, la cambiaron el año pasado. Por eso elegí este piso.","ar":"نعم، غيّروه العام الماضي. لهذا اخترت هذه الشقة."}],"questions":[{"q":"أين تضع لونا الصناديق؟","options":["في المطبخ","في غرفة الجلوس","في غرفة النوم"],"answer":"في غرفة الجلوس","rationale":"قالت «En el salón, por favor»، أي في غرفة الجلوس."},{"q":"من ساعد لونا في الصباح؟","options":["جيرانها","أخوها","باكو"],"answer":"جيرانها","rationale":"قالت «mis vecinos me ayudaron esta mañana»، أي أن جيرانها ساعدوها."},{"q":"ماذا ستفعل لونا بعد الظهر؟","options":["ستذهب إلى العمل","ستشتري أثاثًا","ستركّب السرير"],"answer":"ستركّب السرير","rationale":"قالت «Voy a montarla esta tarde»، أي ستركّب السرير بعد الظهر."},{"q":"منذ متى لم يأكل باكو؟","options":["منذ الثامنة","منذ يومين","منذ ساعة"],"answer":"منذ الثامنة","rationale":"قال «No he comido nada desde las ocho»."},{"q":"لماذا اختارت لونا هذه الشقة؟","options":["لأنها قريبة من العمل","لأن المطبخ جديد","لأن الإيجار رخيص"],"answer":"لأن المطبخ جديد","rationale":"قالت «la cambiaron el año pasado. Por eso elegí este piso»، أي لأن المطبخ جديد."}]},{"id":"a2-movil-perdido","level":"A2","title":"الهاتف المفقود","desc":"أضاعت لونا هاتفها في المقهى، فتذهب إلى مكتب المفقودات وتسأل الموظف عنه.","lines":[{"speaker":"luna","es":"Buenos días. He perdido mi móvil esta mañana en el café.","ar":"صباح الخير. أضعت هاتفي هذا الصباح في المقهى."},{"speaker":"paco","es":"¿En qué café ha estado?","ar":"في أي مقهى كنتِ؟"},{"speaker":"luna","es":"En el que está al lado de la plaza, el de la esquina.","ar":"في المقهى الذي بجانب الساحة، عند الزاوية."},{"speaker":"paco","es":"¿Cómo es el móvil?","ar":"كيف يبدو الهاتف؟"},{"speaker":"luna","es":"Es negro y tiene una funda azul. También tiene una pegatina en la parte de atrás.","ar":"إنه أسود وله غلاف أزرق. وفيه ملصق على الظهر."},{"speaker":"paco","es":"Un momento. Alguien trajo un móvil hace una hora.","ar":"لحظة. أحضر أحدهم هاتفًا قبل ساعة."},{"speaker":"luna","es":"¿Y está aquí?","ar":"وهو هنا؟"},{"speaker":"paco","es":"Sí. ¿Quiere llamar a su número desde aquí?","ar":"نعم. هل تريدين الاتصال برقمك من هنا؟"},{"speaker":"luna","es":"Sí, gracias. Lo tengo apuntado en un papel.","ar":"نعم، شكرًا. إنه مكتوب عندي على ورقة."},{"speaker":"paco","es":"Marque y si suena dentro, es suyo.","ar":"اتصلي، وإن رنّ في الداخل فهو لكِ."},{"speaker":"luna","es":"¡Suena! Es mi móvil. Muchas gracias.","ar":"إنه يرن! هذا هاتفي. شكرًا جزيلًا."},{"speaker":"paco","es":"De nada. La próxima vez, escriba su nombre en la funda.","ar":"لا شكر على واجب. في المرة القادمة اكتبي اسمك على الغلاف."}],"questions":[{"q":"أين أضاعت لونا هاتفها؟","options":["في محطة القطار","في المقهى قرب الساحة","في المكتبة"],"answer":"في المقهى قرب الساحة","rationale":"قالت «He perdido mi móvil esta mañana en el café»، ثم ذكرت المقهى «el de la esquina»."},{"q":"كيف يبدو الهاتف؟","options":["أسود بغلاف أزرق","أبيض بغلاف أسود","أزرق بغلاف أبيض"],"answer":"أسود بغلاف أزرق","rationale":"قالت «Es negro y tiene una funda azul»، أي أسود بغلاف أزرق."},{"q":"من أحضر الهاتف إلى المكتب؟","options":["لونا نفسها","باكو","شخص ما قبل ساعة"],"answer":"شخص ما قبل ساعة","rationale":"قال الموظف «Alguien trajo un móvil hace una hora»."},{"q":"كيف تتأكد لونا أن الهاتف لها؟","options":["بصورة على شاشته","برقم يعرفه الموظف","بأنها تتصل برقمها فيرن الهاتف"],"answer":"بأنها تتصل برقمها فيرن الهاتف","rationale":"قال الموظف «Marque y si suena dentro, es suyo»، فرنّ الهاتف وقالت «¡Suena!»."},{"q":"ماذا ينصحها الموظف في النهاية؟","options":["أن تكتب اسمها على الغلاف","أن تشتري هاتفًا جديدًا","أن تترك الهاتف في المكتب"],"answer":"أن تكتب اسمها على الغلاف","rationale":"قال «La próxima vez, escriba su nombre en la funda»، أي تكتب اسمها على الغلاف."}]},{"id":"a2-reservar-mesa","level":"A2","title":"حجز طاولة في مطعم","desc":"تتصل لونا بمطعم لتحجز طاولة لعيد ميلاد صديقتها، فيسألها الموظف عن العدد والوقت.","lines":[{"speaker":"paco","es":"Restaurante La Plaza, buenas tardes.","ar":"مطعم لا بلازا، مساء الخير."},{"speaker":"luna","es":"Hola, quería reservar una mesa para el viernes por la noche.","ar":"مرحبًا، أردت حجز طاولة لليلة الجمعة."},{"speaker":"paco","es":"¿Para cuántas personas?","ar":"لكم شخصًا؟"},{"speaker":"luna","es":"Para seis. Es el cumpleaños de una amiga.","ar":"لستة أشخاص. إنه عيد ميلاد صديقة."},{"speaker":"paco","es":"¿A qué hora prefiere?","ar":"أي ساعة تفضّلين؟"},{"speaker":"luna","es":"A las nueve, si es posible. Hemos quedado todos a esa hora.","ar":"في التاسعة إن أمكن. اتفقنا جميعًا على هذه الساعة."},{"speaker":"paco","es":"A las nueve estamos llenos. ¿Les va bien a las nueve y media?","ar":"في التاسعة نكون ممتلئين. هل تناسبكم التاسعة والنصف؟"},{"speaker":"luna","es":"Sí, no hay problema. ¿Podemos estar en la terraza?","ar":"نعم، لا مشكلة. هل يمكننا الجلوس في الشرفة؟"},{"speaker":"paco","es":"Si no llueve, sí. En abril todavía hace fresco por la noche.","ar":"إن لم تمطر، نعم. في أبريل لا يزال الجو باردًا ليلًا."},{"speaker":"luna","es":"Entiendo. ¿Hay menú para grupos?","ar":"أفهم. هل هناك قائمة للمجموعات؟"},{"speaker":"paco","es":"Sí, lo hemos preparado este mes. Traeré pastel al final, si quiere.","ar":"نعم، أعددناها هذا الشهر. سأحضر كعكة في النهاية إن أردت."},{"speaker":"luna","es":"¡Qué bien! Entonces la reserva es para seis a las nueve y media.","ar":"كم هذا رائع! إذن الحجز لستة أشخاص في التاسعة والنصف."}],"questions":[{"q":"لكم شخصًا تحجز لونا الطاولة؟","options":["لأربعة","لستة","لثمانية"],"answer":"لستة","rationale":"قالت «Para seis»، أي لستة أشخاص."},{"q":"ما المناسبة؟","options":["عيد ميلاد صديقة","زفاف","عشاء عمل"],"answer":"عيد ميلاد صديقة","rationale":"قالت «Es el cumpleaños de una amiga»."},{"q":"لماذا لا تكون الطاولة في التاسعة؟","options":["لأن المطعم مغلق","لأن الشرفة مغلقة","لأن المطعم ممتلئ في تلك الساعة"],"answer":"لأن المطعم ممتلئ في تلك الساعة","rationale":"قال الموظف «A las nueve estamos llenos»."},{"q":"أين تريد لونا أن تجلس؟","options":["داخل المطعم","في الشرفة","عند النافذة"],"answer":"في الشرفة","rationale":"قالت «¿Podemos estar en la terraza?»، أي في الشرفة."},{"q":"ما الذي يعرضه الموظف في النهاية؟","options":["كعكة","موسيقى","خصمًا"],"answer":"كعكة","rationale":"قال «Traeré pastel al final»، أي سيحضر كعكة في النهاية."}]},{"id":"a2-entrevista-de-trabajo","level":"A2","title":"مقابلة عمل","desc":"تتقدّم لونا لوظيفة نادلة في مقهى، ويسألها المدير عن خبرتها وعن أوقات عملها.","lines":[{"speaker":"paco","es":"Buenos días, siéntese, por favor. ¿Es usted Luna?","ar":"صباح الخير، تفضّلي بالجلوس. هل أنتِ لونا؟"},{"speaker":"luna","es":"Sí, buenos días. Gracias por recibirme.","ar":"نعم، صباح الخير. شكرًا لاستقبالك لي."},{"speaker":"paco","es":"¿Ha trabajado antes en un bar o en un restaurante?","ar":"هل عملتِ سابقًا في حانة أو مطعم؟"},{"speaker":"luna","es":"Sí, he trabajado dos años en una cafetería en El Cairo.","ar":"نعم، عملت سنتين في مقهى في القاهرة."},{"speaker":"paco","es":"¿Y por qué ha venido a España?","ar":"ولماذا أتيتِ إلى إسبانيا؟"},{"speaker":"luna","es":"Vine a estudiar español y ahora busco trabajo.","ar":"جئت لدراسة الإسبانية والآن أبحث عن عمل."},{"speaker":"paco","es":"¿Cuántos idiomas habla?","ar":"كم لغة تتحدثين؟"},{"speaker":"luna","es":"Hablo árabe, inglés y un poco de español.","ar":"أتحدث العربية والإنجليزية وقليلًا من الإسبانية."},{"speaker":"paco","es":"Muy bien. El trabajo es de martes a domingo, por la mañana.","ar":"جيد جدًا. العمل من الثلاثاء إلى الأحد، صباحًا."},{"speaker":"luna","es":"¿Puedo trabajar los sábados por la tarde también?","ar":"هل يمكنني العمل أيام السبت بعد الظهر أيضًا؟"},{"speaker":"paco","es":"Sí, los sábados tenemos mucho trabajo.","ar":"نعم، أيام السبت عندنا عمل كثير."},{"speaker":"paco","es":"Voy a hablar con mi socio y mañana le digo algo.","ar":"سأتحدث مع شريكي وأخبرك غدًا."},{"speaker":"luna","es":"Perfecto. Muchas gracias por su tiempo.","ar":"ممتاز. شكرًا جزيلًا على وقتك."}],"questions":[{"q":"أين عملت لونا سابقًا؟","options":["في مطعم في مدريد","في مقهى في القاهرة","في فندق في بلنسية"],"answer":"في مقهى في القاهرة","rationale":"قالت «he trabajado dos años en una cafetería en El Cairo»، أي عملت في مقهى في القاهرة."},{"q":"لماذا جاءت لونا إلى إسبانيا؟","options":["لدراسة الإسبانية","لزيارة عائلتها","للسياحة"],"answer":"لدراسة الإسبانية","rationale":"قالت «Vine a estudiar español»، أي جاءت لدراسة الإسبانية."},{"q":"كم لغة تتحدث لونا؟","options":["لغتان","ثلاث لغات","أربع لغات"],"answer":"ثلاث لغات","rationale":"قالت «Hablo árabe, inglés y un poco de español»، أي ثلاث لغات."},{"q":"ما أوقات العمل المطلوبة؟","options":["من الاثنين إلى الجمعة مساءً","كل يوم صباحًا","من الثلاثاء إلى الأحد صباحًا"],"answer":"من الثلاثاء إلى الأحد صباحًا","rationale":"قال «El trabajo es de martes a domingo, por la mañana»."},{"q":"ماذا تطلب لونا إضافة إلى ذلك؟","options":["العمل ليلًا","العمل أيام السبت بعد الظهر","زيادة في الراتب"],"answer":"العمل أيام السبت بعد الظهر","rationale":"قالت «¿Puedo trabajar los sábados por la tarde también?»، أي تطلب العمل أيام السبت بعد الظهر."},{"q":"متى سيعطيها المدير جوابًا؟","options":["غدًا بعد التحدث مع شريكه","الأسبوع القادم","الآن مباشرة"],"answer":"غدًا بعد التحدث مع شريكه","rationale":"قال «Voy a hablar con mi socio y mañana le digo algo»، أي سيخبرها غدًا بعد أن يتحدث مع شريكه."}]},{"id":"b1-tarjeta-bloqueada","level":"B1","title":"البطاقة المصرفية موقوفة","desc":"تحاول لونا الدفع في المتجر فترفض البطاقة، فتتصل بخدمة العملاء لتكتشف أن أحدًا حاول استخدام بياناتها.","lines":[{"speaker":"paco","es":"Banco Delta, buenos días. ¿En qué puedo ayudarle?","ar":"بنك دلتا، صباح الخير. كيف يمكنني مساعدتك؟"},{"speaker":"luna","es":"Buenos días. Mi tarjeta no funciona desde ayer. No puedo pagar nada.","ar":"صباح الخير. بطاقتي لا تعمل منذ أمس. لا أستطيع دفع أي شيء."},{"speaker":"paco","es":"¿Le aparece algún mensaje cuando intenta pagar?","ar":"هل تظهر لك رسالة عندما تحاولين الدفع؟"},{"speaker":"luna","es":"Sí, dice que la operación no está permitida.","ar":"نعم، تقول إن العملية غير مسموحة."},{"speaker":"paco","es":"Un momento. Veo que el sistema ha bloqueado la tarjeta por seguridad.","ar":"لحظة. أرى أن النظام أوقف البطاقة لأسباب أمنية."},{"speaker":"luna","es":"¿Por qué? Yo no he hecho nada raro.","ar":"لماذا؟ لم أفعل شيئًا غريبًا."},{"speaker":"paco","es":"Ayer hubo un intento de compra en otro país. El banco lo detectó y bloqueó la tarjeta.","ar":"أمس كانت هناك محاولة شراء في بلد آخر. اكتشف البنك ذلك وأوقف البطاقة."},{"speaker":"luna","es":"¡Qué susto! A esa hora yo estaba en casa.","ar":"يا للفزع! كنت في البيت في تلك الساعة."},{"speaker":"paco","es":"Entonces alguien tiene los datos de su tarjeta. Vamos a cancelarla y a enviarle una nueva.","ar":"إذن أحدهم لديه بيانات بطاقتك. سنلغيها ونرسل لك واحدة جديدة."},{"speaker":"luna","es":"¿Y cuánto tarda en llegar?","ar":"وكم تستغرق حتى تصل؟"},{"speaker":"paco","es":"Unos cinco días laborables. Mientras tanto, puede sacar dinero en la oficina con su documento.","ar":"نحو خمسة أيام عمل. وفي هذه الأثناء يمكنك سحب المال من المكتب بوثيقتك."},{"speaker":"luna","es":"Voy a necesitar dinero el viernes. ¿Es posible hoy mismo?","ar":"سأحتاج المال يوم الجمعة. هل هذا ممكن اليوم نفسه؟"},{"speaker":"paco","es":"Sí, ahora le preparo una autorización. Y no comparta sus datos por teléfono ni por correo.","ar":"نعم، سأعدّ لك تصريحًا الآن. ولا تشاركي بياناتك عبر الهاتف أو البريد."},{"speaker":"luna","es":"Lo tendré en cuenta. Muchas gracias.","ar":"سآخذ ذلك في الحسبان. شكرًا جزيلًا."}],"questions":[{"q":"ما المشكلة التي تواجه لونا؟","options":["بطاقتها لا تعمل ولا تستطيع الدفع","نسيت رقمها السري","أغلقت حسابها في البنك"],"answer":"بطاقتها لا تعمل ولا تستطيع الدفع","rationale":"قالت «Mi tarjeta no funciona desde ayer. No puedo pagar nada»."},{"q":"لماذا أوقف البنك البطاقة؟","options":["لأنها تجاوزت الحد المسموح","لأنها لم تسدد القرض","لأن هناك محاولة شراء في بلد آخر"],"answer":"لأن هناك محاولة شراء في بلد آخر","rationale":"قال الموظف «Ayer hubo un intento de compra en otro país»."},{"q":"أين كانت لونا وقت محاولة الشراء؟","options":["في البيت","في السفر","في العمل"],"answer":"في البيت","rationale":"قالت «A esa hora yo estaba en casa»."},{"q":"ماذا سيفعل البنك بالبطاقة؟","options":["سيصلحها","سيخفض الحد المسموح","سيُلغيها ويرسل واحدة جديدة"],"answer":"سيُلغيها ويرسل واحدة جديدة","rationale":"قال «Vamos a cancelarla y a enviarle una nueva»."},{"q":"كم تستغرق البطاقة الجديدة حتى تصل؟","options":["يومان","خمسة أيام عمل","أسبوعان"],"answer":"خمسة أيام عمل","rationale":"قال «Unos cinco días laborables»."},{"q":"ما الحل المؤقت الذي يقترحه الموظف؟","options":["سحب المال من المكتب بوثيقة الهوية","الدفع نقدًا فقط","استخدام بطاقة صديق"],"answer":"سحب المال من المكتب بوثيقة الهوية","rationale":"قال «puede sacar dinero en la oficina con su documento»."}]},{"id":"b1-cerrado-fuera-de-casa","level":"B1","title":"الباب المغلق في منتصف الليل","desc":"تعود لونا إلى بيتها متأخرة وتكتشف أنها نسيت مفاتيحها، فتتصل بفني أقفال في منتصف الليل.","lines":[{"speaker":"luna","es":"Buenas noches. Me he quedado fuera de casa y no tengo llaves.","ar":"مساء الخير. بقيت خارج البيت وليس معي مفاتيح."},{"speaker":"paco","es":"¿Dónde está ahora?","ar":"أين أنتِ الآن؟"},{"speaker":"luna","es":"En la puerta del edificio, en la calle Mayor. Necesito que venga alguien.","ar":"عند باب العمارة، في شارع مايور. أحتاج أن يأتي أحدهم."},{"speaker":"paco","es":"Puedo estar allí en media hora, pero esta noche la salida cuesta más.","ar":"يمكنني أن أكون هناك في نصف ساعة، لكن الخروج هذه الليلة يكلّف أكثر."},{"speaker":"luna","es":"¿Cuánto cuesta?","ar":"كم يكلّف؟"},{"speaker":"paco","es":"Cien euros, y si hay que cambiar la cerradura, aparte.","ar":"مئة يورو، وإن لزم تغيير القفل فذلك منفصل."},{"speaker":"luna","es":"Es mucho, pero no tengo otra opción. ¿Necesito algún documento?","ar":"هذا كثير، لكن ليس لديّ خيار آخر. هل أحتاج إلى وثيقة؟"},{"speaker":"paco","es":"Sí, el contrato de alquiler o el carné. Tengo que comprobar que la casa es suya.","ar":"نعم، عقد الإيجار أو الهوية. عليّ التأكد من أن البيت لكِ."},{"speaker":"luna","es":"Tengo el carné en el bolso. El contrato está dentro de casa.","ar":"بطاقتي في حقيبتي. أما العقد فهو داخل البيت."},{"speaker":"paco","es":"Con el carné es suficiente. ¿Tiene vecinos que puedan confirmarlo?","ar":"البطاقة تكفي. هل لديك جيران يمكنهم تأكيد ذلك؟"},{"speaker":"luna","es":"Sí, la vecina del segundo me conoce bien.","ar":"نعم، جارة الطابق الثاني تعرفني جيدًا."},{"speaker":"paco","es":"Perfecto. Estoy saliendo. No se mueva de la puerta.","ar":"ممتاز. أنا في الطريق. لا تتحركي من عند الباب."},{"speaker":"luna","es":"Aquí espero. Gracias por venir tan tarde.","ar":"سأنتظر هنا. شكرًا لقدومك في هذه الساعة المتأخرة."},{"speaker":"paco","es":"No se preocupe. Es mi trabajo.","ar":"لا تقلقي. هذا عملي."}],"questions":[{"q":"ما المشكلة؟","options":["نسيت لونا مفاتيحها وبقيت خارج البيت","أغلق الباب من الداخل","ضاعت حقيبتها"],"answer":"نسيت لونا مفاتيحها وبقيت خارج البيت","rationale":"قالت «Me he quedado fuera de casa y no tengo llaves»."},{"q":"كم تكلّف الزيارة ليلًا؟","options":["خمسون يورو","مئة يورو","مئة وخمسون يورو"],"answer":"مئة يورو","rationale":"قال «Cien euros»، أي مئة يورو."},{"q":"ماذا يحدث إن وجب تغيير القفل؟","options":["يُدفع مبلغ إضافي","الانتظار حتى الصباح","الاتصال بالشرطة"],"answer":"الاتصال بالشرطة","rationale":"قال «si hay que cambiar la cerradura, aparte»، أي مبلغ منفصل إضافي."},{"q":"ما الوثيقة التي معها؟","options":["عقد الإيجار","بطاقة الهوية","فاتورة الكهرباء"],"answer":"بطاقة الهوية","rationale":"قالت «Tengo el carné en el bolso»، أي بطاقة الهوية."},{"q":"لماذا يسأل الفني عن الجيران؟","options":["ليتأكد أن البيت لها","ليترك عندهم مفتاحًا","ليطلب منهم الدفع"],"answer":"ليتأكد أن البيت لها","rationale":"قال «¿Tiene vecinos que puedan confirmarlo?»، أي ليؤكد أن البيت لها."}]},{"id":"b1-bici-robada","level":"B1","title":"الدراجة المسروقة","desc":"تكتشف لونا أن دراجتها سُرقت من أمام العمارة، فتذهب إلى مركز الشرطة لتقديم شكوى.","lines":[{"speaker":"luna","es":"Buenos días. Quiero denunciar el robo de mi bicicleta.","ar":"صباح الخير. أريد الإبلاغ عن سرقة دراجتي."},{"speaker":"paco","es":"¿Cuándo ocurrió?","ar":"متى حدث ذلك؟"},{"speaker":"luna","es":"Anoche. La dejé atada a la barandilla del portal y esta mañana ya no estaba.","ar":"الليلة الماضية. ربطتها بدرابزين مدخل العمارة وهذا الصباح لم تكن هناك."},{"speaker":"paco","es":"¿Estaba cerrada con candado?","ar":"هل كانت مقفلة بقفل؟"},{"speaker":"luna","es":"Sí, con un candado de esos gruesos. Seguro que lo han cortado.","ar":"نعم، بقفل سميك من تلك. لا بد أنهم قطعوه."},{"speaker":"paco","es":"¿Tiene la factura de compra o el número de serie?","ar":"هل لديك فاتورة الشراء أو الرقم التسلسلي؟"},{"speaker":"luna","es":"La factura la tengo en casa. El número de serie no lo sé de memoria.","ar":"الفاتورة عندي في البيت. أما الرقم التسلسلي فلا أعرفه عن ظهر قلب."},{"speaker":"paco","es":"Con la factura es suficiente. ¿Ha avisado al seguro?","ar":"الفاتورة تكفي. هل أبلغتِ التأمين؟"},{"speaker":"luna","es":"No, primero quería poner la denuncia. ¿Sirve de algo?","ar":"لا، أردت أولًا تقديم الشكوى. هل تفيد بشيء؟"},{"speaker":"paco","es":"A veces sí. Si aparece la bicicleta, la llamamos. Y muchas compañías piden la denuncia para pagar.","ar":"أحيانًا نعم. إن ظهرت الدراجة نتصل بك. وكثير من الشركات تطلب الشكوى للدفع."},{"speaker":"luna","es":"Entiendo. ¿Tengo que pagar algo por la denuncia?","ar":"أفهم. هل عليّ أن أدفع شيئًا مقابل الشكوى؟"},{"speaker":"paco","es":"No, es gratis. Firme aquí y le doy una copia.","ar":"لا، إنها مجانية. وقّعي هنا وسأعطيك نسخة."},{"speaker":"luna","es":"Gracias. La próxima vez la dejaré dentro del portal.","ar":"شكرًا. في المرة القادمة سأتركها داخل مدخل العمارة."},{"speaker":"paco","es":"Buena idea. Y use un candado mejor.","ar":"فكرة جيدة. واستخدمي قفلًا أفضل."}],"questions":[{"q":"ماذا تريد لونا أن تفعل؟","options":["أن تبلغ عن سرقة دراجتها","أن تشتري دراجة جديدة","أن تسأل عن دراجة ضائعة"],"answer":"أن تبلغ عن سرقة دراجتها","rationale":"قالت «Quiero denunciar el robo de mi bicicleta»."},{"q":"أين كانت الدراجة؟","options":["داخل البيت","أمام مدخل العمارة","في محطة القطار"],"answer":"أمام مدخل العمارة","rationale":"قالت «La dejé atada a la barandilla del portal»."},{"q":"ماذا يطلب الموظف لإثبات الملكية؟","options":["صورًا للدراجة","شاهدًا","فاتورة الشراء"],"answer":"فاتورة الشراء","rationale":"قال «¿Tiene la factura de compra o el número de serie?» ثم «Con la factura es suficiente»."},{"q":"ما فائدة الشكوى؟","options":["لا تفيد بشيء","قد يتصلون بها إن ظهرت الدراجة، وكثير من شركات التأمين تطلبها","تضمن استعادة الدراجة"],"answer":"قد يتصلون بها إن ظهرت الدراجة، وكثير من شركات التأمين تطلبها","rationale":"قال «Si aparece la bicicleta, la llamamos» وأضاف أن كثيرًا من الشركات تطلب الشكوى."},{"q":"كم تكلّف الشكوى؟","options":["مجانية","عشرون يورو","خمسون يورو"],"answer":"مجانية","rationale":"قال «No, es gratis»، أي مجانية."}]},{"id":"b1-referencia-de-trabajo","level":"B1","title":"طلب توصية من مدير سابق","desc":"تحتاج لونا إلى توصية من مديرها السابق لوظيفة جديدة، فتتصل به بعد ثلاث سنوات.","lines":[{"speaker":"luna","es":"Hola, señor Ruiz. Soy Luna, trabajé en su equipo hace tres años.","ar":"مرحبًا سيد رويز. أنا لونا، عملت في فريقك قبل ثلاث سنوات."},{"speaker":"paco","es":"Luna, claro que me acuerdo. ¿Cómo estás?","ar":"لونا، بالطبع أتذكرك. كيف حالك؟"},{"speaker":"luna","es":"Bien, gracias. Le llamo porque estoy buscando trabajo y me piden una recomendación.","ar":"بخير، شكرًا. أتصل بك لأنني أبحث عن عمل ويطلبون مني توصية."},{"speaker":"paco","es":"¿Y quieres que la escriba yo?","ar":"وتريدين أن أكتبها أنا؟"},{"speaker":"luna","es":"Si no le importa. Trabajamos juntos dos años y conoce bien mi trabajo.","ar":"إن لم يكن يزعجك. عملنا معًا سنتين وتعلم جيدًا عملي."},{"speaker":"paco","es":"Me acuerdo de que llevabas muy bien los proyectos difíciles.","ar":"أتذكر أنك كنت تديرين المشاريع الصعبة جيدًا."},{"speaker":"luna","es":"Gracias. La empresa nueva pide una carta firmada y un teléfono de contacto.","ar":"شكرًا. الشركة الجديدة تطلب خطابًا موقّعًا ورقم هاتف للتواصل."},{"speaker":"paco","es":"Puedo escribirla esta semana. ¿Para cuándo la necesitas?","ar":"يمكنني كتابتها هذا الأسبوع. متى تحتاجينها؟"},{"speaker":"luna","es":"Antes del viernes, si es posible. La entrevista es el lunes.","ar":"قبل الجمعة إن أمكن. المقابلة يوم الاثنين."},{"speaker":"paco","es":"No hay problema. ¿Quieres que mencione también el curso de formación?","ar":"لا مشكلة. هل تريدين أن أذكر أيضًا دورة التدريب؟"},{"speaker":"luna","es":"Sí, por favor. Fue importante para mí.","ar":"نعم، من فضلك. كانت مهمة بالنسبة لي."},{"speaker":"paco","es":"De acuerdo. Envíame por correo los datos del puesto y lo preparo.","ar":"حسنًا. أرسلي لي بالبريد بيانات الوظيفة وأنا أعدّه."},{"speaker":"luna","es":"Se lo mando hoy mismo. Muchas gracias, de verdad.","ar":"سأرسله لك اليوم نفسه. شكرًا جزيلًا، حقًا."},{"speaker":"paco","es":"No hay de qué. Me alegra saber de ti.","ar":"لا شكر على واجب. يسعدني أن أعرف أخبارك."}],"questions":[{"q":"لماذا تتصل لونا بالسيد رويز؟","options":["لتطلب منه عملًا","لتطلب منه توصية","لتشكره على هدية"],"answer":"لتطلب منه توصية","rationale":"قالت «estoy buscando trabajo y me piden una recomendación»."},{"q":"ما علاقة السيد رويز بلونا؟","options":["مديرها السابق","جارها","زميلها في الجامعة"],"answer":"مديرها السابق","rationale":"قالت «trabajé en su equipo hace tres años»."},{"q":"ماذا تطلب الشركة الجديدة؟","options":["شهادة جامعية","رسالة من زملاء","خطابًا موقّعًا ورقم هاتف للتواصل"],"answer":"خطابًا موقّعًا ورقم هاتف للتواصل","rationale":"قالت «La empresa nueva pide una carta firmada y un teléfono de contacto»."},{"q":"متى تحتاج لونا التوصية؟","options":["يوم الاثنين","قبل الجمعة","بعد المقابلة"],"answer":"قبل الجمعة","rationale":"قالت «Antes del viernes, si es posible. La entrevista es el lunes»."},{"q":"ما الذي يقترح السيد رويز ذكره أيضًا؟","options":["الراتب السابق","عدد أيام الإجازة","دورة التدريب"],"answer":"دورة التدريب","rationale":"قال «¿Quieres que mencione también el curso de formación?»."}]},{"id":"b1-coche-de-alquiler","level":"B1","title":"خدش في سيارة مستأجرة","desc":"تعيد لونا سيارة مستأجرة إلى المكتب، فيقول الموظف إن فيها ضربة ويطلب مبلغًا إضافيًا.","lines":[{"speaker":"luna","es":"Buenas tardes. Vengo a devolver el coche. Todo ha ido bien.","ar":"مساء الخير. جئت لأعيد السيارة. كل شيء سار على ما يرام."},{"speaker":"paco","es":"Déjeme ver. Un momento, por favor.","ar":"اسمحي لي أن أرى. لحظة من فضلك."},{"speaker":"paco","es":"Aquí hay un golpe en la puerta derecha. ¿Lo ha visto?","ar":"هنا ضربة في الباب الأيمن. هل رأيتِها؟"},{"speaker":"luna","es":"No. Cuando lo alquilé no estaba. Estoy segura.","ar":"لا. لم تكن موجودة عندما استأجرتها. أنا متأكدة."},{"speaker":"paco","es":"En el contrato pone que el coche estaba sin daños.","ar":"في العقد مكتوب أن السيارة كانت بلا أضرار."},{"speaker":"luna","es":"Ya, pero yo no lo he golpeado. Solo lo he aparcado en la calle.","ar":"أعرف، لكنني لم أضربها. لقد أوقفتها في الشارع فقط."},{"speaker":"paco","es":"Entonces alguien lo ha golpeado mientras estaba aparcado.","ar":"إذن أحدهم ضربها وهي متوقفة."},{"speaker":"luna","es":"¿Y tengo que pagarlo yo? Yo contraté el seguro completo.","ar":"وعليّ أن أدفع أنا؟ لقد تعاقدت على التأمين الشامل."},{"speaker":"paco","es":"Con el seguro completo, usted paga solo una parte. Vamos a ver la cantidad.","ar":"مع التأمين الشامل، تدفعين جزءًا فقط. لنرَ المبلغ."},{"speaker":"luna","es":"Quiero ver las fotos que hice antes de salir con el coche.","ar":"أريد أن أرى الصور التي التقطتها قبل الخروج بالسيارة."},{"speaker":"paco","es":"Perfecto. Si el golpe ya estaba, no paga nada.","ar":"ممتاز. إن كانت الضربة موجودة سابقًا فلن تدفعي شيئًا."},{"speaker":"luna","es":"Aquí están. Mire la fecha: son del día que recogí el coche.","ar":"ها هي. انظر إلى التاريخ: إنها من يوم استلمت السيارة."},{"speaker":"paco","es":"Tiene razón. El golpe ya estaba. Le pido disculpas por la molestia.","ar":"أنتِ على حق. الضربة كانت موجودة سابقًا. أعتذر عن الإزعاج."},{"speaker":"luna","es":"Gracias. La próxima vez haré más fotos todavía.","ar":"شكرًا. في المرة القادمة سألتقط صورًا أكثر."}],"questions":[{"q":"ماذا يقول الموظف عن السيارة؟","options":["إن فيها ضربة في الباب الأيمن","إنها تحتاج إلى بنزين","إنها متأخرة عن الموعد"],"answer":"إن فيها ضربة في الباب الأيمن","rationale":"قال «Aquí hay un golpe en la puerta derecha»."},{"q":"ماذا تقول لونا؟","options":["إنها هي من أحدث الضربة","إن الضربة لم تكن موجودة عندما استأجرت السيارة","إنها لا ترى أي ضربة"],"answer":"إن الضربة لم تكن موجودة عندما استأجرت السيارة","rationale":"قالت «Cuando lo alquilé no estaba. Estoy segura»."},{"q":"ماذا تعاقدت لونا؟","options":["تأمينًا ضد السرقة فقط","من دون تأمين","تأمينًا شاملًا"],"answer":"تأمينًا شاملًا","rationale":"قالت «Yo contraté el seguro completo»، أي التأمين الشامل."},{"q":"ما الذي يثبت أن الضربة قديمة؟","options":["شهادة شاهد","الصور التي التقطتها قبل الخروج بالسيارة","تقرير الشرطة"],"answer":"الصور التي التقطتها قبل الخروج بالسيارة","rationale":"قالت «Quiero ver las fotos que hice antes de salir con el coche»."},{"q":"كيف ينتهي الأمر؟","options":["تدفع لونا المبلغ كاملًا","تدفع لونا جزءًا من المبلغ","يعتذر الموظف ولا تدفع شيئًا"],"answer":"يعتذر الموظف ولا تدفع شيئًا","rationale":"قال «Tiene razón. El golpe ya estaba. Le pido disculpas»."}]},{"id":"b2-vuelo-cancelado","level":"B2","title":"رحلة ملغاة في المطار","desc":"تُلغى رحلة لونا في اللحظة الأخيرة قبل حفل زفاف، فتحاول مع موظف الشركة الحصول على رحلة بديلة وتعويض.","lines":[{"speaker":"luna","es":"Buenas tardes. Mi vuelo a Roma de las seis está cancelado y nadie me ha avisado.","ar":"مساء الخير. رحلتي إلى روما في السادسة ملغاة ولم يبلغني أحد."},{"speaker":"paco","es":"Lo siento mucho. Ha sido por un problema técnico del avión.","ar":"آسف جدًا. كان السبب مشكلة فنية في الطائرة."},{"speaker":"luna","es":"Tengo una boda el sábado. Necesito llegar mañana como sea.","ar":"لديّ حفل زفاف يوم السبت. أحتاج أن أصل غدًا بأي طريقة."},{"speaker":"paco","es":"Puedo ofrecerle un vuelo mañana a primera hora, con escala en Barcelona.","ar":"يمكنني أن أعرض عليك رحلة غدًا في أول النهار، مع توقف في برشلونة."},{"speaker":"luna","es":"¿A qué hora llega a Roma?","ar":"في أي ساعة تصل إلى روما؟"},{"speaker":"paco","es":"A las dos de la tarde, así que llegará a tiempo para la boda.","ar":"في الثانية بعد الظهر، لذا ستصلين في الوقت المناسب للزفاف."},{"speaker":"luna","es":"De acuerdo, pero quiero saber qué derechos tengo. He leído que me corresponde una compensación.","ar":"حسنًا، لكنني أريد أن أعرف ما حقوقي. قرأت أن لي تعويضًا."},{"speaker":"paco","es":"Sí, en este caso le corresponde, porque no le avisamos con tiempo.","ar":"نعم، في هذه الحالة يحق لك، لأننا لم نبلغك في الوقت المناسب."},{"speaker":"luna","es":"¿Y cómo la pido? ¿La tramitan ustedes o tengo que hacerlo yo?","ar":"وكيف أطلبها؟ هل تعالجونها أنتم أم عليّ أن أفعل ذلك؟"},{"speaker":"paco","es":"Puede pedirla por la página web. También le pagamos el hotel de esta noche y la cena.","ar":"يمكنك طلبها عبر الموقع. وسندفع لك أيضًا فندق هذه الليلة والعشاء."},{"speaker":"luna","es":"Eso esperaba, porque no tengo dónde dormir.","ar":"هذا ما كنت أتمناه، لأنني لا أملك مكانًا أنام فيه."},{"speaker":"paco","es":"Le doy un papel con el número de reserva del hotel. Está cerca del aeropuerto.","ar":"سأعطيك ورقة برقم حجز الفندق. إنه قريب من المطار."},{"speaker":"luna","es":"Muy bien. ¿Y si el vuelo de mañana también se cancela?","ar":"جيد جدًا. وإن أُلغيت رحلة الغد أيضًا؟"},{"speaker":"paco","es":"Entonces le buscaríamos otra compañía. No la dejaremos aquí.","ar":"في هذه الحالة سنبحث لك عن شركة أخرى. لن نتركك هنا."}],"questions":[{"q":"لماذا أُلغيت الرحلة؟","options":["بسبب الطقس","بسبب مشكلة فنية في الطائرة","بسبب إضراب في المطار"],"answer":"بسبب مشكلة فنية في الطائرة","rationale":"قال الموظف «Ha sido por un problema técnico del avión»."},{"q":"لماذا تحتاج لونا أن تصل غدًا؟","options":["لأن عندها حفل زفاف يوم السبت","لأن عندها اجتماع عمل","لأن تذكرتها تنتهي"],"answer":"لأن عندها حفل زفاف يوم السبت","rationale":"قالت «Tengo una boda el sábado. Necesito llegar mañana como sea»."},{"q":"ما الرحلة البديلة التي يعرضها الموظف؟","options":["رحلة غدًا في أول النهار مع توقف في برشلونة","رحلة الليلة مباشرة","رحلة بعد يومين"],"answer":"رحلة غدًا في أول النهار مع توقف في برشلونة","rationale":"قال «un vuelo mañana a primera hora, con escala en Barcelona»."},{"q":"لماذا يحق للونا التعويض؟","options":["لأن الرحلة كانت دولية","لأنها مسافرة دائمًا","لأنهم لم يبلغوها في الوقت المناسب"],"answer":"لأنهم لم يبلغوها في الوقت المناسب","rationale":"قال «le corresponde, porque no le avisamos con tiempo»."},{"q":"ماذا تدفع الشركة إضافة إلى التعويض؟","options":["تذكرة القطار","الفندق والعشاء","سيارة مستأجرة"],"answer":"الفندق والعشاء","rationale":"قال «También le pagamos el hotel de esta noche y la cena»."},{"q":"ماذا سيحدث إن أُلغيت رحلة الغد؟","options":["ستبقى لونا في المطار","ستلغي السفر","ستبحث الشركة لها عن شركة أخرى"],"answer":"ستبحث الشركة لها عن شركة أخرى","rationale":"قال «Entonces le buscaríamos otra compañía»."}]},{"id":"b2-prestamo-a-un-amigo","level":"B2","title":"صديق يطلب قرضًا","desc":"يطلب صديق لونا مبلغًا كبيرًا على سبيل القرض، فتحاول الموازنة بين الصداقة والحذر.","lines":[{"speaker":"paco","es":"Luna, necesito hablarte de algo y me da vergüenza.","ar":"لونا، أحتاج أن أتحدث معك في أمر ويخجلني."},{"speaker":"luna","es":"Dime, Paco. ¿Qué pasa?","ar":"قل لي باكو. ماذا حدث؟"},{"speaker":"paco","es":"Me han pedido dejar el piso donde vivo y necesito tres mil euros para la entrada de otro.","ar":"طلبوا مني مغادرة الشقة التي أسكنها وأحتاج ثلاثة آلاف يورو لمقدم شقة أخرى."},{"speaker":"luna","es":"¿Tres mil? Es mucho dinero.","ar":"ثلاثة آلاف؟ هذا مبلغ كبير."},{"speaker":"paco","es":"Lo sé. Te lo devolvería en un año, poco a poco. Te lo prometo.","ar":"أعرف. سأعيده إليك في سنة، قليلًا قليلًا. أعدك."},{"speaker":"luna","es":"No es que no quiera ayudarte, pero nunca he prestado una cantidad así.","ar":"ليس أنني لا أريد مساعدتك، لكنني لم أقرض مبلغًا كهذا من قبل."},{"speaker":"paco","es":"Lo entiendo. Si no puedes, lo entenderé de verdad.","ar":"أفهم ذلك. إن لم تستطيعي، سأفهم حقًا."},{"speaker":"luna","es":"Déjame pensar. ¿Tienes trabajo fijo ahora?","ar":"دعني أفكر. هل لديك عمل ثابت الآن؟"},{"speaker":"paco","es":"Sí, en el almacén. Llevo allí ocho meses.","ar":"نعم، في المخزن. لي هناك ثمانية أشهر."},{"speaker":"luna","es":"Entonces puedo prestarte una parte, no los tres mil. Y quiero un papel firmado.","ar":"إذن يمكنني أن أقرضك جزءًا، لا الثلاثة آلاف. وأريد ورقة موقّعة."},{"speaker":"paco","es":"Claro, lo que quieras. ¿Qué cantidad puedes?","ar":"بالطبع، كما تريدين. ما المبلغ الذي تستطيعين؟"},{"speaker":"luna","es":"Mil quinientos, y me los devuelves en diez meses. Sin prisa, pero sin olvidarlo.","ar":"ألف وخمس مئة، وتعيدها لي في عشرة أشهر. بلا عجلة، لكن دون أن تنسى."},{"speaker":"paco","es":"Me parece justo. Gracias, de verdad. No sabes lo que significa para mí.","ar":"يبدو ذلك عادلًا. شكرًا، حقًا. لا تعرفين ماذا يعني هذا لي."},{"speaker":"luna","es":"Solo espero que no tengamos que hablar de esto otra vez.","ar":"آمل فقط ألا نضطر إلى الحديث في هذا مرة أخرى."}],"questions":[{"q":"ماذا يطلب باكو من لونا؟","options":["أن تساعده في الانتقال","أن تقرضه ثلاثة آلاف يورو","أن تسأل له عن شقة"],"answer":"أن تقرضه ثلاثة آلاف يورو","rationale":"قال «necesito tres mil euros para la entrada de otro»."},{"q":"لماذا يحتاج المال؟","options":["لأنه يجب أن يترك شقته ويحتاج مقدمًا لشقة أخرى","لأنه يريد شراء سيارة","لأنه مدين للبنك"],"answer":"لأنه يجب أن يترك شقته ويحتاج مقدمًا لشقة أخرى","rationale":"قال «Me han pedido dejar el piso donde vivo»."},{"q":"كيف يعد بإعادة المال؟","options":["دفعة واحدة بعد شهر","في سنة، قليلًا قليلًا","عندما يجد عملًا جديدًا"],"answer":"في سنة، قليلًا قليلًا","rationale":"قال «Te lo devolvería en un año, poco a poco»."},{"q":"ماذا تسأل لونا أولًا؟","options":["إن كان لديه عمل ثابت","إن كان قد سأل أحدًا آخر","إن كان قد وقّع عقدًا"],"answer":"إن كان لديه عمل ثابت","rationale":"قالت «¿Tienes trabajo fijo ahora?»."},{"q":"ماذا تقرر لونا؟","options":["تقرضه المبلغ كاملًا","ترفض تمامًا","تقرضه جزءًا بورقة موقّعة"],"answer":"تقرضه جزءًا بورقة موقّعة","rationale":"قالت «puedo prestarte una parte, no los tres mil. Y quiero un papel firmado»."},{"q":"على أي مبلغ ومدة يتفقان؟","options":["ألف وخمس مئة في عشرة أشهر","ثلاثة آلاف في سنة","ألف في ستة أشهر"],"answer":"ألف وخمس مئة في عشرة أشهر","rationale":"قالت «Mil quinientos, y me los devuelves en diez meses»."}]},{"id":"b2-vender-el-coche","level":"B2","title":"بيع السيارة المستعملة","desc":"تعرض لونا سيارتها القديمة للبيع، فيحاول المشتري خفض السعر ويريد الدفع على دفعتين.","lines":[{"speaker":"paco","es":"He visto el anuncio de tu coche. ¿Sigue disponible?","ar":"رأيت إعلان سيارتك. هل لا تزال متاحة؟"},{"speaker":"luna","es":"Sí, todavía no lo he vendido.","ar":"نعم، لم أبعها بعد."},{"speaker":"paco","es":"¿Cuántos kilómetros tiene?","ar":"كم عدد الكيلومترات التي قطعتها؟"},{"speaker":"luna","es":"Ciento veinte mil, más o menos. Pero está bien cuidado y las revisiones están al día.","ar":"مئة وعشرون ألفًا تقريبًا. لكنها مصانة جيدًا ومراجعاتها منتظمة."},{"speaker":"paco","es":"El precio del anuncio me parece alto. He visto coches parecidos más baratos.","ar":"سعر الإعلان يبدو لي مرتفعًا. رأيت سيارات مشابهة أرخص."},{"speaker":"luna","es":"Puedo bajar un poco, pero no mucho. Le he puesto neumáticos nuevos este año.","ar":"يمكنني أن أنزل قليلًا، لكن ليس كثيرًا. وضعت لها إطارات جديدة هذا العام."},{"speaker":"paco","es":"¿Aceptarías cuatro mil quinientos?","ar":"هل تقبلين أربعة آلاف وخمس مئة؟"},{"speaker":"luna","es":"Pedía cinco mil. Cuatro mil ochocientos es lo mínimo.","ar":"كنت أطلب خمسة آلاف. أربعة آلاف وثماني مئة هو الحد الأدنى."},{"speaker":"paco","es":"De acuerdo. Pero tengo que pagarte en dos veces: la mitad ahora y la otra mitad el mes que viene.","ar":"حسنًا. لكن عليّ أن أدفع لك على دفعتين: النصف الآن والنصف الآخر الشهر القادم."},{"speaker":"luna","es":"Eso no me convence. Si el coche cambia de dueño, el papeleo se hace una sola vez.","ar":"هذا لا يقنعني. إذا انتقلت ملكية السيارة، تُنجز الأوراق مرة واحدة فقط."},{"speaker":"paco","es":"Puedo dejarte una señal ahora y el resto cuando firmemos.","ar":"يمكنني أن أترك لك عربونًا الآن والباقي عندما نوقّع."},{"speaker":"luna","es":"Así está bien. ¿Puedes venir el jueves al taller para que lo revise un mecánico?","ar":"هكذا جيد. هل يمكنك أن تأتي يوم الخميس إلى الورشة ليفحصها ميكانيكي؟"},{"speaker":"paco","es":"Me parece razonable. Si todo está bien, cerramos el trato.","ar":"يبدو ذلك معقولًا. إن كان كل شيء على ما يرام، نُنهي الاتفاق."},{"speaker":"luna","es":"Perfecto. Te mando la dirección del taller.","ar":"ممتاز. سأرسل لك عنوان الورشة."}],"questions":[{"q":"كم عدد الكيلومترات التي قطعتها السيارة؟","options":["ثمانون ألفًا","مئة وعشرون ألفًا","مئتا ألف"],"answer":"مئة وعشرون ألفًا","rationale":"قالت «Ciento veinte mil, más o menos»."},{"q":"ما الذي يشتكي منه المشتري؟","options":["السعر مرتفع","السيارة قديمة جدًا","اللون لا يعجبه"],"answer":"السعر مرتفع","rationale":"قال «El precio del anuncio me parece alto»."},{"q":"ما آخر سعر تقبله لونا؟","options":["أربعة آلاف وخمس مئة","خمسة آلاف","أربعة آلاف وثماني مئة"],"answer":"أربعة آلاف وثماني مئة","rationale":"قالت «Cuatro mil ochocientos es lo mínimo»."},{"q":"كيف يريد المشتري أن يدفع؟","options":["على دفعتين","نقدًا كاملًا","بتحويل بنكي بعد شهر"],"answer":"على دفعتين","rationale":"قال «tengo que pagarte en dos veces»."},{"q":"لماذا ترفض لونا الدفع على دفعتين؟","options":["لأنها تحتاج المال كله","لأن الأوراق تُنجز مرة واحدة عند انتقال الملكية","لأنها لا تثق به"],"answer":"لأن الأوراق تُنجز مرة واحدة عند انتقال الملكية","rationale":"قالت «el papeleo se hace una sola vez»."},{"q":"ما الاتفاق النهائي؟","options":["عربون الآن والباقي عند التوقيع، بعد فحص السيارة","البيع فورًا بلا فحص","إلغاء البيع"],"answer":"عربون الآن والباقي عند التوقيع، بعد فحص السيارة","rationale":"قال «Puedo dejarte una señal ahora y el resto cuando firmemos»، ثم اتفقا على فحص السيارة يوم الخميس."}]},{"id":"b2-examen-de-espanol","level":"B2","title":"هل أتقدّم للامتحان؟","desc":"تسأل لونا معلّمها إن كانت مستعدة للامتحان الرسمي في اللغة الإسبانية، فيشرح لها ما ينتظرها.","lines":[{"speaker":"luna","es":"Profesor, quería preguntarle una cosa. Estoy pensando en presentarme al examen oficial de español.","ar":"أستاذ، أردت أن أسألك عن أمر. أفكر في التقدم للامتحان الرسمي للإسبانية."},{"speaker":"paco","es":"Me parece una buena idea. ¿Para cuándo sería?","ar":"أرى أنها فكرة جيدة. ومتى سيكون؟"},{"speaker":"luna","es":"La inscripción termina el viernes y el examen es en mayo.","ar":"التسجيل ينتهي يوم الجمعة والامتحان في مايو."},{"speaker":"paco","es":"Entonces tienes tres meses para prepararte. ¿Cómo te sientes con la expresión escrita?","ar":"إذن لديك ثلاثة أشهر للتحضير. كيف تشعرين مع التعبير الكتابي؟"},{"speaker":"luna","es":"Ahí es donde tengo más problemas. Hablo bastante bien, pero cuando escribo cometo muchos errores.","ar":"هناك مشكلتي الأكبر. أتحدث جيدًا إلى حد ما، لكنني أرتكب أخطاء كثيرة عندما أكتب."},{"speaker":"paco","es":"Eso se arregla con práctica. ¿Y la comprensión auditiva?","ar":"هذا يُحلّ بالتمرين. وماذا عن فهم المسموع؟"},{"speaker":"luna","es":"Me da miedo. A veces no entiendo nada cuando hablan rápido.","ar":"إنه يخيفني. أحيانًا لا أفهم شيئًا عندما يتحدثون بسرعة."},{"speaker":"paco","es":"En el examen hablan despacio y repiten dos veces. No es tan difícil como parece.","ar":"في الامتحان يتحدثون ببطء ويكررون مرتين. الأمر ليس صعبًا كما يبدو."},{"speaker":"luna","es":"¿Y si no lo apruebo? Habré gastado el dinero para nada.","ar":"وإن لم أنجح؟ سأكون قد أنفقت المال بلا فائدة."},{"speaker":"paco","es":"Aunque no lo apruebes, habrás practicado y sabrás en qué fallas. Puedes repetirlo en noviembre.","ar":"حتى إن لم تنجحي، ستكونين قد تمرّنت وعرفت أين تقصرين. يمكنك إعادته في نوفمبر."},{"speaker":"luna","es":"Tiene razón. ¿Me ayudaría a corregir mis textos una vez por semana?","ar":"أنت على حق. هل تساعدني في تصحيح نصوصي مرة في الأسبوع؟"},{"speaker":"paco","es":"Claro. Y te recomiendo que escribas un diario en español, aunque sea corto.","ar":"بالطبع. وأنصحك بأن تكتبي يوميات بالإسبانية، ولو كانت قصيرة."},{"speaker":"luna","es":"Voy a inscribirme hoy mismo antes de que se me olvide.","ar":"سأسجل اليوم نفسه قبل أن أنسى."},{"speaker":"paco","es":"Buena decisión. Y no te preocupes demasiado por el resultado.","ar":"قرار جيد. ولا تقلقي كثيرًا من النتيجة."}],"questions":[{"q":"ماذا تفكر لونا أن تفعل؟","options":["أن تترك الدراسة","أن تتقدم للامتحان الرسمي","أن تدرس في إسبانيا"],"answer":"أن تتقدم للامتحان الرسمي","rationale":"قالت «Estoy pensando en presentarme al examen oficial de español»."},{"q":"متى ينتهي التسجيل؟","options":["في مايو","في نوفمبر","يوم الجمعة"],"answer":"يوم الجمعة","rationale":"قالت «La inscripción termina el viernes»."},{"q":"أين مشكلتها الأكبر؟","options":["في فهم المسموع","في التعبير الكتابي","في القراءة"],"answer":"في التعبير الكتابي","rationale":"قالت «Ahí es donde tengo más problemas» بعد سؤال المعلّم عن التعبير الكتابي."},{"q":"لماذا يقلّل المعلّم من صعوبة فهم المسموع؟","options":["لأنها تسمع جيدًا","لأنهم يتحدثون ببطء ويكررون مرتين","لأنه لا يوجد فهم مسموع في الامتحان"],"answer":"لأنهم يتحدثون ببطء ويكررون مرتين","rationale":"قال «En el examen hablan despacio y repiten dos veces»."},{"q":"ماذا يمكنها أن تفعل إن لم تنجح؟","options":["أن تعيد الامتحان في نوفمبر","أن تستعيد المال","أن تنتقل إلى مستوى أعلى"],"answer":"أن تعيد الامتحان في نوفمبر","rationale":"قال «Puedes repetirlo en noviembre»."},{"q":"بماذا ينصحها المعلّم؟","options":["بأن تدرس كل يوم ساعتين","بأن تقرأ الصحف","بأن تكتب يوميات بالإسبانية"],"answer":"بأن تكتب يوميات بالإسبانية","rationale":"قال «te recomiendo que escribas un diario en español»."}]},{"id":"b2-humedad-en-el-piso","level":"B2","title":"رطوبة في الشقة","desc":"تكتشف لونا رطوبة في جدار غرفة النوم، فتطالب صاحب الشقة بإصلاحها وبخصم من الإيجار.","lines":[{"speaker":"luna","es":"Buenos días. Le llamo porque ha aparecido humedad en el dormitorio.","ar":"صباح الخير. أتصل بك لأنه ظهرت رطوبة في غرفة النوم."},{"speaker":"paco","es":"¿Humedad? ¿Está segura de que no es una gotera pequeña?","ar":"رطوبة؟ هل أنت متأكدة أنها ليست تسربًا صغيرًا؟"},{"speaker":"luna","es":"Es una mancha grande en la pared y la ropa del armario huele mal.","ar":"إنها بقعة كبيرة على الحائط وملابس الخزانة رائحتها سيئة."},{"speaker":"paco","es":"Puede que el problema venga de la terraza del vecino de arriba.","ar":"قد تكون المشكلة قادمة من شرفة الجار في الأعلى."},{"speaker":"luna","es":"No lo sé, pero tiene que venir alguien a mirarlo. Llevo dos semanas esperando.","ar":"لا أعرف، لكن يجب أن يأتي أحدهم ليراه. أنتظر منذ أسبوعين."},{"speaker":"paco","es":"Le mandé un mensaje la semana pasada y no me contestó.","ar":"أرسلت لك رسالة الأسبوع الماضي ولم تردّي."},{"speaker":"luna","es":"No me llegó nada. Revise el número, por favor.","ar":"لم يصلني شيء. تحقق من الرقم، من فضلك."},{"speaker":"paco","es":"Tiene razón, lo he enviado a un número antiguo. Le pido disculpas.","ar":"أنت على حق، أرسلتها إلى رقم قديم. أعتذر."},{"speaker":"luna","es":"De acuerdo. ¿Cuándo puede venir un técnico?","ar":"حسنًا. متى يمكن أن يأتي فني؟"},{"speaker":"paco","es":"El jueves por la mañana. Si hay que romper la pared, tardará dos o tres días.","ar":"الخميس صباحًا. إن لزم كسر الحائط، سيستغرق الأمر يومين أو ثلاثة."},{"speaker":"luna","es":"Y mientras tanto, ¿puedo pagar menos de alquiler? La habitación no se puede usar.","ar":"وفي هذه الأثناء، هل يمكنني أن أدفع إيجارًا أقل؟ الغرفة لا يمكن استخدامها."},{"speaker":"paco","es":"Vamos a ver el informe del técnico. Si el problema es del edificio, le descontamos esos días.","ar":"لنرَ تقرير الفني. إن كانت المشكلة في المبنى، سنخصم لك تلك الأيام."},{"speaker":"luna","es":"Me parece justo. Le mando las fotos por correo ahora mismo.","ar":"يبدو ذلك عادلًا. سأرسل لك الصور بالبريد الآن."},{"speaker":"paco","es":"Perfecto. Y si empeora, avíseme enseguida.","ar":"ممتاز. وإن ساءت الحال، أبلغيني فورًا."}],"questions":[{"q":"ما المشكلة في الشقة؟","options":["تسرب في المطبخ","رطوبة في غرفة النوم","نافذة مكسورة"],"answer":"رطوبة في غرفة النوم","rationale":"قالت «ha aparecido humedad en el dormitorio»."},{"q":"من أين يعتقد صاحب الشقة أن المشكلة؟","options":["من أنابيب الحمام","من السطح","من شرفة الجار في الأعلى"],"answer":"من شرفة الجار في الأعلى","rationale":"قال «Puede que el problema venga de la terraza del vecino de arriba»."},{"q":"لماذا لم يصل شيء إلى لونا؟","options":["لأن هاتفها مغلق","لأنه أرسل الرسالة إلى رقم قديم","لأنه لم يرسل شيئًا"],"answer":"لأنه أرسل الرسالة إلى رقم قديم","rationale":"قال «lo he enviado a un número antiguo»."},{"q":"متى يأتي الفني؟","options":["الخميس صباحًا","الجمعة مساءً","الأسبوع القادم"],"answer":"الخميس صباحًا","rationale":"قال «El jueves por la mañana»."},{"q":"ماذا تطلب لونا بخصوص الإيجار؟","options":["أن يلغى الإيجار كله","أن تدفع أقل ما دامت الغرفة غير صالحة","أن يُصلح المبنى على حسابها"],"answer":"أن تدفع أقل ما دامت الغرفة غير صالحة","rationale":"قالت «¿puedo pagar menos de alquiler? La habitación no se puede usar»."},{"q":"على أي أساس يعدها بالخصم؟","options":["على أساس صورها","على أساس شهادة الجار","على أساس تقرير الفني"],"answer":"على أساس تقرير الفني","rationale":"قال «Vamos a ver el informe del técnico»."}]}].map(a=>({...a,questions:a.questions.map(e=>({...e,answer:e.options.indexOf(e.answer)}))})));
